/* 名篇译文 / 赏析 / 创作背景（手工编校 + docx 素材并入，持续扩充）
 * 键: "标题|作者"（课堂页按标题全等→互含模糊匹配）
 * y: 白话译文  s: 作品赏析  b: 创作背景
 */
window.POEM_NOTES = {
  "关雎|佚名": {
    y: "雎鸠鸟在河中小洲上关关和鸣。文静美好的姑娘，是君子理想的伴侣。长短不齐的荇菜，她左右采摘；醒着睡着都在思念她，翻来覆去难以入眠。",
    s: "《诗经》开篇之作。以雎鸠和鸣起兴，引出君子对淑女的爱慕，情感真挚而克制，「乐而不淫，哀而不伤」，奠定了中国爱情诗的基调。",
    b: "出自《诗经·周南》，是西周初年至春秋中叶的民间乐歌，后经孔子删订列入「诗三百」。"
  },
  "蒹葭|佚名": {
    y: "芦苇苍苍，白露成霜。我思念的那个人，在河水的另一方。逆流而上去寻她，道路险阻又漫长；顺流而下去寻她，她仿佛就在水中央。",
    s: "全诗三章复沓，营造出水雾迷茫、可望而不可即的意境。「伊人」究竟是谁——爱人、理想还是道——千百年来引人无限遐想，是含蓄美的极致。",
    b: "出自《诗经·秦风》，春秋时期流传于今陕西一带的民歌。"
  },
  "观沧海|曹操": {
    y: "东行登上碣石山，眺望苍茫的大海。海水浩荡，山岛耸立；树木丛生，百草丰茂。秋风吹来，巨浪涌起。日月星辰，仿佛都从这海中运行升起。",
    s: "中国现存第一首完整的山水诗。曹操以大海自况，吞吐日月、包蕴星汉的气象，正是他囊括天下的胸襟写照。",
    b: "建安十二年（207年）曹操北征乌桓，得胜回师途经碣石山时所作，是组诗《步出夏门行》的首章。"
  },
  "龟虽寿|曹操": {
    y: "神龟虽能长寿，终有死亡之时；腾蛇虽能乘雾，终究化为土灰。年老的千里马伏在马槽旁，雄心仍在千里驰骋；有志之士即使到了晚年，壮志也不会消沉。",
    s: "「老骥伏枥，志在千里」成为千古名言。诗人不服老、不信命，把生命的长度交给天，把生命的价值握在自己手里，慷慨激昂。",
    b: "写于北征乌桓之后，曹操时年五十三岁，正值事业巅峰却已感到岁月紧迫。"
  },
  "饮酒·其五|陶渊明": {
    y: "在尘世中建屋居住，却听不到车马的喧闹。为何能如此？心远离了世俗，居所自然偏远。东篱下采菊，悠然望见南山。山气日夕美好，飞鸟结伴归还，其中自有真意，想要分辨却已忘了言语。",
    s: "「采菊东篱下，悠然见南山」是田园诗的巅峰意象。物我两忘、得意忘言，把隐居生活的闲适与人生真谛融为一炉。",
    b: "陶渊明辞去彭泽县令后归隐田园，《饮酒》组诗二十首写于归隐之后，此为其五。"
  },
  "木兰诗|佚名": {
    y: "织布声一声接一声，木兰对着门织布，听不见机杼声，只听见她的叹息。原来可汗大点兵，父亲在名册上，木兰决定女扮男装、替父从军。十二年后凯旋，她谢绝高官，只求还乡，脱下战袍重着女儿装，同行伙伴这才惊觉：木兰竟是女郎。",
    s: "北朝民歌的压卷之作，与《孔雀东南飞》并称「乐府双璧」。详写战前准备与战后还乡，略写十年征战，剪裁大胆；木兰既是英雄又是普通女儿，形象亲切丰满。",
    b: "产生于北朝时期，记录了北方民族尚武的社会风气，「安能辨我是雄雌」成为挑战性别成见的千古一问。"
  },
  "长歌行|佚名": {
    y: "园中葵菜青青，朝露等待阳光晒干。春天把恩惠洒遍大地，万物生机焕发。常怕秋天来到，花叶枯黄衰败。百川东流入海，何时能再西归？年少时不努力，年老只能空自悲伤。",
    s: "由园中葵起兴，经四季流转、百川东去，自然引出「少壮不努力，老大徒伤悲」的千古劝诫，形象与哲理浑然一体。",
    b: "汉乐府民歌，属《相和歌辞》，是汉代无名氏作品。"
  },
  "送杜少府之任蜀州|王勃": {
    y: "三秦之地拱卫着长安，遥望蜀地，风烟渺茫。与你离别，同是宦游之人。四海之内有知心朋友，即使远在天边也如近邻。不要在岔路口像小儿女一样泪湿衣巾。",
    s: "一扫送别诗的悲切，「海内存知己，天涯若比邻」以豁达的胸襟写友情，境界阔大，成为送别诗的千古绝唱。",
    b: "王勃在长安任职时，送友人杜某赴蜀州任县尉所作，是初唐五律的成熟之作。"
  },
  "登幽州台歌|陈子昂": {
    y: "向前看不见古代的贤君，向后望不到后世的明主。想到天地悠悠无穷无尽，不禁独自悲伤，潸然泪下。",
    s: "仅二十二个字，把个人遭际放到无穷的时间与空间里对照，孤独感惊天动地。语言苍劲奔放，一扫齐梁绮靡诗风。",
    b: "陈子昂随武攸宜北征契丹，屡献奇计不被采纳，反遭贬斥，登蓟北楼（幽州台）慨然作歌。"
  },
  "次北固山下|王湾": {
    y: "行舟于青山绿水之间，潮水涨满，江面开阔，顺风行船，船帆高悬。海上的太阳在残夜里升起，江上的新春闯入旧年。家书何处送达？希望北归的大雁捎到洛阳。",
    s: "「海日生残夜，江春入旧年」蕴含新旧交替的自然理趣，气象恢宏，被宰相张说题于政事堂，作为诗文的典范。",
    b: "王湾进士及第前漫游江南，途经镇江北固山时触景生情而作。"
  },
  "使至塞上|王维": {
    y: "轻车简从出使边塞，途经居延。如飘飞的蓬草出了汉塞，如北归的大雁飞入胡天。大漠中一缕孤烟笔直上升，黄河上一轮落日浑圆。在萧关遇到侦察骑兵，得知都护还在前线。",
    s: "「大漠孤烟直，长河落日圆」以几何般简练的线条勾勒出塞外奇景，被王国维称为「千古壮观」，诗中有画的典范。",
    b: "开元二十五年，王维以监察御史身份奉使凉州，慰问河西节度副大使崔希逸，此诗写于赴边途中。"
  },
  "山居秋暝|王维": {
    y: "空山新雨过后，秋意初凉。明月照在松林间，清泉在石上流淌。竹林喧响是洗衣女子归来，莲叶摇动是渔舟顺流而下。春日的芳华任它消逝，秋天的山中自可久留。",
    s: "「明月松间照，清泉石上流」动静相生、光影交错，构成一幅有声有色的山居秋夜图，寄托了诗人高洁的情怀与归隐的志趣。",
    b: "王维晚年隐居辋川别墅期间所作，是他山水田园诗的代表作。"
  },
  "九月九日忆山东兄弟|王维": {
    y: "独自在异乡做客，每逢佳节就加倍思念亲人。遥想兄弟们今日登高插茱萸时，会发现少了我一个人。",
    s: "「每逢佳节倍思亲」道尽了天下游子的共同心事。后两句不直写自己思亲，而是想象兄弟们登高时发现缺少自己，曲折见情，更为动人。",
    b: "王维十七岁时客居长安，适逢九九重阳节，思念蒲州（今山西永济）的兄弟而作。"
  },
  "静夜思|李白": {
    y: "明亮的月光洒在床前，地上仿佛铺了一层白霜。抬头仰望天上的明月，低头思念远方的故乡。",
    s: "二十个字，一个举头一个低头，把千古游子共通的月夜乡愁写得自然天成。明白如话却意境深远，是传唱度最高的唐诗。",
    b: "作于唐玄宗开元十四年，李白二十六岁旅居扬州旅舍，秋夜望月思乡。"
  },
  "望庐山瀑布|李白": {
    y: "阳光照耀香炉峰升起紫色云烟，远远望去瀑布像长河悬挂在山前。飞流直下三千尺，让人怀疑是银河从九天倾泻而下。",
    s: "「飞流直下三千尺，疑是银河落九天」以极度夸张和瑰丽想象写瀑布气势，是李白浪漫主义的标志性画面。",
    b: "李白漫游庐山时所作，共两首，这是第二首七言绝句。"
  },
  "早发白帝城|李白": {
    y: "清晨辞别彩云缭绕的白帝城，千里之外的江陵一天就可到达。两岸猿声还在耳边不停啼叫，轻快的小舟已穿过万重青山。",
    s: "全诗节奏如江水奔流，「轻舟已过万重山」既是写实又暗喻劫后余生的畅快，景中寓情，快人快语。",
    b: "乾元二年李白因永王李璘案流放夜郎，行至白帝城遇赦东归，惊喜交加写下此诗。"
  },
  "黄鹤楼送孟浩然之广陵|李白": {
    y: "老朋友在西边的黄鹤楼向我告别，在烟花三月的美好时节东下扬州。孤帆的影子渐渐消失在碧空尽头，只看见长江水向天边奔流。",
    s: "不写离愁写目送：帆影消失后仍久久伫立，眼中只剩长江天际流。深情全部藏在「孤帆远影碧空尽」的画面里。",
    b: "开元年间，李白在黄鹤楼送别比他年长十二岁的诗友孟浩然前往扬州，时二人交谊正笃。"
  },
  "望天门山|李白": {
    y: "天门山被长江从中劈开，碧绿的江水到此回旋澎湃。两岸青山相对耸立，一片孤帆从日边驶来。",
    s: "山因水而开，水因山而回，山水相映成势。末句孤帆远来，为壮丽的山水画卷点上灵动一笔。",
    b: "开元十三年，二十五岁的李白初出巴蜀，乘船东下途经天门山，豪情满怀而作。"
  },
  "闻王昌龄左迁龙标遥有此寄|李白": {
    y: "杨花落尽、杜鹃哀啼的时节，听说你被贬龙标，要跋涉过五溪。我把满腔愁心托付给明月，让它随风伴你一直到夜郎以西。",
    s: "「我寄愁心与明月，随君直到夜郎西」——明月本无情，诗人偏要它做信使，想象奇绝而情真意切。",
    b: "王昌龄因「不护细行」被贬龙标县尉，李白闻讯写下此诗遥寄同情与慰藉。"
  },
  "行路难|李白": {
    y: "金杯美酒、玉盘珍馐摆在面前，我却放下杯筷无心下咽。想渡黄河冰封塞川，想登太行大雪满山。闲来在碧溪上垂钓，忽又梦见乘船经过日月旁边。行路难啊，多歧路，如今身在何处？总有一天我要乘长风破万里浪，高挂云帆横渡沧海！",
    s: "从停杯投箸的苦闷到直挂云帆的呐喊，情感的跌宕转折一气呵成。「长风破浪会有时，直挂云帆济沧海」成为逆境中自我激励的第一名句。",
    b: "天宝三载，李白被唐玄宗「赐金放还」，离京前朋友设宴饯行，愤懑与希望交织而作。"
  },
  "望岳|杜甫": {
    y: "泰山究竟如何雄伟？走出齐鲁大地依然可见它青翠的峰峦。大自然把神奇秀丽都赋予了它，山南山北判若晨昏。层云生起荡涤心胸，睁大眼睛目送归鸟入山。一定要登上最高峰，那时俯瞰群山，都会觉得渺小。",
    s: "「会当凌绝顶，一览众山小」写尽青年杜甫的凌云壮志。全诗无一「望」字却句句写望，由远及近，层层递进。",
    b: "开元二十四年起杜甫漫游齐赵，途经泰山所作，是现存杜诗中最早的作品之一。"
  },
  "春望|杜甫": {
    y: "国都沦陷，山河依旧；春天来到，城中草木丛生。感伤时事，见花也落泪；怅恨离别，闻鸟也惊心。战火连续三个月，一封家信抵得上万两黄金。满头白发越挠越短，几乎插不住簪子了。",
    s: "「感时花溅泪，恨别鸟惊心」——花鸟本娱人，因人心悲伤而溅泪惊心。国破之痛与思家之情层层交织，沉郁顿挫。",
    b: "至德二载春，杜甫身陷安史叛军占领的长安，目睹都城残破景象而作。"
  },
  "蜀相|杜甫": {
    y: "诸葛丞相的祠堂何处寻？锦官城外柏树森森。碧草自绿阶前，黄鹂空自鸣叫。三顾茅庐论天下大计，辅佐先帝后主两代老臣。出兵未捷身先死，长使千古英雄泪满襟。",
    s: "「出师未捷身先死，长使英雄泪满襟」写尽壮志未酬的千古遗恨，既是悼诸葛亮，也是自伤怀抱。",
    b: "乾元三年杜甫定居成都后，探访武侯祠，追慕诸葛亮功业，有感于自身报国无门而作。"
  },
  "闻官军收河南河北|杜甫": {
    y: "剑门外忽传收复蓟北的喜讯，初闻时泪水沾满衣裳。回头看妻儿，愁云一扫而空；胡乱卷起诗书，欣喜若狂。白日放歌须纵酒，趁着大好春光启程还乡。即从巴峡穿巫峡，再下襄阳直奔洛阳。",
    s: "杜甫「生平第一快诗」。忽传、初闻、却看、漫卷，一连串动作写狂喜；尾联四句四个地名一泻千里，归心似箭。",
    b: "广德元年春，延续八年的安史之乱终告平定，流寓梓州的杜甫闻讯喜极而作。"
  },
  "春夜喜雨|杜甫": {
    y: "好雨仿佛懂得时节，正当春天就及时降临。随风悄悄潜入夜空，细细密密滋润万物。野外云黑路暗，江船渔火独明。清晨再看那带雨的红花，定是沉甸甸开满锦官城。",
    s: "一个「知」字把雨写活了。「润物细无声」既状春雨之柔，又暗喻潜移默化的教化之功，体贴入微。",
    b: "上元二年春，杜甫定居成都草堂，亲自耕作养花，对春雨润物有真切体会。"
  },
  "茅屋为秋风所破歌|杜甫": {
    y: "八月秋风怒号，卷走我屋顶上几层茅草，茅草飞过江去，有的挂树梢，有的沉塘坳。南村群童欺我年老，公然抱茅入竹去。夜里屋漏床湿，孩子把被里都蹬破了，长夜难眠。何时能有千万间广厦，庇护天下寒士，让他们都开颜欢笑？那时即使我的茅屋被吹破、自己受冻而死，也心甘情愿！",
    s: "从自家屋漏之痛推及天下寒士，「安得广厦千万间，大庇天下寒士俱欢颜」展现了推己及人的博大胸怀，是杜甫人道主义精神的最强音。",
    b: "上元二年秋，杜甫成都草堂的茅屋被秋风吹破，连夜屋漏，有感而作。"
  },
  "登鹳雀楼|王之涣": {
    y: "夕阳依傍群山慢慢沉落，黄河向着大海滔滔奔流。想要看得更远，就要再登上一层楼。",
    s: "前两句写眼前壮阔山河，后两句翻出不凡哲理。「欲穷千里目，更上一层楼」成为进取精神的通用语，景、情、理水乳交融。",
    b: "王之涣早年漫游时登临蒲州鹳雀楼所作，是唐代五绝的压卷之作。"
  },
  "凉州词|王之涣": {
    y: "黄河仿佛从白云间奔流而来，一座孤城坐落在万丈高山之中。羌笛何必吹奏哀怨的《折杨柳》？春风本来就吹不到玉门关外。",
    s: "「春风不度玉门关」既写边地苦寒，又暗讽朝廷不恤戍卒。悲壮苍凉而气韵沉雄，被推为唐人七绝压卷之作之一。",
    b: "唐代边塞诗名篇，写戍守凉州将士的乡思，「旗亭画壁」的典故即由此诗而来。"
  },
  "出塞|王昌龄": {
    y: "依旧是秦汉时的明月、秦汉时的边关，万里征战的将士至今未还。倘若飞将军李广还在，绝不会让敌人的战马越过阴山。",
    s: "「秦时明月汉时关」一句互文，把千年边患的历史纵深感拉到眼前。被明代李攀龙推为唐人七绝压卷之作。",
    b: "王昌龄早年赴边塞时所作，慨叹边将无能、征人未还，寄托对良将安边的期盼。"
  },
  "芙蓉楼送辛渐|王昌龄": {
    y: "寒雨连江，夜入吴地，清晨在芙蓉楼送你北归，眼前只剩楚山孤影。洛阳的亲友如果问起我，就说我的心仍像玉壶中的冰一样纯洁。",
    s: "「一片冰心在玉壶」以玉壶冰自喻清白坚贞的品格，送别诗不写离愁写操守，立意高远。",
    b: "王昌龄时任江宁县丞，遭人非议，借送别友人辛渐表明心迹。"
  },
  "别董大|高适": {
    y: "黄云千里使日光昏暗，北风吹雁、大雪纷飞。不必忧愁前路没有知己，天下还有谁不认识您呢？",
    s: "「莫愁前路无知己，天下谁人不识君」在凄寒背景中喊出豪迈之声，慰藉中见风骨，是送别诗中别具一格的壮语。",
    b: "高适与著名琴师董庭兰相遇时同处困顿，离别时以诗相赠共勉。"
  },
  "白雪歌送武判官归京|岑参": {
    y: "北风卷地吹折白草，胡天八月就下起了雪。忽然如一夜春风吹来，千树万树梨花开。雪落珠帘湿了罗幕，狐裘不暖锦被也薄。将军角弓冻得拉不开，都护铁衣冷得难穿上。瀚海冰封百丈，愁云惨淡万里。中军设酒饯行，胡琴琵琶羌笛齐奏。傍晚大雪落满辕门，红旗冻僵在风里不能翻卷。轮台东门送你离去，雪满天山路，山回路转不见你，雪上只留下马蹄的印迹。",
    s: "「忽如一夜春风来，千树万树梨花开」以春景写冬雪，奇绝壮美。全诗以雪为线索串起送别，气势磅礴又情韵悠长。",
    b: "岑参第二次出塞，任安西北庭节度使封常清幕僚，在轮台送同僚武某返京时作。"
  },
  "黄鹤楼|崔颢": {
    y: "昔人已乘黄鹤离去，此地只留下黄鹤楼。黄鹤一去不再回来，千百年来只见白云悠悠。晴日里汉阳树木清晰可见，鹦鹉洲上芳草茂盛。傍晚时分何处是故乡？江面烟波使人忧愁。",
    s: "前四句打破格律、一气呵成，后四句严整工丽，古律相间而气象浑成。传说李白登楼见此诗而搁笔：「眼前有景道不得，崔颢题诗在上头。」",
    b: "崔颢登武昌黄鹤楼吊古怀乡而作，被严羽《沧浪诗话》推为唐人七律第一。"
  },
  "春晓|孟浩然": {
    y: "春夜酣睡不知不觉天已亮，到处听见鸟儿的啼鸣。想起昨夜风声雨声，不知有多少花儿被吹落。",
    s: "从听觉落笔写春天：鸟啼是晴，风雨是昨，花落是惜。二十字里有春天的生机与怜惜，天然浑成。",
    b: "孟浩然早年隐居鹿门山时所作，是流传最广的唐诗之一。"
  },
  "过故人庄|孟浩然": {
    y: "老朋友备下饭菜，邀我到田家做客。绿树环绕村庄，青山斜倚城郭。开窗面对谷场菜园，把酒闲谈农事。等到九九重阳节，还要再来赏菊饮酒。",
    s: "「绿树村边合，青山郭外斜」对仗自然如口语，全诗如话家常，田园的恬静与友情的醇厚水乳交融。",
    b: "孟浩然隐居襄阳时，应邀到农村老友家做客，归后所作。"
  },
  "咏柳|贺知章": {
    y: "高高的柳树像用碧玉妆扮而成，万千枝条垂下如绿色丝带。这细细的叶子是谁裁剪出来的？二月的春风就像一把剪刀。",
    s: "把无形的春风比作有形的剪刀，构思新奇。「不知细叶谁裁出，二月春风似剪刀」赋予春风创造性的人格。",
    b: "贺知章晚年告老还乡时所作，借咏柳赞美春天的创造力。"
  },
  "回乡偶书|贺知章": {
    y: "年少离家，到老了才回来，乡音虽未改变，鬓发已经疏落。孩子们见了都不认识，笑着问：客人您从哪里来？",
    s: "「少小离家老大回」人人心中有、个个笔下无。儿童的笑问天真无邪，却反衬出久客伤老的无限感慨。",
    b: "天宝三载，八十六岁的贺知章辞官还乡，距他离乡已五十余年。"
  },
  "赋得古原草送别|白居易": {
    y: "原野上的草一年一枯荣。野火烧不尽它，春风吹来又复生。远芳侵入古道，晴翠连接荒城。又送友人离去，萋萋芳草满含离别之情。",
    s: "「野火烧不尽，春风吹又生」写野草顽强的生命力，成为赞美坚韧精神的千古名句，赋得体而能自出新意。",
    b: "相传是白居易十六岁应考习作，以此诗谒见名士顾况，顾况读后叹服：「有句如此，居天下亦不难。」"
  },
  "钱唐湖春行|白居易": {
    y: "从孤山寺北、贾亭西出发，春水初涨与岸齐平，白云低垂与湖相连。早来的黄莺争抢向阳的树，新来的燕子啄泥筑巢。缤纷的春花渐渐迷乱人眼，浅浅的春草刚能没过马蹄。最爱湖东一带美景，绿杨阴里的白沙堤，怎么走也不够。",
    s: "以游踪为线，莺燕花草皆是早春「初、早、新、渐」的情态，「乱花渐欲迷人眼，浅草才能没马蹄」体物入微。",
    b: "长庆年间白居易任杭州刺史时，春日游览西湖（钱塘湖）所作。"
  },
  "暮江吟|白居易": {
    y: "一道残阳铺洒在江面上，半江碧绿半江绯红。最可爱的是九月初三的夜晚，露水像珍珠，新月像弯弓。",
    s: "「半江瑟瑟半江红」——受光的半江红，背光的半江碧，色彩对照如画；末以真珠、弯弓设喻，夜景清丽可爱。",
    b: "长庆二年白居易自请外放，赴杭州刺史任途中，心情轻松畅快，见暮色江景而作。"
  },
  "江雪|柳宗元": {
    y: "千山之中没有飞鸟的踪迹，万条路上没有行人的踪影。只有一叶孤舟上，披蓑戴笠的老翁，独自在寒冷的江雪中垂钓。",
    s: "前两句以「绝」「灭」造出极端寂静的天地，后两句孤舟独钓的渔翁正是诗人孤高傲岸、不屈于厄运的自我写照。",
    b: "柳宗元因永贞革新失败被贬永州司马，政治失意中借寒江独钓寄寓坚守之志。"
  },
  "山行|杜牧": {
    y: "沿着弯曲的石子小路上寒山，在白云升起的地方隐约有人家。停下车来只因喜爱这枫林晚景，经霜的枫叶比二月的春花还要红艳。",
    s: "「霜叶红于二月花」一反悲秋传统，把深秋枫叶写得比春花更热烈，英爽俊拔，理趣与画意兼备。",
    b: "杜牧秋日山行即景之作，展现其对自然之美的敏锐发现。"
  },
  "清明|杜牧": {
    y: "清明时节细雨纷纷，路上行人神情凄迷。请问哪里有酒家？牧童遥遥指向杏花深处的村庄。",
    s: "雨纷纷、欲断魂，写尽清明特有的凄迷氛围；末句牧童遥指，画面一转，留下悠长余味，是节日诗中传诵最广的一首。",
    b: "杜牧任池州刺史时逢清明细雨，触景而作。"
  },
  "泊秦淮|杜牧": {
    y: "烟雾笼罩寒水，月光笼罩沙滩，夜晚停船在秦淮河靠近酒家的地方。歌女不懂亡国之恨，隔着江水还在唱《玉树后庭花》。",
    s: "「商女不知亡国恨，隔江犹唱后庭花」借陈后主亡国之音，讽刺晚唐统治者醉生梦死，曲笔写忧愤，警策深沉。",
    b: "杜牧夜泊金陵秦淮河，眼见统治者奢靡享乐、国势日衰，有感而作。"
  },
  "夜雨寄北|李商隐": {
    y: "你问我归期，我也说不好何时能回。今夜巴山夜雨涨满秋池。什么时候能和你倚坐西窗剪烛夜话，那时再向你讲述今夜巴山听雨的心情。",
    s: "「何当共剪西窗烛，却话巴山夜雨时」——从今夜之雨预想他日重逢夜话，时空回环往复，语浅情深，是李商隐最温情的诗。",
    b: "李商隐滞留巴蜀时，寄赠远在长安的妻子（一说友人）之作。"
  },
  "无题|李商隐": {
    y: "相见难，离别更难，何况在东风无力的暮春。春蚕到死才吐尽丝，蜡烛烧成灰才干泪。晨起对镜只怕鬓发变白，夜吟应觉月光清寒。蓬莱山不远，请青鸟替我去探望她。",
    s: "「春蚕到死丝方尽，蜡炬成灰泪始干」以谐音双关（丝/思）写至死不渝的思念，缠绵悱恻，成为爱情诗的顶级名句。",
    b: "李商隐《无题》组诗多写爱情，本事难考，正因其朦胧而意蕴无穷。"
  },
  "锦瑟|李商隐": {
    y: "锦瑟为什么有五十根弦？一弦一柱都让我想起逝去的年华。庄周梦蝶，望帝化鹃。沧海月明，鲛人泪落成珠；蓝田日暖，美玉升起烟霭。这份情怀岂是今天回忆时才怅惘？当时就已惘然了。",
    s: "全诗意象华美而旨趣朦胧，悼亡、自伤、咏物诸说并存，「此情可待成追忆，只是当时已惘然」道尽追忆之美与惘然之痛。",
    b: "约作于李商隐晚年，是义山诗中最难解也最负盛名的一篇。"
  },
  "游子吟|孟郊": {
    y: "慈爱的母亲手中穿针引线，为即将远行的儿子缝制衣衫。临行前一针针缝得细密，担心儿子迟迟不归。谁说小草般微弱的孝心，报答得了春天阳光般的母爱？",
    s: "「谁言寸草心，报得三春晖」以小草与春晖设喻，写尽母爱的博大与孝心的难报，千年来唤起无数人的共鸣。",
    b: "孟郊五十岁任溧阳县尉，接母亲同住，感念半生漂泊中母亲的牵挂而作，题下自注「迎母溧上作」。"
  },
  "乌衣巷|刘禹锡": {
    y: "朱雀桥边长满野草野花，乌衣巷口夕阳西斜。从前在王谢堂前筑巢的燕子，如今飞进了普通百姓家。",
    s: "不著一字议论，只写桥边野草、巷口夕阳、堂前旧燕，六朝的繁华与眼前的冷落自在对照之中，「旧时王谢堂前燕，飞入寻常百姓家」是咏史的妙笔。",
    b: "宝历二年刘禹锡由和州返洛阳途经金陵，作《金陵五题》，此为第二首。"
  },
  "酬乐天扬州初逢席上见赠|刘禹锡": {
    y: "在巴山楚水这些凄凉之地，我被贬置了二十三年。怀念旧友只能吟诵闻笛之赋，回乡恍如隔世之人。沉船旁边有千帆竞发，病树前头是万木逢春。今日听你高歌一曲，且借这杯酒振作精神。",
    s: "「沉舟侧畔千帆过，病树前头万木春」以沉舟病树自况却毫不颓唐，翻出新旧更替的昂扬哲理，是逆境诗的巅峰。",
    b: "宝历二年，刘禹锡结束二十三年贬谪北返，在扬州与白居易相遇，酬答白的赠诗而作。"
  },
  "元日|王安石": {
    y: "爆竹声中旧的一年过去，春风送暖，人们畅饮屠苏酒。千家万户被朝阳照得明亮，都忙着把旧桃符换成新桃符。",
    s: "爆竹、屠苏、新桃符，三个年俗意象写出万象更新的春节气象，也寄托了诗人推行新政、除旧布新的政治抱负。",
    b: "王安石初拜相、推行新法之时，见新年气象联想到变法图强，欣然命笔。"
  },
  "泊船瓜洲|王安石": {
    y: "京口与瓜洲只隔一江水，钟山也不过数重山之遥。春风又一次吹绿了江南两岸，明月什么时候才能照着我回家？",
    s: "「春风又绿江南岸」的「绿」字历经十数次改定，由形容词活用为动词，一字传神，是炼字的千古范例。",
    b: "熙宁八年王安石二次拜相，自江宁赴京途中泊船瓜洲，眷恋故里而作。"
  },
  "饮湖上初晴后雨|苏轼": {
    y: "晴天时西湖波光潋滟正美，雨天时山色空濛也很奇妙。若把西湖比作西施，无论淡妆还是浓抹，都那么相宜。",
    s: "「欲把西湖比西子，淡妆浓抹总相宜」以西施喻西湖，从此西湖有了「西子湖」的别称，是咏西湖诗的绝唱。",
    b: "熙宁六年苏轼任杭州通判时所作，同题共二首，此为第二首。"
  },
  "题西林壁|苏轼": {
    y: "正面看是山岭，侧面看是山峰；远近高低，姿态各不相同。看不清庐山的真面目，只因为自己就站在这山里面。",
    s: "「不识庐山真面目，只缘身在此山中」借观山说理：当局者迷，旁观者清。写景与哲理浑然一体，是宋诗理趣的代表。",
    b: "元丰七年苏轼由黄州改贬汝州，途经庐山，题诗于西林寺壁。"
  },
  "水调歌头|苏轼": {
    y: "明月从什么时候开始有的？举杯问苍天。不知天上宫阙，今晚是哪一年。想乘风归去，又怕琼楼玉宇太高太冷。起舞弄着清影，何似在人间。月光转过朱楼，低照绮窗，照着无眠的我。月亮不该有恨，为何总在离别时圆？人有悲欢离合，月有阴晴圆缺，此事自古难全。只愿人长久，即使相隔千里，也能共赏这一轮明月。",
    s: "中秋词的千古绝唱。从问天到问月，从出世之想到入世之情，最后落在「但愿人长久，千里共婵娟」的旷达祝愿上，清雄旷达，历来被推为中秋词第一。",
    b: "熙宁九年中秋，苏轼在密州任上，怀念七年未见的弟弟苏辙，大醉而作此词。"
  },
  "游山西村|陆游": {
    y: "莫笑农家腊月酿的酒浑浊，丰收年景待客的菜肴很丰盛。山峦重叠、水道弯弯，正怀疑无路可走，忽然柳暗花明，又出现一个村庄。箫鼓声近，春社日将临，村民衣冠简朴古风犹存。从今若得闲乘月出游，我还要拄杖随时来叩门。",
    s: "「山重水复疑无路，柳暗花明又一村」写尽绝处逢生的境界，既是山村行旅的实景，又蕴含人生哲理，流传极广。",
    b: "乾道三年，陆游罢官闲居山阴老家，游镜湖旁山西村有感而作。"
  },
  "示儿|陆游": {
    y: "我本就知道人死后万事皆空，唯一痛心的是没能亲眼看到国家统一。等到大宋军队收复中原那一天，家祭时别忘了把这个消息告诉你们的父亲。",
    s: "绝笔之作，临终念念不忘的不是家事而是国事。「王师北定中原日，家祭无忘告乃翁」九百年后读来仍令人动容。",
    b: "嘉定二年冬，八十五岁的陆游临终前写给儿子们的遗嘱诗，是他一生爱国情怀的最后凝结。"
  },
  "十一月四日风雨大作|陆游": {
    y: "僵卧在孤村里并不自哀，还想着为国家戍守边疆。深夜躺着听风吹雨打，梦中仿佛骑着披铁甲的战马跨过冰封的河流。",
    s: "「夜阑卧听风吹雨，铁马冰河入梦来」——现实的僵卧与梦中的征战形成强烈对照，六十八岁老诗人的报国之志跃然纸上。",
    b: "绍熙三年，陆游退居山阴，风雨之夜触景生情，写下这组诗（此为其二）。"
  },
  "破阵子|辛弃疾": {
    y: "醉里挑亮油灯看宝剑，梦中回到号角连营。八百里牛肉分给部下，五十弦乐器奏出悲壮军乐，沙场秋点兵。战马像的卢一样飞快，弓弦如霹雳般震响。本想完成君王收复中原的大业，赢得生前身后名，可惜如今已是满头白发！",
    s: "前九句一路壮怀激烈，结句「可怜白发生」猛然跌落，理想与现实的巨大落差喷薄而出，是辛词悲壮风格的代表。",
    b: "辛弃疾失意闲居江西时，寄赠志同道合的好友陈亮（字同甫）之作。"
  },
  "西江月|辛弃疾": {
    y: "明月升上枝头惊起喜鹊，清风半夜送来蝉鸣。稻花香里谈论着丰收年景，听取蛙声一片。七八个星星挂在天边，两三点雨落在山前。从前熟悉的茅店还在社林边，拐了个弯，忽然就出现在眼前。",
    s: "全词用白描写乡村夏夜：月、鹊、风、蝉、稻香、蛙声、疏星、微雨，平淡景物中满是丰收的喜悦与生活的热爱。",
    b: "辛弃疾闲居上饶带湖期间，夜行黄沙岭道中所见所感。"
  },
  "小池|杨万里": {
    y: "泉眼无声，仿佛吝惜那涓涓细流；树阴映水，喜爱这晴日的柔光。小荷刚露出尖尖的角，早就有蜻蜓立在上头了。",
    s: "「小荷才露尖尖角，早有蜻蜓立上头」捕捉刹那间的生机，小巧玲珑又意蕴悠长，成为新生事物最经典的写照。",
    b: "杨万里「诚斋体」小诗的代表，写日常生活里随处可见的小景，清新自然。"
  },
  "晓出净慈寺送林子方|杨万里": {
    y: "到底是六月的西湖，风光与别的季节不同。满湖的莲叶一直铺到天边，碧绿无穷；荷花映着朝阳，红得格外鲜艳。",
    s: "「接天莲叶无穷碧，映日荷花别样红」用夸张与对仗写尽六月西湖的浓烈色彩，碧绿与别样红形成强烈视觉冲击。",
    b: "淳熙十四年，杨万里清晨出杭州净慈寺送别赴福州任职的友人林子方而作。"
  },
  "春日|朱熹": {
    y: "风和日丽在泗水边踏青，无边风光焕然一新。人人都认得春风的面容——万紫千红的花开，就是春天的样子。",
    s: "「等闲识得东风面，万紫千红总是春」表面写游春，实寓求道：圣人之道如春风化雨，万紫千红皆其化育。",
    b: "泗水在宋时已沦陷于金，朱熹未曾亲至，此诗实为借景言志的哲理诗。"
  },
  "观书有感|朱熹": {
    y: "半亩大的方形池塘像一面打开的镜子，天光云影在水中徘徊。池塘里的水为什么这样清澈？因为有源头不断送来活水。",
    s: "「问渠那得清如许，为有源头活水来」借池塘清澈喻心智开明：不断学习新知识，思想才能常新，是说理诗的典范。",
    b: "朱熹读书有感而作，以形象喻抽象哲理，同题共二首，此为其一。"
  },
  "满江红|岳飞": {
    y: "怒发冲冠，凭栏处，一场急雨刚停。仰天长啸，壮怀激烈。三十年的功名如尘土，八千里的征程伴云月。莫等闲，白了少年头，空悲切！靖康之耻还未洗雪，臣子之恨何时能灭？定要驾长车，踏破贺兰山缺。壮志饥餐胡虏肉，笑谈渴饮匈奴血。待从头收拾旧山河，朝天阙！",
    s: "千古忠愤第一词。「莫等闲、白了少年头，空悲切」既是自励也是励人，全词字字掷地有声，成为中华民族爱国精神的符号。",
    b: "约作于绍兴年间岳飞北伐前后，抒发收复中原、洗雪国耻的壮志。"
  },
  "过零丁洋|文天祥": {
    y: "回想我由科举入仕历尽艰辛，战火中已度过四年。山河破碎如风中的柳絮，身世浮沉如雨打的浮萍。惶恐滩头诉说惶恐，零丁洋里叹息零丁。人生自古以来谁能不死？留取一颗丹心照耀史册！",
    s: "「人生自古谁无死？留取丹心照汗青」以死明志，气贯长虹，成为中华民族舍生取义精神的千古绝唱。",
    b: "祥兴二年，文天祥兵败被俘，元军押他经过零丁洋，他以此诗明志拒降。"
  },
  "天净沙|马致远": {
    y: "枯藤缠绕的老树上栖息着黄昏的乌鸦，小桥下流水旁有人家，荒凉的古道上，一匹瘦马顶着西风前行。夕阳向西落下，伤心的旅人还漂泊在天涯。",
    s: "二十八字，九个名词意象叠加成画，无一动词而萧瑟自现，被誉为「秋思之祖」，是元人小令的巅峰。",
    b: "马致远长期漂泊不得志，秋日旅途中触景生情而作。"
  },
  "山坡羊|张养浩": {
    y: "峰峦如聚，波涛如怒，山河表里潼关路。遥望西都，意踌躇。伤心秦汉宫殿都化作了尘土。兴，百姓苦；亡，百姓苦。",
    s: "结尾「兴，百姓苦；亡，百姓苦」八个字一针见血：无论王朝兴亡，苦难都落在百姓头上，立意远超一般怀古之作。",
    b: "天历二年陕西大旱，张养浩赴任赈灾，途经潼关怀古伤今而作。"
  },
  "石灰吟|于谦": {
    y: "石灰石经过千锤万凿才从深山开采出来，烈火焚烧视若等闲。粉身碎骨也毫不惧怕，只为把清白留在人间。",
    s: "托物言志的典范。石灰的锤炼过程正是人格的修炼过程，「要留清白在人间」是于谦一生的写照。",
    b: "相传为于谦少年时观石灰烧制有感而作，后来他果然以清白忠烈践行了此诗。"
  },
  "竹石|郑燮": {
    y: "竹子紧紧咬住青山毫不放松，根深深扎进岩石缝中。经历千磨万击依然坚劲，任凭你东西南北刮什么风。",
    s: "「千磨万击还坚劲，任尔东西南北风」以岩竹自喻，写尽刚正不阿、不屈不挠的骨气，是题画诗中的名篇。",
    b: "郑板桥为自画竹石图所题的诗，画中竹、诗中志、人中品三者合一。"
  },
  "己亥杂诗|龚自珍": {
    y: "要使中国大地重新焕发生气，必须依靠疾风迅雷般的变革。社会沉闷到极点，终究令人悲哀。我劝上天重新振作精神，不拘一格地降下各种人才。",
    s: "「我劝天公重抖擞，不拘一格降人才」喊出对变革与人才的渴望，是近代思想启蒙的先声。",
    b: "道光十九年（己亥年），龚自珍辞官南归，途中作大型组诗三百一十五首，此为其一百二十五，过镇江时见祭神场面有感。"
  },
  "沁园春|毛泽东": {
    y: "北国风光，千里冰封，万里雪飘。望长城内外只剩莽莽一片，大河上下顿时失去滔滔。山如银蛇飞舞，高原如白象奔驰，都想与老天比高。待到晴天，看红妆素裹，分外妖娆。江山如此多娇，引无数英雄竞折腰。可惜秦皇汉武文采稍逊，唐宗宋祖风骚略差，一代天骄成吉思汗，只识弯弓射大雕。都过去了，数风流人物，还看今朝。",
    s: "上阕写北国雪景，气象万千；下阕评点千古帝王，落到「数风流人物，还看今朝」的万丈豪情，是现代词坛的巅峰之作。",
    b: "1936年2月，毛泽东率红军东征途中，在陕北清涧见大雪而作；1945年重庆谈判期间公开发表，轰动一时。"
  },
  "七律·长征|毛泽东": {
    y: "红军不怕远征的艰难，把万水千山只看作平常。五岭逶迤如细小的波浪，乌蒙磅礴像滚动的泥丸。金沙江拍打着云崖变暖，大渡河的铁索桥令人胆寒。更喜岷山千里雪，三军过后个个笑开颜。",
    s: "「红军不怕远征难，万水千山只等闲」开篇即定下豪迈基调，五岭作细浪、乌蒙为泥丸的夸张，写尽革命英雄主义气概。",
    b: "1935年10月，中央红军长征胜利在望，毛泽东回顾征程而作。"
  },
  "滕王阁序|王勃": {
    y: "这里是汉代的豫章旧郡、今日的洪都新府。天上对应翼、轸二星，地上连接衡山与庐山……雨过天晴，落霞与孤鹜一同飞翔，秋水与长天融为一色。傍晚渔船上传来歌声，响彻鄱阳湖畔；雁阵惊觉寒意，鸣声消失在衡阳水边。",
    s: "「落霞与孤鹜齐飞，秋水共长天一色」是骈文史上最著名的句子。全文四六对仗、典故琳琅而不滞涩，由盛宴之乐转入身世之悲，再振起于青云之志，跌宕起伏。",
    b: "上元二年，王勃南下探父途经南昌，适逢都督阎公重修滕王阁大宴宾客，即席挥毫写成此序，时年二十六岁（一说十四岁）。"
  },
  "岳阳楼记|范仲淹": {
    y: "庆历四年春，滕子京被贬到岳州做知州。到第二年，政事顺利、百姓和乐，各种荒废的事业都兴办起来，于是重修岳阳楼，嘱托我写篇文章记述此事……古时仁人的心境不同于常人：不因外物而喜，不因己身而悲；在朝廷做官就忧虑百姓，退处江湖就忧虑君主。那么何时才快乐呢？他们一定说：「在天下人忧之前先忧，在天下人乐之后才乐。」",
    s: "「先天下之忧而忧，后天下之乐而乐」是全文灵魂。文章借景写情、以情衬理，把迁客骚人的悲喜与古仁人的境界两相对照，立意高远，成为士人精神的千年标杆。",
    b: "庆历六年，范仲淹因「庆历新政」失败被贬邓州，应同样被贬的好友滕子京之请，看图作文写就此记。"
  },
  "醉翁亭记|欧阳修": {
    y: "环绕滁州的都是山。西南方向的山峰，树林和山谷尤其秀美……醉翁的意趣不在酒上，而在山水之间。山水的乐趣，领会在心里，寄托在酒上……人们只知道跟从太守游玩的快乐，却不知道太守以他们的快乐为快乐啊。",
    s: "全文连用二十一个「也」字，一唱三叹，摇曳生姿。「醉翁之意不在酒，在乎山水之间也」早已化入日常语言，山水之乐、宴饮之乐、与民同乐层层递进。",
    b: "庆历五年，欧阳修因支持庆历新政被贬滁州知州，寄情山水、与民同乐，自号「醉翁」而作。"
  },
  "出师表|诸葛亮": {
    y: "先帝开创大业未及一半就中途去世，如今天下三分，益州疲敝，这实在是危急存亡的时刻……我本是一介平民，在南阳亲自耕种，只求在乱世中保全性命，不求在诸侯间显达。先帝不嫌我身份低微，三次到草庐中看望我，向我询问天下大事，我因此感奋，答应为先帝奔走效劳……如今南方已经平定，军备已经充足，应当激励全军，北上平定中原。这是我报答先帝、效忠陛下的职责本分。",
    s: "全文不用典故、不事雕琢，一片赤诚从肺腑流出。「鞠躬尽瘁，死而后已」的精神写照，陆游赞曰：「出师一表真名世，千载谁堪伯仲间。」",
    b: "建兴五年，诸葛亮决定北上伐魏，临行前上表后主刘禅，劝勉他亲贤远佞，并剖白自己的心迹。"
  },
  "桃花源记|陶渊明": {
    y: "晋朝太元年间，武陵有个以捕鱼为生的人。一天他沿溪而行，忘记了路程远近，忽然遇到一片桃花林……村里人自己说，先辈为躲避秦时战乱，带领妻子儿女和乡邻来到这与世隔绝的地方，从此不再出去，就和外界隔绝了。他们问现在是什么朝代，竟然不知道有过汉朝，更不用说魏和晋了。",
    s: "以渔人行踪为线索，把虚构的桃源写得宛然在目。「桃花源」从此成为中国人心中理想社会的代名词，影响及于诗歌、绘画乃至东亚文化圈。",
    b: "约作于南朝宋永初二年，时值晋宋易代、战乱频仍，陶渊明借虚构的乐土寄托对和平安定生活的向往。"
  },
  "陋室铭|刘禹锡": {
    y: "山不在于高，有仙人就出名；水不在于深，有蛟龙就显灵。这是间简陋的屋子，只因我的品德美好就不觉简陋。苔痕碧绿长到阶上，草色青葱映入帘中。谈笑往来的都是博学之士，没有无学问的人。可以弹素朴的琴，读佛经。没有奏乐声扰乱耳朵，没有公文劳累身心。好比南阳诸葛亮的草庐、西蜀扬子云的玄亭。孔子说：有什么简陋的呢？",
    s: "全文八十一字，以「惟吾德馨」为眼目，山水起兴、人事作陪、圣言作结，把安贫乐道的君子之风写得铿锵雅致，是铭文体的绝唱。",
    b: "刘禹锡因参加永贞革新被贬和州，知县故意刁难、三迁其居，他愤然写下此文置于门上。"
  },
  "爱莲说|周敦颐": {
    y: "水上陆上各种草木的花，值得喜爱的很多。晋代陶渊明只爱菊花，自唐朝以来世人大多爱牡丹。我唯独爱莲花从淤泥中长出却不被沾染，经清水洗涤却不显得妖媚，茎内空外直，不蔓不枝，香气越远越清，洁净地挺立，可以远远观赏却不能轻慢地玩弄。",
    s: "「出淤泥而不染，濯清涟而不妖」是全文之眼。以菊衬隐逸、以牡丹衬富贵、以莲喻君子，托物言志，成为君子人格的千古定义。",
    b: "嘉祐八年，周敦颐任虔州通判时所作，是宋明理学开山鼻祖借花明志的名篇。"
  },
  "记承天寺夜游|苏轼": {
    y: "元丰六年十月十二日夜里，我解衣欲睡，月光照进门来，于是高兴地起身出门。想到没有可以同乐的人，就到承天寺找张怀民。怀民也没睡，我们便一起在庭院中散步。庭院里像积满了清水一样澄澈，水中藻荇交错，原来是竹子和柏树的影子。哪个夜晚没有月亮？哪里没有竹子和柏树？只是缺少像我们两个这样的闲人罢了。",
    s: "八十四字，叙事、写景、抒情浑然一体。「但少闲人如吾两人者耳」——贬谪中的自嘲里透着旷达，是苏轼小品文的极致。",
    b: "元丰六年，苏轼因「乌台诗案」被贬黄州已四年，与同样谪居的张怀民夜游赏月而作。"
  },
  "氓|佚名": {
    y: "憨厚农家小伙子，怀抱布匹来换丝。其实不是真换丝，找个机会谈婚事。送郎送过淇水西，到了顿丘情依依。不是我愿误佳期，你无媒人失礼仪。望郎休要发脾气，秋天到了来迎娶。\n爬上那垛破土墙，遥向复关凝神望。复关远在云雾中，不见情郎泪千行。情郎即从复关来，又说又笑喜洋洋。你去卜卦求神仙，没有凶兆心欢畅。赶着你的车子来，为我搬运好嫁妆。\n桑树叶子未落时，缀满枝头绿萋萋。嘘嘘那些斑鸠儿，别把桑葚吃嘴里。哎呀年轻姑娘们，别对男人情依依。男人若是恋上你，要丢便丢太容易。女人若是恋男子，要想解脱难挣离。\n桑树叶子落下了，枯黄憔悴任飘摇。自从嫁到你家来，三年穷苦受煎熬。淇水茫茫送我归，水溅车帷湿又潮。我做妻子没差错，是你男人太奸刁。反覆无常没准则，变心缺德耍花招。\n婚后三年守妇道，繁重家务不辞劳。起早睡晚不嫌苦，忙里忙外非一朝。谁知家业已成后，渐渐对我施凶暴。兄弟不知我处境，个个见我哈哈笑。静下心来细细想，独自伤神泪暗抛。\n当年发誓偕白头，如今未老心先忧。淇水滔滔终有岸，沼泽虽宽有尽头。回想少时多欢乐，谈笑之间露温柔。海誓山盟犹在耳，哪料反目竟成仇。莫再回想背盟事，既已终结便罢休！",
    s: "《氓》是《诗经》中最著名的叙事诗之一，以一位弃妇的口吻，讲述了从恋爱、结婚到被遗弃的完整过程。诗中女主人公从天真痴情到清醒决绝，形象鲜明生动。“桑之未落，其叶沃若”与“桑之落矣，其黄而陨”的比喻，将女子青春与衰老的对比写得入木三分。全诗是中国文学史上最早的女性觉醒之作。"
  },
  "离骚|屈原": {
    y: "我是古帝高阳氏的子孙，我已去世的父亲字伯庸。\n岁星在寅那年的孟春月，正当庚寅日那天我降生。\n父亲仔细揣测我的生辰，于是赐给我相应的美名。\n父亲把我的名取为正则，同时把我的字叫作灵均。\n天赋给我很多良好素质，我不断加强自己的修养。\n我把江离芷草披在肩上，把秋兰结成索佩挂身旁。\n光阴似箭我好像跟不上，岁月不等待人令我心慌。\n早晨我在大坡采集木兰，傍晚在小洲中摘取宿莽。\n时光迅速逝去不能久留，四季更相代谢变化有常。\n我想到草木已由盛到衰，恐怕自己身体逐渐衰老。\n何不利用盛时扬弃秽政，为何还不改变这些法度？\n乘上千里马纵横驰骋吧，来呀我在前面引导开路！",
    s: "《离骚》是屈原的代表作，也是中国古代最长的抒情诗，共373句。这里节选的是开篇部分，诗人自叙身世、生辰和名字，表达了自己的高洁品质和对国家的忧虑。“路漫漫其修远兮，吾将上下而求索”的精神贯穿全诗，奠定了中国浪漫主义文学的传统，对后世影响深远。"
  },
  "迢迢牵牛星|佚名": {
    y: "在银河东南牵牛星遥遥可见，在银河之西织女星明亮皎洁。\n织女正摆动柔长洁白的双手，织布机札札地响个不停。\n一整天也没织成一段布，哭泣的眼泪如同下雨般零落。\n这银河看起来又清又浅，两岸相隔又有多远呢？\n虽然只相隔了一条银河，但也只能含情脉脉相视无言。",
    s: "《迢迢牵牛星》是《古诗十九首》中的名篇，借牛郎织女的神话传说，抒发了男女之间的相思离别之苦。全诗通篇使用叠字，“迢迢”“皎皎”“纤纤”“札札”“盈盈”“脉脉”，音韵和谐，意境优美。最后两句“盈盈一水间，脉脉不得语”，将咫尺天涯的哀怨写得含蓄深沉，是五言诗的杰作。"
  },
  "短歌行|曹操": {
    y: "一边喝酒一边高歌，人生短促日月如梭。\n好比晨露转瞬即逝，失去的时日实在太多！\n席上歌声激昂慷慨，忧郁长久填满心窝。\n靠什么来排解忧闷？唯有狂饮方可解脱。\n那穿着青领的学子哟，你们令我朝夕思慕。\n只是因为您的缘故，让我沉痛吟诵至今。\n阳光下鹿群呦呦欢鸣，悠然自得啃食在绿坡。\n一旦四方贤才光临舍下，我将奏瑟吹笙宴请嘉宾。\n当空悬挂的皓月哟，什么时候才可以拾到。\n我久蓄于怀的忧愤哟，突然喷涌而出汇成长河。\n远方宾客踏着田间小路，一个个屈驾前来探望我。\n彼此久别重逢谈心宴饮，争着将往日的情谊诉说。\n月光明亮星光稀疏，一群寻巢乌鹊向南飞去。\n绕树飞了三周却没敛翅，哪里才有它们的栖身之所？\n高山不辞土石才见巍峨，大海不弃涓流才见壮阔。\n我愿如周公一般礼贤下士，愿天下的英杰真心归顺于我。",
    s: "《短歌行》是曹操的代表作，全诗抒发了诗人求贤若渴的心情和统一天下的雄心壮志。开头“对酒当歌，人生几何”感叹时光易逝，继而引用《诗经》成句表达对贤才的渴望，最后以“周公吐哺，天下归心”作结，气魄宏大。全诗情感跌宕，用典自然，是建安风骨的典范之作。"
  },
  "归园田居·其一|陶渊明": {
    y: "年轻时就没有适应世俗的性格，生来就喜爱大自然的风物。\n错误地陷落到仕途罗网，转眼间远离田园已十余年。\n笼子里的鸟儿怀念以前生活的森林，池子里的鱼儿思念原来嬉戏的深潭。\n我愿到南边的原野里去开荒，依着愚拙的心性回家耕种田园。\n绕房宅方圆有十余亩地，还有那茅屋草舍八九间。\n榆树柳树成荫遮盖了后屋檐，桃树李树整齐的栽种在屋前。\n远处的邻村屋舍依稀可见，村落上方飘荡着袅袅炊烟。\n深深的街巷中传来了几声狗吠，桑树顶有雄鸡不停啼唤。\n庭院内没有世俗琐杂的事情烦扰，静室里有的是安适悠闲。\n久困于樊笼里毫无自由，我今日总算又归返林山。",
    s: "《归园田居》是陶渊明辞官归隐后的组诗，这是第一首。诗中描写了田园生活的宁静美好，表达了对官场的厌恶和对自由的向往。“羁鸟恋旧林，池鱼思故渊”以鸟鱼自比，“久在樊笼里，复得返自然”点明主旨。全诗语言朴素自然，意境悠远，开创了中国田园诗派。"
  },
  "杜少府之任蜀州|王勃": {
    y: "三秦之地护卫着巍巍长安，透过那风云烟雾遥望着蜀川。\n和你离别心中怀着无限情意，因为我们同是在宦海中浮沉。\n四海之内有知心朋友，即使远在天边也如近在比邻。\n绝不要在岔路口上分手之时，像多情的少年男女那样悲伤得泪湿衣巾。",
    s: "这是王勃送别友人的名作，一反传统送别诗的伤感低沉，以“海内存知己，天涯若比邻”的豁达胸襟，表达了真挚深厚的友情。全诗格调高昂，气势雄健，是初唐送别诗的代表作，也是千古传诵的名篇。"
  },
  "春江花月夜|张若虚": {
    y: "春天的江潮水势浩荡，与大海连成一片，一轮明月从海面升起，仿佛跟着潮水一同涌现。\n月光照耀着春江，波光粼粼绵延千万里，所有地方的春江，都沐浴在明亮的月色里。\n江水曲折地绕过开满花草的原野，月光洒在花林上，像撒了一层细碎的雪珠。\n月色如霜在空中流淌，却感觉不到霜飞，江边的白沙和月色融为一体，看不分明。\n江水与天空连成一色，没有一丝尘埃，只有一轮皎洁的孤月高悬空中。\n江边是什么人，最先看见了月亮？江上的月亮，又是哪一年最初照耀着人间？\n人生一代又一代无穷无尽，而江上的月亮，年年看上去都没有变化。\n不知道江上的月亮在等待着什么人，只见长江水不断地向前奔流。\n一片白云悠然飘远，青枫浦上的游子，满是说不尽的忧愁。\n今晚谁家的游子坐着小船漂泊？何处的思妇在明月照耀的楼上思念远方的人？\n可怜那楼上徘徊的月光，应该正照在离人的梳妆台上。\n月光照进珠帘，卷也卷不走；落在捣衣砧上，拂去了又还来。\n此刻一同望着月亮，却听不到彼此的声音，我愿追随着月光，流照到你的身边。\n鸿雁飞得再远，也飞不出月光；鱼龙跃出水面，只激起阵阵波纹。\n昨夜梦见花落闲潭，可惜春天已经过半，人还没能回家。\n江水带着春光流走，快要耗尽；江潭上的落月，又向西边倾斜。\n斜月沉沉藏在海雾里，碣石与潇湘相隔万里，路途遥远。\n不知道有几人能乘着月光回家，落月的余晖摇曳着，洒满了江边的树林。",
    s: "《春江花月夜》被闻一多誉为“诗中的诗，顶峰上的顶峰”，素有“孤篇盖全唐”的美誉。全诗以春、江、花、月、夜为核心意象，将写景、抒情、哲理完美融合，既有宇宙永恒的苍茫追问，又有人生相思的细腻柔情，意境空灵悠远，是唐诗美学的极致代表。"
  },
  "辋川集·鹿柴|王维": {
    y: "幽静的山谷里看不见人，只听到人说话的声音。\n落日的影晕映入了深林，又照在幽暗处的青苔上。",
    s: "《鹿柴》是王维《辋川集》中的名篇，全诗仅二十字，却营造出一种空寂幽深的意境。“空山不见人，但闻人语响”以有声衬无声，“返景入深林，复照青苔上”以光亮写幽暗，充满禅意，体现了王维“诗佛”的艺术特色。"
  },
  "渭城曲|王维": {
    y: "渭城早晨一场春雨沾湿了轻尘，客舍周围柳树的枝叶翠嫩一新。\n老朋友请你再干一杯美酒，向西出了阳关就难以遇到故旧亲人。",
    s: "《送元二使安西》又名《渭城曲》，是王维最著名的送别诗，后被谱成《阳关三叠》，广为传唱。“劝君更尽一杯酒，西出阳关无故人”两句，将依依惜别之情浓缩在一杯酒中，含蓄深沉，余味无穷，是唐诗中最动人的送别名句。"
  },
  "望洞庭湖赠张丞相|孟浩然": {
    y: "秋水盛涨几乎与岸平，水天含混迷茫与天空浑然一体。\n云梦大泽水气蒸腾白白茫茫，波涛汹涌似乎把岳阳城撼动。\n想要渡水却没有船只，闲居不仕，有愧于圣明天子。\n坐看垂钓之人多么悠闲自在，可惜只能空怀一片羡鱼之情。",
    s: "这是孟浩然写给张九龄的干谒诗，希望得到引荐出仕。前四句写洞庭湖的壮阔景象，“气蒸云梦泽，波撼岳阳城”气势磅礴，是写洞庭湖的千古名句。后四句以“欲济无舟楫”“羡鱼情”委婉表达出仕的愿望，不卑不亢，含蓄得体。"
  },
  "凉州词二首”·一|王之涣": {
    y: "黄河好像从白云间奔流而来，玉门关孤独地耸峙在高山中。\n何必用羌笛吹起那哀怨的杨柳曲去埋怨春光迟迟不来呢，原来玉门关一带春风是吹不到的啊！",
    s: "《凉州词》是王之涣的代表作，也是唐代边塞诗的绝唱。前两句写塞外壮阔苍凉的景象，“黄河远上白云间”气势宏大；后两句借羌笛吹奏《折杨柳》曲，委婉表达戍边将士的思乡之情，“春风不度玉门关”一语双关，既写自然气候，又暗喻朝廷的恩泽不及边塞，含蓄深沉。"
  },
  "出塞二首·一|王昌龄": {
    y: "依旧是秦汉时期的明月和边关，守边御敌鏖战万里征夫未回还。\n倘若龙城的飞将李广如今还在，一定不会让敌人的铁蹄踏过阴山。",
    s: "《出塞》被明人李攀龙推为唐人七绝压卷之作。“秦时明月汉时关”以互文手法，将秦汉以来的漫长历史浓缩在一句之中，营造出苍茫悠远的时空感。后两句借怀念李广，表达对良将的渴望和对边塞安宁的期盼，气势雄浑，寓意深远。"
  },
  "芙蓉楼送辛渐二首·一|王昌龄": {
    y: "冷雨连夜洒遍吴地江天，清晨送走你后，独自面对着楚山离愁无限！\n到了洛阳，如果洛阳亲友问起我来，就请转告他们，我的心依然像玉壶里的冰那样晶莹纯洁！",
    s: "这是王昌龄送别友人的名作，“一片冰心在玉壶”是千古名句，以冰在玉壶之中比喻自己品格的高洁清白，既是对亲友的告慰，也是对自身操守的坚守。全诗意境凄清而不失高洁，情感真挚而含蓄。"
  },
  "从军行七首·四|王昌龄": {
    y: "青海湖上乌云密布，遮得连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。\n守边将士身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。",
    s: "《从军行》是王昌龄边塞诗的代表作，“黄沙百战穿金甲，不破楼兰终不还”两句，以铿锵的音调、坚定的语气，写出了戍边将士誓死报国的英雄气概，是唐诗中最具豪情壮志的名句之一。"
  },
  "燕歌行|高适": {
    y: "唐朝东北边境战事又起，将军离家前去征讨贼寇。\n战士们本来在战场上就所向无敌，皇帝又特别给予他们丰厚的赏赐。\n军队擂击金鼓，浩浩荡荡开出山海关外，旌旗连锦不断，飘扬在碣石山间。\n校尉紧急传羽书，飞奔浩瀚之沙海，匈奴单于举猎火光照已到我狼山。\n山河荒芜多萧条，满目凄凉到边土，胡人骑兵仗威力兵器声里夹风雨。\n战士拼斗军阵前半数死去半生还，美人却在营帐中还是歌来还是舞。\n时值深秋大沙漠塞外百草尽凋枯，孤城一片映落日战卒越斗越稀少。\n身受皇家深恩义常思报国轻寇敌，边塞之地尽力量尚未破除匈奴围。\n身穿铁甲守边远疆场辛勤已长久，珠泪纷落挂双目丈夫远去独啼哭。\n少妇孤单住城南泪下凄伤欲断肠，远征军人驻蓟北依空仰望频回头。\n边境飘渺多遥远怎可轻易来奔赴，绝远之地尽苍茫更是人烟何所有。\n杀气春夏秋三季腾起阵前似乌云，一夜寒风声声里如泣更声惊耳鼓。\n互看白刃乱飞舞夹杂着鲜血纷飞，从来死节为报国难道还求著功勋？\n你没看见拼杀在沙场战斗多惨苦，现在还在思念有勇有谋的李将军。",
    s: "《燕歌行》是高适的代表作，也是唐代边塞诗的杰作。全诗以一次战役为线索，揭露了军中苦乐不均的现实——“战士军前半死生，美人帐下犹歌舞”，对将领的骄奢轻敌进行了尖锐批判，同时对士兵的英勇牺牲表示深切同情。全诗气势雄浑，笔力苍劲，思想深刻。"
  },
  "别董大二首·一|高适": {
    y: "千里黄云遮天蔽日，天气阴沉，北风送走雁群又吹来纷扬大雪。\n不要担心前路茫茫没有知己，天下还有谁不认识你呢？",
    s: "《别董大》是高适送别友人董庭兰的名作，一反送别诗的伤感低沉，以“莫愁前路无知己，天下谁人不识君”的豪迈之语激励友人，充满信心和力量。全诗意境开阔，格调高昂，是送别诗中的佳作。"
  },
  "逢入京使|岑参": {
    y: "向东遥望长安家园路途遥远，思乡之泪沾湿双袖难擦干。\n在马上匆匆相逢没有纸和笔，只有托你捎个口信，给家人报平安。",
    s: "《逢入京使》是岑参西行途中所作，写在路上偶遇入京使者，托他捎口信回家报平安的情景。“马上相逢无纸笔，凭君传语报平安”两句，语言朴素自然，却将游子的思乡之情和对家人的牵挂写得真挚动人，是唐诗中最感人的思乡名篇之一。"
  },
  "将进酒|李白": {
    y: "你难道看不见，黄河之水从天上奔腾而来，波涛翻滚直奔东海，再也不会回流。\n你难道看不见，年迈的父母对着明镜悲叹白发，早晨还是青丝般的黑发，傍晚就变得如雪般洁白。\n人生得意之时就应当纵情欢乐，不要让金杯空对着皎洁的明月。\n上天造就了我这样的人才，就一定有我的用处，黄金千两一挥而尽，也还会重新得来。\n烹羊宰牛姑且尽情享乐，今日相逢，应当一口气喝上三百杯。\n岑夫子、丹丘生，快喝酒吧，不要停下酒杯。\n我为你们唱一首歌，请你们为我侧耳倾听。\n钟鸣鼎食的荣华富贵都不值得珍贵，只希望长久沉醉，再也不愿清醒。\n自古以来的圣贤都寂然无名，只有善饮的人才能留下美名。\n当年陈王曹植在平乐观大摆酒宴，一斗酒价值万钱，却恣意纵情欢饮。\n主人怎么说钱不够了呢？只管去买酒来和我对饮。\n名贵的五花马、价值千金的狐裘，快叫孩子拿去换美酒，让我们一同消解这万古的长愁。",
    s: "《将进酒》是李白豪放诗的巅峰之作，以黄河奔涌起兴，以时光易逝落笔，将怀才不遇的愤懑与人生旷达的豪情融为一体。全诗气势磅礴、情感跌宕，“天生我材必有用”更是成为千古励志名句，是中国人最熟悉的唐诗代表作之一。"
  },
  "相和歌辞·蜀道难|李白": {
    y: "唉呀呀！多么高峻伟岸！蜀道难以攀越，简直难于上青天。\n传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。\n从那时至今约有四万八千年了吧，秦蜀被秦岭所阻从不沟通往返。\n西边太白山高峻无路只有飞鸟可通行，飞鸟可以直通峨眉山巅。\n山崩地裂，埋葬了五位开山英雄壮士，这样高险的山路和栈道才相互勾连。\n蜀中上有挡住太阳神六龙车的山巅，下有激浪排空曲折的大川。\n善于高飞的黄鹤尚且无法飞过，即使猢狲要想翻过也愁于攀援。\n青泥岭的泥路曲曲弯弯，百步九折萦绕着山峦。\n屏住呼吸仰头就可触摸参星和井星，紧张得透不过气来，用手抚胸惊恐不已徒长吁短叹。\n好朋友呵请问你西游何时回还？可怕的岩山栈道实在难以登攀！\n只见那悲鸟在古树上哀鸣啼叫，雄雌相随飞翔在树丛之间。\n月夜又听到杜鹃凄凉悲啼，在空山中传响令人愁思绵绵。\n蜀道难以攀越呵简直难于上青天，使人听到这些怎么不脸色突变？\n山峰座座相连离天还不到一尺，枯松老枝倒挂倚贴在绝壁之间。\n漩涡飞转瀑布飞泻争相喧闹着，飞流撞击着巨石在山谷中滚动像万壑鸣雷一般。\n这样危险的地方，唉呀呀你这个远方而来的客人，为什么非要来这里不可呀？\n剑阁所在崇峻巍峨高入云端，只要一人把守千军万马难攻占。\n驻守的官员倘若不是可信赖的人，难免要变为豺狼，据险作乱。\n每日每夜都要躲避猛虎和长蛇，它们磨牙吮血，杀人如麻。\n锦官城虽然说是个快乐的所在，如此险恶还不如早早地把家还。\n蜀道难以攀越呵简直难于上青天，侧身西望令人不免感慨与长叹！",
    s: "《蜀道难》是李白浪漫主义诗歌的代表作，以雄奇奔放的笔调描绘了蜀道的艰险壮丽。全诗以“蜀道之难，难于上青天”为主旋律，三次反复出现，一唱三叹，气势磅礴。诗人运用夸张、想象、神话传说等手法，将蜀道的奇险写得惊心动魄，是唐诗中最具想象力的杰作。"
  },
  "望庐山瀑布水二首·二|李白": {
    y: "香炉峰在阳光的照射下生起紫色烟霞，从远处看去瀑布好似白色绢绸悬挂山前。\n高崖上飞腾直落的瀑布好像有几千尺，让人怀疑是银河从天上泻落到人间。",
    s: "《望庐山瀑布》是李白山水诗的代表作，“飞流直下三千尺，疑是银河落九天”以极度夸张的手法和奇特的想象，将庐山瀑布的雄伟壮丽写得淋漓尽致，是中国诗歌史上最著名的咏瀑名句。全诗气势磅礴，想象奇绝，充分体现了李白浪漫主义的诗风。"
  },
  "赠汪伦|李白": {
    y: "李白乘舟将要远行离去，忽听岸上传来踏歌之声。\n即使桃花潭水深至千尺，也比不上汪伦送我之情。",
    s: "《赠汪伦》是李白写给友人汪伦的赠别诗，“桃花潭水深千尺，不及汪伦送我情”以潭水之深比喻友情之深，形象生动，情感真挚。全诗语言朴素自然，充满生活气息，是唐诗中最脍炙人口的赠别名篇。"
  },
  "行路难三首·一|李白": {
    y: "金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。\n心中郁闷，我放下杯筷不愿进餐；拔出宝剑环顾四周，心里一片茫然。\n想渡黄河，冰雪却冻封了河川；想登太行山，莽莽风雪早已封山。\n像姜尚垂钓溪，闲待东山再起；又像伊尹做梦，他乘船经过日边。\n人生道路多么艰难，多么艰难；歧路纷杂，如今又身在何处？\n相信乘风破浪的时机总会到来，到时定要扬起征帆，横渡沧海！",
    s: "《行路难》是李白在仕途受挫时所作，全诗情感跌宕起伏，从“停杯投箸不能食”的苦闷茫然，到“长风破浪会有时，直挂云帆济沧海”的豪迈自信，展现了诗人虽身处逆境却依然乐观进取的精神。结尾两句是千古传诵的励志名句。"
  },
  "梦游天姥吟留别|李白": {
    y: "听海外来客们谈起瀛洲，在烟波浩渺的遥远地方，实在难以找到。\n越中来人说起天姥山，在云霞的明灭掩映之间有时候能看见。\n天姥山高耸入云，连着天际，横向天外；山势高峻超过五岳，遮掩过赤城山。\n天姥山极为高峻，就连四万八千丈高的天台山，面对着它好像要向东南倾斜拜倒一样。\n我想根据越人说的话梦游到吴越，一天夜晚飞渡过明月映照下的镜湖。\n镜湖上的月光照着我的身影，一直送我到剡溪。\n谢灵运住的地方如今还在，清澈的湖水荡漾，猿猴清啼。\n我脚上穿着谢公当年特制的木鞋，攀登直上云霄的山路。\n上到半山腰就看见了从海上升起的太阳，空中传来天鸡报晓的啼鸣之声。\n无数山岩重叠，道路盘旋弯曲，方向不定，迷恋着花，依倚着石头，不觉天色已晚。\n熊在怒吼，龙在长鸣，岩中的泉水在震响，使深林战栗，使层巅震惊。\n云层黑沉沉的，像是要下雨，水波动荡生起了薄薄的烟雾。\n电光闪闪，雷声轰鸣，山峰好像要被崩塌似的。\n仙府的石门，訇的一声从中间打开。\n洞中蔚蓝的天空广阔无际，看不到尽头，日月照耀着金银做的宫阙。\n用彩虹做衣裳，将风作为马来乘，云中的神仙们纷纷下来。\n老虎弹奏着琴瑟，鸾鸟拉着车。仙人们排成列，多如密麻。\n忽然魂魄惊动，我猛然惊醒，不禁长声叹息。\n醒来时身边只有枕席，刚才梦中所见的烟雾云霞全都消失了。\n人世间的欢乐也是像梦中的幻境这样，自古以来万事都像东流的水一样一去不复返。\n告别诸位朋友远去东鲁啊，什么时候才能回来？暂且把白鹿放牧在青崖间，等到要远行时就骑上它访名山。\n岂能卑躬屈膝去侍奉权贵，让自己不能有舒心畅意的笑颜！",
    s: "《梦游天姥吟留别》是李白浪漫主义诗歌的代表作，通过梦游天姥山的奇幻经历，描绘了一个瑰丽多彩的神仙世界。全诗想象奇绝，气势磅礴，结尾“安能摧眉折腰事权贵，使我不得开心颜”点明主旨，表达了诗人蔑视权贵、追求自由的崇高品格。"
  },
  "独坐敬亭山|李白": {
    y: "山中群鸟一只只高飞远去，天空中的最后一片白云也悠然飘走。\n敬亭山和我对视着，谁都看不够，看不厌，看来理解我的只有这敬亭山了。",
    s: "《独坐敬亭山》是李白晚年所作，以拟人手法写人与山的相知相惜。“相看两不厌，只有敬亭山”将山人格化，表达了诗人在孤独中寻求慰藉的心境，含蓄深沉，余味无穷。全诗意境清幽，是李白五绝的代表作。"
  },
  "秋浦歌十七首·十五|李白": {
    y: "白发长达三千丈，是因为愁才长得这样长。\n不知在明镜之中，是何处的秋霜落在了我的头上？",
    s: "《秋浦歌》以“白发三千丈”的极度夸张开篇，将愁思之深之长写得惊心动魄。“缘愁似个长”点明白发因愁而生，后两句以问语作结，含蓄深沉。全诗仅二十字，却将怀才不遇的悲愤写得淋漓尽致，是李白浪漫主义夸张手法的典范。"
  },
  "客中行|李白": {
    y: "兰陵美酒甘醇醉人散发着郁金的香气，盛满玉碗色泽如琥珀般清莹秀彻。\n只要主人同我一道尽兴畅饮，一醉方休，我哪管这里是故乡还是异乡呢！",
    s: "《客中行》一反游子思乡的传统主题，以豁达豪迈的笔调写客中之乐。“但使主人能醉客，不知何处是他乡”表达了诗人随遇而安、四海为家的豪迈胸襟，全诗色彩明丽，情调欢快，是李白七绝中的佳作。"
  },
  "登高|杜甫": {
    y: "风势迅急，天空高远，猿猴的啼声十分哀切；水清沙白的洲渚上，鸟儿在空中盘旋飞翔。\n无边无际的树叶萧萧飘落，奔流不息的长江滚滚而来。\n漂泊万里，常年客居他乡，更添悲秋情绪；一生多病，今日独自登上高台。\n历尽艰难困苦，白发长满了双鬓；穷困潦倒，偏偏又刚刚停下了浇愁的酒杯。",
    s: "《登高》被后世称为“古今七言律诗第一”，全诗四联皆对，格律严整却浑然天成。前四句写景，雄浑苍凉；后四句抒情，沉郁顿挫，将身世飘零、老病孤愁与家国动荡融为一体，是杜甫“沉郁顿挫”诗风的集中体现。"
  },
  "登岳阳楼|杜甫": {
    y: "以前就听说洞庭湖波澜壮阔，今日终于如愿登上岳阳楼。\n浩瀚的湖水把吴楚两地分隔开来，整个天地仿似在湖中日夜浮动。\n亲朋好友们音信全无，年老多病只有一只船孤零零的陪伴自己。\n关山以北战争烽火仍未止息，凭栏遥望胸怀家国泪水横流。",
    s: "《登岳阳楼》是杜甫晚年漂泊湖南时所作，“吴楚东南坼，乾坤日夜浮”写洞庭湖的壮阔，气象万千，与孟浩然“气蒸云梦泽，波撼岳阳城”并为咏洞庭绝唱。后四句由景入情，将个人身世之悲与国家战乱之忧融为一体，沉郁顿挫，感人至深。"
  },
  "江畔独步寻花七绝句·六|杜甫": {
    y: "黄四娘家周围的小路旁开满了鲜花，千朵万朵鲜花把枝条都压得低垂了。\n嬉闹的彩蝶恋恋不舍地盘旋飞舞，自由自在的小黄莺在花间不断欢唱。",
    s: "《江畔独步寻花》是杜甫在成都草堂时的组诗，这一首描写了春日繁花似锦、蝶舞莺啼的美好景象。全诗语言明快，色彩明丽，充满生活气息，展现了杜甫诗歌中轻松愉悦的一面，是描写春景的名篇。"
  },
  "绝句四首·三|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，全诗四句四景，“两个黄鹂鸣翠柳，一行白鹭上青天”色彩明丽，“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗对仗工整，是杜甫七绝的代表作。"
  },
  "石壕吏|杜甫": {
    y: "日暮时投宿石壕村，夜里有差役来强征兵。\n老翁越墙逃走，老妇出门应付。\n差役喊叫得是那样凶狠，老妇人啼哭得是那样悲伤。\n我听到老妇上前说：我的三个儿子去参加邺城之战。\n其中一个儿子捎信回来，说另外两个儿子刚刚战死。\n活着的人姑且活一天算一天，死去的人就永远不会复生了！\n家里再也没有别的男人了，只有个正在吃奶的小孙子。\n因为有小孙子在，他母亲还没有离去，但进进出出连一件完好的衣裳都没有。\n老妇虽然年老力衰，但请允许我跟从你连夜赶回营去。\n赶快到河阳去应征，还能够为部队准备早餐。\n夜深了，说话的声音逐渐消失，隐隐约约听到低微断续的哭泣声。\n天亮后我继续赶路，只能与返回家中的那个老翁告别。",
    s: "《石壕吏》是杜甫“三吏三别”之一，通过作者亲眼所见的石壕吏乘夜捉人的故事，揭露了封建统治者的残暴，反映了安史之乱给人民带来的深重灾难。全诗以白描手法叙事，情感深沉，是杜甫现实主义诗歌的杰作，被称为“诗史”。"
  },
  "赠花卿|杜甫": {
    y: "锦官城里每日音乐声轻柔悠扬，一半随着江风飘去，一半飘入了云端。\n这样的乐曲只应该天上有，人世间芸芸众生哪里能听见几回？",
    s: "《赠花卿》表面上赞美乐曲的美妙，“此曲只应天上有，人间能得几回闻”是千古传诵的名句。实际上，花卿是武将，却僭用天子礼乐，杜甫此诗暗含讽喻，意在言外，含蓄委婉，是杜诗中“寓讽于颂”的佳作。"
  },
  "长恨歌|白居易": {
    y: "唐明皇爱好女色一心想要得到绝世美人，登基多年却始终未能求得。\n杨家有个女儿刚刚长大，十分娇艳，养在深闺中，外人不知她美丽绝伦。\n天生丽质让她很难埋没世间，终于有一天被选到皇帝身边。\n她回眸一笑时，千姿百态、娇媚横生；六宫妃嫔，一个个都黯然失色。\n春寒料峭时，皇上赐她到华清池沐浴，温润的泉水洗涤着凝脂一般的肌肤。\n侍女搀扶她，如出水芙蓉软弱娉婷，由此开始得到皇帝恩宠。\n鬓发如云颜脸似花，头戴着金步摇。温暖的芙蓉帐里，与皇上共度春宵。\n春宵苦短，一觉睡到太阳高高升起，从此君王再也不早朝了。\n承欢侍宴，忙碌得没有片刻闲暇，春日陪皇上一起出游，晚上夜夜侍寝。\n后宫中妃嫔不下三千人，却只有她独享皇帝的恩宠。\n金屋中梳妆打扮，夜夜撒娇不离君王；玉楼上酒酣宴罢，醉意更添几许风韵。\n兄弟姐妹都因她列土封侯，杨家门楣光耀令人羡慕。\n于是使得天下的父母都改变了心意，不重视生男孩，只重视生女孩。\n骊山上华清宫内玉宇琼楼高耸入云，清风过处仙乐飘向四面八方。\n轻歌曼舞多合拍，管弦旋律尽传神，君王终日观看，却百看不厌。\n渔阳叛乱的战鼓震耳欲聋，宫中的霓裳羽衣曲被惊破。\n九重宫殿霎时尘土飞扬，君王带着大批臣工美眷向西南逃亡。\n车队走走停停，西出长安才百余里。\n六军停滞不前，要求赐死杨玉环，君王无可奈何，只得在马嵬坡下缢杀杨玉环。\n贵妃头上的饰品，抛撒满地无人收拾。翠翘金雀玉搔头，珍贵头饰一根根。\n君王欲救不能，掩面而泣，回头看贵妃惨死的场景，血泪止不住地流。\n秋风萧索扫落叶，黄土尘埃已消遁，回环曲折穿栈道，车队踏上了剑阁古道。\n峨眉山下行人稀少，旌旗无色，日月无光。\n蜀地山清水秀，引得君王相思情。行宫里望月满目凄然，雨夜听曲声声带悲。\n叛乱平息后，君王重返长安，路过马嵬坡，睹物思人，徘徊不前。\n马嵬坡下荒凉的泥土中，不见美人，空留她死去的地方。\n君臣相顾，泪湿衣衫，东望京都，信马由缰回到宫中。\n回来一看，池苑依旧，太液池的芙蓉，未央宫的垂柳。\n芙蓉像她的脸，柳叶像她的眉，面对此景怎么能不落泪。\n春风吹开桃李花的日子，秋雨打落梧桐叶的时候。\n西宫南苑长满秋草，落叶满阶也无人打扫。\n梨园弟子新添了白发，椒房的宫女也已老去。\n夜晚殿上萤火虫飞过，思绪悄然，孤灯挑尽也无法入眠。\n钟鼓声迟迟响起，夜才刚刚开始，银河耿耿，天快亮了。\n鸳鸯瓦上结了厚厚的霜，翡翠被里谁与我共眠。\n生死离别已经一年，你的魂魄却不曾入我梦来。\n有个临邛道士客居长安，能用精诚招来亡魂。\n感念君王辗转反侧的思念，于是让方士殷勤寻觅。\n驾驭云气如闪电般奔驰，升上天入地下到处寻找。\n上到九天，下到黄泉，两处茫茫都不见。\n忽然听说海上有座仙山，山在虚无缥缈之间。\n玲珑楼阁在五彩云中升起，其中有许多风姿绰约的仙子。\n其中有一人字太真，雪肤花貌，仿佛就是她。\n金阙西厢叩响玉门，转告小玉、双成去通报。\n听说汉家天子派来使者，九华帐里梦魂惊醒。\n披上衣服推开枕头起身徘徊，珠帘银屏一路打开。\n云鬓半偏，刚睡醒，花冠不整就走下堂来。\n风吹衣袖飘飘举起，还像当年跳霓裳羽衣舞。\n玉容寂寞，泪水纵横，像一枝春天带雨的梨花。\n含情凝视，感谢君王，一别之后音容两渺茫。\n昭阳殿里的恩爱已经断绝，蓬莱宫中的岁月漫长。\n回头下望人间，看不见长安，只见尘雾。\n只能用旧物表达深情，把钿合金钗捎去。\n钗留一股，盒留一扇，掰开黄金钗，分开钿合。\n只要心像金钿一样坚贞，天上人间终会相见。\n临别时又殷勤寄语，话中有誓言只有两人知道。\n七月七日长生殿，夜半无人私语时。\n在天上愿做比翼双飞鸟，在地上愿做连理并生枝。\n天长地久也有穷尽的时候，这遗恨却永远没有尽头。",
    s: "《长恨歌》是白居易最著名的长篇叙事诗，以唐玄宗和杨贵妃的爱情故事为主线，将历史与传说、写实与浪漫融为一体。“在天愿作比翼鸟，在地愿为连理枝”“天长地久有时尽，此恨绵绵无绝期”成为千古传诵的爱情名句。全诗叙事曲折，抒情缠绵，语言优美，是中国古典诗歌中最伟大的爱情诗篇。"
  },
  "琵琶引|白居易": {
    y: "秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。\n我下马和客人在船上饯别设宴，举起酒杯要饮却无助兴的管弦。\n酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。\n忽听得江面上传来琵琶清脆声，我忘却了回归客人也不想动身。\n循身轻轻探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。\n我们移船靠近邀请她出来相见，叫下人添酒回灯重新摆起酒宴。\n千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。\n转紧琴轴拨动琴弦试弹了几声，尚未成曲调那形态就非常有情。\n弦弦凄楚悲切声音隐含着沉思，似乎在诉说着她平生的不得志。\n她低着头随手连续地弹个不停，用琴声把心中无限的往事说尽。\n轻轻抚拢慢慢捻滑抹了又加挑，初弹霓裳羽衣曲接着再弹六幺。\n大弦浑宏悠长嘈嘈如暴风骤雨，小弦和缓幽细切切如有人私语。\n嘈嘈声切切声互为交错地弹奏，就像大珠小珠一串串掉落玉盘。\n琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉。\n水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。\n像另有一种愁思幽恨暗暗滋生，此时闷闷无声却比有声更动人。\n突然间好像银瓶撞破水浆四溅，又好像铁甲骑兵厮杀刀枪齐鸣。\n一曲终了她对准琴弦中心划拨，四弦一声轰鸣好像撕裂了布帛。\n东船西舫人们都静悄悄地聆听，只见江心之中映着白白秋月影。\n她沉吟着收起拨片插在琴弦中，整顿衣裳依然显出庄重的颜容。\n她说我原是京城负有盛名的歌女，老家住在长安城东南的虾蟆陵。\n弹奏琵琶技艺十三岁就已学成，教坊乐团第一队中列有我姓名。\n每曲弹罢都令艺术大师们叹服，每次妆成都被同行歌妓们嫉妒。\n京都豪富子弟争先恐后来献彩，弹完一曲收来的红绡不知其数。\n钿头银篦打节拍常常断裂粉碎，红色罗裙被酒渍染污也不后悔。\n年复一年都在欢笑打闹中度过，秋去春来美好的时光白白消磨。\n兄弟从军姊妹死家道已经破败，暮去朝来我也渐渐地年老色衰。\n门前车马减少光顾者落落稀稀，青春已逝我只得嫁给商人为妻。\n商人重利不重情常常轻易别离，上个月他去浮梁做茶叶的生意。\n他去了留下我在江口孤守空船，秋月与我作伴绕舱的秋水凄寒。\n更深夜阑常梦少年时作乐狂欢，梦中哭醒纵横了泪水和脂粉。\n我听了琵琶声早已摇头叹息，又听到她这番诉说更加歔欷。\n同样都是天涯沦落的可怜人，今日相逢何必问是否曾经相识！\n自从去年我离开繁华长安京城，被贬居住在浔阳江畔常常卧病。\n浔阳这地方荒凉偏僻没有音乐，一年到头也听不到管弦的乐器声。\n住在湓江附近低洼潮湿的地方，黄芦和苦竹绕着宅第丛生。\n在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。\n春江花朝秋江月夜那样好光景，也无可奈何常常取酒独酌独饮。\n难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。\n今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。\n请你不要推辞坐下来再弹一曲，我要为你创作一首新诗琵琶行。\n被我的话所感动她站立了好久，回身坐下再转紧琴弦拨出急声。\n凄凄切切不再像刚才那种声音，在座的人重听都掩面哭泣不停。\n要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！",
    s: "《琵琶行》是白居易贬官江州时所作，通过描写琵琶女的高超技艺和不幸身世，抒发了自己被贬的愤懑之情。“同是天涯沦落人，相逢何必曾相识”是千古传诵的名句，将诗人与琵琶女的命运联系在一起，感人至深。诗中对琵琶音乐的描写更是出神入化，“大珠小珠落玉盘”“此时无声胜有声”等句成为描写音乐的经典。"
  },
  "忆江南·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "新乐府·卖炭翁	苦官市也|白居易": {
    y: "有位卖炭的老翁，整年在南山里砍柴烧炭。\n他满脸灰尘，显出被烟熏火燎的颜色，两鬓头发灰白，十个手指也被炭烧得很黑。\n卖炭得到的钱用来干什么？买身上穿的衣裳和嘴里吃的食物。\n可怜他身上只穿着单薄的衣服，心里却担心炭卖不出去，还希望天更寒冷。\n夜里城外下了一尺厚的大雪，清晨，老翁驾着炭车碾轧冰冻的车轮印往集市上赶去。\n牛累了，人饿了，但太阳已经升得很高了，他们就在集市南门外泥泞中歇息。\n那得意忘形的骑着两匹马的人是谁啊？是皇宫内的太监和太监的手下。\n太监手里拿着文书，嘴里却说是皇帝的命令，吆喝着牛朝皇宫拉去。\n一车的炭，一千多斤，太监差役们硬是要赶着走，老翁是百般不舍，但又无可奈何。\n那些人把半匹红纱和一丈绫，朝牛头上一挂，就充当炭的价钱了。",
    s: "《卖炭翁》是白居易《新乐府》中的名篇，通过卖炭翁的遭遇，深刻揭露了宫市制度的罪恶，对劳动人民寄予深切同情。“可怜身上衣正单，心忧炭贱愿天寒”将老人矛盾的心理写得入木三分，是白居易现实主义诗歌的代表作。"
  },
  "金陵五题·乌衣巷|刘禹锡": {
    y: "朱雀桥边冷落荒凉，野草丛生，开出了野花；乌衣巷口断壁残垣，正是夕阳西斜。\n当年王导、谢安檐下的燕子，如今已飞进寻常百姓家中。",
    s: "《乌衣巷》是刘禹锡《金陵五题》中最著名的一首，通过乌衣巷的今昔对比，抒发了对世事沧桑、富贵无常的感慨。“旧时王谢堂前燕，飞入寻常百姓家”以燕子的变迁写尽历史兴亡，含蓄深沉，是咏史怀古诗的杰作。"
  },
  "望洞庭|刘禹锡": {
    y: "洞庭湖水色与月光互相辉映，湖面风平浪静，犹如未磨的铜镜。\n远远眺望洞庭湖山水苍翠如墨，好似白银盘里托着一枚青螺。",
    s: "《望洞庭》以奇特的比喻描绘了洞庭湖的秋夜美景，“白银盘里一青螺”将洞庭湖比作白银盘，将君山比作青螺，想象奇特，形象生动。全诗意境优美，格调清新，是描写洞庭湖的名篇。"
  },
  "雁门太守行|李贺": {
    y: "敌兵滚滚而来，犹如黑云翻卷，想要摧倒城墙；战士们的铠甲在阳光照射下金光闪烁。\n号角声响彻秋夜的长空，边塞上将士的血迹在寒夜中凝为紫色。\n红旗半卷，援军赶赴易水；夜寒霜重，鼓声郁闷低沉。\n为了报答国君的赏赐和厚爱，手操宝剑甘愿为国血战到死。",
    s: "《雁门太守行》是李贺的代表作，“黑云压城城欲摧”以夸张手法渲染敌军兵临城下的紧张气氛，“甲光向日金鳞开”写守军的严阵以待。全诗色彩浓烈，意境悲壮，“报君黄金台上意，提携玉龙为君死”表达了将士誓死报国的决心，是李贺诗风的典型体现。"
  },
  "李凭箜篌引|李贺": {
    y: "在深秋的夜晚，弹奏起吴丝蜀桐制成精美的箜篌。听到美妙的乐声，天空的白云凝聚起来不再飘游。\n湘娥把泪珠洒满斑竹，九天素女也牵动满腔忧愁。出现这种情况，是由于乐工李凭在京城弹奏箜篌。\n乐声清脆动听得就像昆仑山美玉击碎，凤凰鸣叫；时而使芙蓉在露水中饮泣，时而使香兰开怀欢笑。\n清脆的乐声，融和了长安城十二门前的清冷光气。二十三根弦丝高弹轻拨，打动了高高在上的天帝。\n高亢的乐声直冲云霄，冲上女娲炼石补过的天际。好似补天的五彩石被击破，逗落了漫天绵绵秋雨。\n幻觉中仿佛乐工进入了神山，把技艺向女仙传授；老鱼兴奋得在波中跳跃，瘦蛟也翩翩起舞乐悠悠。\n月宫中吴刚被乐声吸引，彻夜不眠在桂树下逗留。桂树下的兔子也伫立聆听，不顾露珠斜飞寒飕飕！",
    s: "《李凭箜篌引》是李贺描写音乐的名篇，与白居易《琵琶行》、韩愈《听颖师弹琴》并为唐诗中写音乐的三大杰作。诗人以奇特的想象和夸张的手法，将箜篌声的美妙写得惊心动魄，“昆山玉碎凤凰叫”“石破天惊逗秋雨”等句想象奇绝，充分体现了李贺“诗鬼”的艺术特色。"
  },
  "乐游原|李商隐": {
    y: "傍晚时分我心情不太好，独自驱车登上了乐游原。\n这夕阳晚景的确十分美好，只不过已是黄昏。",
    s: "《登乐游原》仅二十字，却蕴含着深沉的哲理。“夕阳无限好，只是近黄昏”既写出了夕阳的美丽，又感叹好景不长，既有对美好事物的珍惜，又有对时光流逝的无奈，成为千古传诵的名句。"
  },
  "常娥|李商隐": {
    y: "云母屏风上烛影暗淡，银河渐渐斜落，晨星也隐没低沉。\n嫦娥应该后悔偷取了长生不老之药，如今空对碧海青天夜夜孤寂。",
    s: "《嫦娥》借嫦娥奔月的神话故事，抒发了诗人孤寂清高的心境。“嫦娥应悔偷灵药，碧海青天夜夜心”以嫦娥的孤独比喻自己的处境，含蓄深沉，意境悠远，是李商隐七绝中的佳作。"
  },
  "阿房宫赋|杜牧": {
    y: "六国灭亡，四海统一；蜀地的山变得光秃秃了，阿房宫建造出来了。它从渭南到咸阳覆盖了三百多里地，宫殿高耸，遮天蔽日。它从骊山北边建起，折而向西，一直通到咸阳。渭水、樊川浩浩荡荡的，流进宫墙里边。五步一座楼，十步一个阁；走廊如绸带般萦回，牙齿般排列的飞檐像鸟嘴向高处啄着。楼阁各依地势的高低倾斜而建筑，低处的屋角钩住高处的屋心，并排相向的屋角彼此相斗。盘结交错，曲折回旋，远观鸟瞰，建筑群如密集的蜂房，如旋转的水涡，高高地耸立着，不知道它有几千万座。没有起云，为什么有龙？原来是一座长桥躺在水波上。不是雨过天晴，为什么出虹？原来是天桥在空中行走。房屋忽高忽低，幽深迷离，使人不能分辨东西。歌台上由于歌声响亮而充满暖意，有如春光融和；舞殿上由于舞袖飘拂而充满寒意，有如风雨凄凉。一天里边，一座宫殿中间，气候却不一样。\n六国的宫妃、王子王孙，辞别六国的宫楼，走下六国的宫殿，坐着辇车来到秦国。他们早上歌唱，晚上奏乐，成为秦国的宫人。明亮的星星晶莹闪烁，这是宫妃们打开了梳妆的镜子；乌青的云朵纷纷扰扰，这是宫妃们在梳理晨妆的发髻；渭水涨起一层油腻，这是宫妃们抛弃了的胭脂水；烟霭斜斜上升，云雾横绕空际，这是宫中在焚烧椒、兰制的香料；雷霆突然震响，这是宫车驶过去了；辘辘的车声越听越远，无影无踪，不知道它去到什么地方。每一片肌肤，每一种容颜，都美丽娇媚得无以复加。宫妃们久久地站着，远远地探视，盼着皇帝来临。有的宫女竟整整三十六年没能见到皇帝。\n燕赵、韩魏收藏的金玉珍宝，齐楚精华的财富，是多少代多少年，从人民那里抢来的，堆叠得像山一样。一旦国家灭亡，不能占有了，统统运进了阿房宫。把宝鼎当作铁锅，把美玉当作石头，把黄金当作土块，把珍珠当作沙石，随意丢弃，秦人看见了也不觉得可惜。\n唉！一个人的想法和千万人的想法是一样的。秦始皇喜爱奢侈，老百姓也顾念自己的家业。为什么搜刮老百姓的财物一分一厘都不放过，挥霍时却像泥沙一样毫不珍惜呢？让那承担栋梁的柱子，比田地里的农夫还多；架在梁上的椽子，比织机上的女工还多；梁柱上的钉头光彩耀目，比粮仓里的粟粒还多；瓦楞长短不一，比全身的丝缕还多；或直或横的栏杆，比九州的城郭还多；管弦的声音嘈杂，比市民的言语还多。使天下的人民，口里不敢说，心里却敢愤怒。可是失尽人心的秦始皇，一天天更加骄傲顽固。结果戍边的陈胜、吴广一声呼喊，函谷关被攻下，楚兵一把大火，可惜阿房宫化为一片焦土。\n唉！灭亡六国的是六国自己，不是秦国啊。消灭秦王朝的是秦王朝自己，不是天下的人啊。可叹呀！假使六国各自爱护它的人民，就完全可以依靠人民来抵抗秦国。假使秦王朝又爱护六国的人民，那么皇位就可以传到三世还可以传到万世做皇帝，谁能够族灭它呢？秦人来不及哀悼自己，而后人替他们哀伤；如果后人哀悼他却不把他作为鉴戒吸取教训，也只会使更后的人又来哀悼这后人啊。",
    s: "《阿房宫赋》是杜牧的代表作，借秦王朝因奢侈荒淫而亡国的历史教训，讽喻当时的统治者。“灭六国者六国也，非秦也；族秦者秦也，非天下也”“后人哀之而不鉴之，亦使后人而复哀后人也”是千古传诵的名句，寓意深刻。全文辞藻华丽，气势磅礴，是唐代文赋的典范。"
  },
  "赤壁|杜牧": {
    y: "赤壁的泥沙中，埋着一枚未锈尽的断戟。自己磨洗后发现这是当年赤壁之战的遗留之物。\n倘若不是东风给周瑜以方便，结局恐怕是曹操取胜，二乔被关进铜雀台了。",
    s: "《赤壁》是杜牧咏史诗的代表作，借赤壁之战的历史事件，以“东风不与周郎便，铜雀春深锁二乔”的假设，表达了对历史兴亡的独特见解。全诗以小见大，含蓄深沉，是咏史诗中的杰作。"
  },
  "江南春绝句|杜牧": {
    y: "辽阔的江南，到处莺歌燕舞，绿树红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的许多座古寺，如今有多少笼罩在这蒙胧烟雨之中。",
    s: "《江南春》以极简练的笔触描绘了江南春天的美丽景象，“千里莺啼绿映红”从听觉和视觉写江南春景，“南朝四百八十寺，多少楼台烟雨中”在写景中融入历史兴亡的感慨，意境深远，是描写江南春景的千古名篇。"
  },
  "枫桥夜泊|张继": {
    y: "月亮已落下乌鸦啼叫寒气满天，江边枫树与船上渔火，难抵我独自傍愁而眠。\n姑苏城外那寂寞清静寒山古寺，半夜里敲钟的声音传到了客船。",
    s: "《枫桥夜泊》是张继最著名的诗作，描写了夜泊枫桥的所见所闻所感。“月落乌啼霜满天”渲染了凄清的氛围，“姑苏城外寒山寺，夜半钟声到客船”以钟声衬托夜的寂静和诗人的愁思，意境悠远，是唐诗中最著名的羁旅诗之一，寒山寺也因此诗名扬天下。"
  },
  "题都城南庄|崔护": {
    y: "去年的这个时候，我从这扇门里望去，只见那美丽的脸庞和桃花彼此相互映衬的绯红。\n今日再来此地，那佳人已不知所踪，只有桃花依旧，含笑怒放春风之中。",
    s: "《题都城南庄》以“人面”“桃花”为线索，通过去年与今年的对比，抒发了物是人非的惆怅。“人面不知何处去，桃花依旧笑春风”成为千古传诵的名句，全诗意境优美，情感含蓄，是唐诗中最脍炙人口的作品之一。"
  },
  "古风二首·二|李绅": {
    y: "盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？",
    s: "《悯农》是李绅最著名的诗作，“谁知盘中餐，粒粒皆辛苦”以朴素的语言道出了粮食的来之不易，告诫人们珍惜粮食、尊重劳动。全诗语言浅近，寓意深刻，是中国流传最广的诗篇之一。"
  },
  "离思五首·四|元稹": {
    y: "经历过波澜壮阔的大海，别处的水再也不值得一观。陶醉过巫山的云雨的梦幻，别处的风景就不称之为云雨了。\n即使身处万花丛中，我也懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。",
    s: "《离思》是元稹悼念亡妻韦丛所作，“曾经沧海难为水，除却巫山不是云”以沧海之水和巫山之云比喻爱情的深广与美好，表达了对亡妻的忠贞不渝。全诗情感真挚，意境深远，是中国文学史上最著名的悼亡诗之一。"
  },
  "菊花|元稹": {
    y: "一丛一丛的秋菊环绕着房屋，好似到了陶渊明的家。绕着篱笆观赏菊花，不知不觉太阳已经快落山了。\n不是因为百花中偏爱菊花，只是因为菊花开过之后，再不能够看到好花了。",
    s: "《菊花》是元稹咏菊的名篇，“不是花中偏爱菊，此花开尽更无花”点明了爱菊的原因，既写出了菊花在深秋独放的特点，也暗含了对菊花坚贞品格的赞美。全诗语言朴素，构思巧妙，是咏菊诗中的佳作。"
  },
  "凉州词二首·一|王翰": {
    y: "酒筵上甘醇的葡萄美酒盛满在夜光杯之中，正要畅饮时，马上琵琶也声声响起，仿佛催人出征。\n如果醉卧在沙场上，也请你不要笑话，古来出外打仗的能有几人返回家乡？",
    s: "《凉州词》是王翰的代表作，描写了边塞将士在出征前开怀畅饮的场景。“醉卧沙场君莫笑，古来征战几人回”以豪迈旷达的语气写出了战争的残酷和将士们视死如归的气概，全诗格调苍凉而豪放，是唐代边塞诗的名篇。"
  },
  "回乡偶书二首·一|贺知章": {
    y: "年少时离乡老年才归家，我的乡音虽未改变，但鬓角的毛发却已经疏落。\n家乡的儿童们看见我，没有一个认识我。他们笑着询问我：你是从哪里来的呀？",
    s: "《回乡偶书》是贺知章八十多岁告老还乡时所作，“少小离家老大回，乡音无改鬓毛衰”写出了久客他乡的感慨，“儿童相见不相识，笑问客从何处来”以儿童的天真提问，反衬出诗人的沧桑与悲凉，全诗语言朴素，情感深沉，是唐诗中最感人的思乡名篇。"
  },
  "惠崇春江晚景|苏轼": {
    y: "竹林外两三枝桃花初放，水中嬉戏的鸭子最先察觉到初春江水的回暖。\n河滩上长满了蒌蒿，芦苇也长出短短的新芽，而河豚此时正要逆流而上，从大海回游到江河里来了。",
    s: "《惠崇春江晚景》是苏轼为僧人惠崇的画所作的题画诗，“春江水暖鸭先知”既写出了画中鸭子戏水的情景，又蕴含着实践出真知的哲理。全诗将画面与想象结合，生动再现了江南早春的景象，是题画诗的典范。"
  },
  "六月二十七日望湖楼醉书|苏轼": {
    y: "乌云上涌，就如墨汁泼下，却又在天边露出一段山峦，明丽清新，大雨激起的水花如白珠碎石，飞溅入船。\n忽然间狂风卷地而来，吹散了满天的乌云，而那西湖的湖水碧波如镜，明媚温柔。",
    s: "《六月二十七日望湖楼醉书》描写了西湖夏日暴雨的景象，“黑云翻墨未遮山，白雨跳珠乱入船”以“翻墨”“跳珠”的比喻，将乌云和白雨写得生动形象，“卷地风来忽吹散，望湖楼下水如天”写雨过天晴的开阔，全诗节奏明快，是苏轼写景诗的佳作。"
  },
  "书愤|陆游": {
    y: "年轻时哪里知道世事如此艰难，北望中原，收复故土的豪迈气概坚定如山。\n记得在瓜州渡痛击金兵，雪夜里飞奔着楼船战舰。秋风中跨战马纵横驰骋，收复了大散关捷报频传。\n我当初自比万里长城，立壮志为祖国扫除边患。到如今垂垂老鬓发如霜，盼北伐盼恢复都成空谈。\n出师表真可谓名不虚传，有谁像诸葛亮鞠躬尽瘁，率三军复汉室北定中原！",
    s: "《书愤》是陆游晚年的代表作，追述了早年的抗金经历，抒发了壮志未酬的悲愤。“楼船夜雪瓜洲渡，铁马秋风大散关”以六个名词组合，勾勒出两幅壮阔的战争画面，是宋诗中的名句。全诗感情沉郁，气壮山河，是陆游爱国诗的杰作。"
  },
  "登飞来峰|王安石": {
    y: "登上飞来峰顶高高的塔，听说每天鸡鸣时分在这可以看到旭日升起。\n不怕层层浮云遮挡我远望的视线，只因为如今我站在最高层。",
    s: "《登飞来峰》是王安石青年时期的作品，“不畏浮云遮望眼，自缘身在最高层”由登塔望远悟出哲理：只要站得高、看得远，就不怕被浮云遮住视线，表达了诗人高瞻远瞩、不畏艰难的政治抱负，是宋诗中著名的哲理诗。"
  },
  "四时田园杂兴·其三十一|范成大": {
    y: "白天去田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树荫下学着种瓜。",
    s: "《四时田园杂兴》是范成大田园诗的代表作，描写了农村夏日的劳动场景。“童孙未解供耕织，也傍桑阴学种瓜”以儿童学种瓜的细节，写出了农村劳动的代代相传，充满生活气息，全诗语言朴素，意境清新，是宋代田园诗的佳作。"
  },
  "游园不值|叶绍翁": {
    y: "也许是园主担心我的木屐踩坏他那爱惜的青苔，我轻轻地敲打柴门久久不开。\n满园子的春色是关不住的，开得正旺的红杏有一枝枝条伸到墙外来了。",
    s: "《游园不值》写诗人游园不遇，却从出墙的一枝红杏感受到满园春色。“春色满园关不住，一枝红杏出墙来”既写出了春天的蓬勃生机，又蕴含着新生事物不可阻挡的哲理，成为千古传诵的名句。"
  },
  "己亥杂诗·其五|龚自珍": {
    y: "离别京都的愁思浩如水波向着日落西斜的远处延伸，马鞭向东一挥，感觉就是人在天涯一般。\n从枝头上掉下来的落花不是无情之物，即使化作春泥，也甘愿培育美丽的春花成长。",
    s: "《己亥杂诗》是龚自珍辞官南归时所作，“落红不是无情物，化作春泥更护花”以落花自喻，表达了虽已辞官，却依然心系国家、愿为国家培养人才的奉献精神，成为千古传诵的名句。"
  },
  "咏鹅|骆宾王": {
    y: "鹅呀，鹅呀，鹅呀，弯曲着脖子对天高歌。\n一身雪白的羽毛浮于绿水之上，红色的脚掌拨动着清澈的水波。",
    s: "《咏鹅》是骆宾王七岁时的作品，也是中国流传最广的儿童启蒙诗。全诗以白描手法描绘了鹅的形态和动作，“曲项”“白毛”“红掌”“绿水”色彩鲜明，画面生动，语言浅近，是小学生最熟悉的古诗之一。"
  },
  "古朗月行|李白": {
    y: "小时候不认识月亮，把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。\n月中的仙人是垂着双脚吗？月中的桂树为什么长得圆圆的？\n白兔捣成的仙药，到底是给谁吃的呢？",
    s: "《古朗月行》是李白借古题写的诗，前四句以儿童的视角描写月亮，充满童趣；后四句引用月亮神话，表达了对月亮的好奇与想象。全诗想象丰富，语言明快，是小学课本中的经典篇目。"
  },
  "风|李峤": {
    y: "风能吹落秋天金黄的树叶，能吹开春天美丽的鲜花。\n刮过江面能掀千尺巨浪，吹进竹林能使万竿倾斜。",
    s: "《风》是一首咏物诗，全诗没有一个“风”字，却处处在写风。“解落三秋叶，能开二月花”写风的力量，“过江千尺浪，入竹万竿斜”写风的气势，构思巧妙，是小学课本中的经典篇目。"
  },
  "渔父歌·一|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "和张仆射塞下曲·三|卢纶": {
    y: "死寂之夜，乌云遮月，天边大雁惊飞，单于的军队想要趁着夜色悄悄潜逃。\n正想要带领轻骑兵一路追赶，大雪纷纷扬扬落满了身上的弓刀。",
    s: "《塞下曲》是卢纶的边塞诗名作，“月黑雁飞高，单于夜遁逃”写敌军夜逃，“欲将轻骑逐，大雪满弓刀”写将士追击，全诗没有直接写战斗，却充满紧张的战斗氛围，气势雄浑，是唐代边塞诗的佳作。"
  },
  "浪淘沙九首·一|刘禹锡": {
    y: "弯弯曲曲的黄河，挟带着泥沙，波涛滚滚如巨风掀簸来自天涯。\n如今好像要直飞上高空的银河，请你带上我一起去寻访牛郎织女的家。",
    s: "《浪淘沙》是刘禹锡的组诗，这一首描写黄河的雄伟景象。“九曲黄河万里沙”写出黄河的蜿蜒与泥沙，“如今直上银河去，同到牵牛织女家”由黄河联想到银河，想象奇特，充满浪漫主义色彩。"
  },
  "忆江南词三首·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "池上二绝·二|白居易": {
    y: "小娃撑着小船，偷偷地从池塘里采了白莲回来。\n他不懂得掩藏自己的行踪，浮萍被船儿荡开，水面上留下了一条长长的水线。",
    s: "《池上》是白居易描写儿童生活的小诗，“小娃撑小艇，偷采白莲回”写出了小孩的天真淘气，“不解藏踪迹，浮萍一道开”以浮萍被分开的细节，将小孩的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "小儿垂钓|胡令能": {
    y: "一个头发蓬乱、面孔青嫩的小孩在河边学钓鱼，侧身坐在青苔上绿草映衬着他的身影。\n听到有过路的人问路，小孩漠不关心地摆了摆手，不敢回应路人生怕惊动了鱼儿。",
    s: "《小儿垂钓》是胡令能的名作，描写了一个小孩钓鱼的场景。“蓬头稚子学垂纶”写出小孩的天真，“路人借问遥招手，怕得鱼惊不应人”以小孩的动作和心理，将钓鱼时的专注写得生动传神。全诗充满生活气息，是小学课本中的经典篇目。"
  },
  "寻隐者不遇|贾岛": {
    y: "苍松下询问年少的学童，他说他的师傅已经去山中采药了。\n只知道就在这座大山里，可山中云雾缭绕不知道他的行踪。",
    s: "《寻隐者不遇》是贾岛的名作，以问答形式写寻访隐者不遇的情景。“松下问童子，言师采药去”写问答，“只在此山中，云深不知处”以景结情，将隐者的高洁与寻访的怅惘写得含蓄深沉。全诗语言朴素，意境悠远，是唐诗五绝的精品。"
  },
  "蜂|罗隐": {
    y: "无论是在平地，还是在山峰，极其美好的风景都被蜜蜂占有。\n蜜蜂啊，你采尽百花酿成了花蜜，到底为谁付出辛苦，又想让谁品尝香甜？",
    s: "《蜂》是罗隐的咏物诗，以蜜蜂采花酿蜜的现象，发出“为谁辛苦为谁甜”的追问，既赞美了蜜蜂的勤劳，又暗含对劳动者的同情和对不劳而获者的讽刺。全诗寓意深刻，是小学课本中的经典篇目。"
  },
  "书湖阴先生壁|王安石": {
    y: "茅草房庭院经常打扫，洁净得没有一丝青苔。花草树木成行成垄，都是主人亲手栽种。\n庭院外一条小河护卫环绕着园田，将绿苗紧紧环绕；两座青山打开门来为人们送来绿色。",
    s: "《书湖阴先生壁》是王安石题在邻居杨德逢屋壁上的诗，“一水护田将绿绕，两山排闼送青来”以拟人手法写山水，“护”字和“排闼”将山水写得有情有义，构思巧妙，是王安石写景诗的佳作。"
  },
  "夏日绝句|李清照": {
    y: "活着就要当人中的俊杰，死了也要做鬼中的英雄。\n人们到现在还思念项羽，只因他不肯苟且偷生，退回江东。",
    s: "《夏日绝句》是李清照的名作，“生当作人杰，死亦为鬼雄”以铿锵有力的语言，表达了对英雄气概的赞美和对南宋朝廷偏安一隅的讽刺。全诗借项羽不肯过江东的典故，抒发了爱国情怀，是李清照少有的豪放之作。"
  },
  "三衢道中|曾几": {
    y: "梅子成熟的时候，天天都是晴朗的好天气，乘小船走到小溪的尽头，再走山间小路。\n山路上古树苍翠，与水路上的风景相比也毫不逊色，深林丛中传来几声黄鹂的欢鸣声，更增添了些幽趣。",
    s: "《三衢道中》是曾几的名作，描写了初夏时节在三衢山中行走的所见所闻。“绿阴不减来时路，添得黄鹂四五声”以绿荫和黄鹂声写出了山路的幽静与生机，全诗语言清新，意境优美，是小学课本中的经典篇目。"
  },
  "秋夜将晓出篱门迎凉有感|陆游": {
    y: "三万里长的黄河奔腾向东流入大海，五千仞高的华山耸入云霄触青天。\n中原人民在胡人压迫下眼泪已流尽，他们盼望王师北伐盼了一年又一年。",
    s: "《秋夜将晓出篱门迎凉有感》是陆游的名作，“三万里河东入海，五千仞岳上摩天”以夸张手法写祖国山河的壮丽，“遗民泪尽胡尘里，南望王师又一年”写中原百姓对王师的期盼，全诗气势雄浑，情感深沉，是陆游爱国诗的代表作。"
  },
  "观书有感·其一|朱熹": {
    y: "半亩大的方形池塘像一面镜子一样打开，清澈明净，天光、云影在水面上闪耀浮动。\n要问池塘里的水为何这样清澈呢？是因为有永不枯竭的源头源源不断地为它输送活水。",
    s: "《观书有感》是朱熹的哲理诗，“问渠那得清如许？为有源头活水来”以池塘清澈因为有源头活水，比喻读书学习要不断汲取新知识，才能保持思想的清新与活力。全诗寓理于景，是宋诗中著名的哲理诗。"
  },
  "题临安邸|林升": {
    y: "西湖四周青山绵延楼阁望不见头，湖面游船上的歌舞几时才能停休？\n温暖馥郁的香风把人吹得醉醺醺的，简直是把杭州当成了那汴州。",
    s: "《题临安邸》是林升的讽喻诗，“山外青山楼外楼，西湖歌舞几时休”描写了南宋朝廷偏安江南、醉生梦死的景象，“暖风熏得游人醉，直把杭州作汴州”讽刺了统治者忘记国耻、苟且偷安的行为，是南宋讽喻诗的名作。"
  },
  "乡村四月|翁卷": {
    y: "山坡田野间草木茂盛，稻田里的水色与天光相辉映。天空中烟雨蒙蒙，杜鹃声声啼叫，大地一片欣欣向荣的景象。\n四月到了，没有人闲着，刚刚结束了蚕桑的事又要插秧了。",
    s: "《乡村四月》是翁卷的名作，描写了江南农村四月的繁忙景象。“绿遍山原白满川，子规声里雨如烟”写乡村美景，“乡村四月闲人少，才了蚕桑又插田”写农民的忙碌，全诗色彩明丽，充满生活气息，是小学课本中的经典篇目。"
  },
  "墨梅|王冕": {
    y: "我家洗砚池边有一棵梅树，朵朵开放的梅花都像是用淡淡的墨汁点染而成。\n它不需要别人夸奖颜色多么好看，只是要将清香之气弥漫在天地之间。",
    s: "《墨梅》是王冕的题画诗，以墨梅自喻，“不要人夸好颜色，只留清气满乾坤”表达了诗人不慕虚荣、坚守高洁品格的精神。全诗语言朴素，寓意深刻，是小学课本中的经典篇目。"
  },
  "所见|袁枚": {
    y: "牧童骑在黄牛背上，嘹亮的歌声在树林里回荡。\n忽然想要捕捉树上鸣叫的知了，就马上停止唱歌，一声不响地站立在树旁。",
    s: "《所见》是袁枚的名作，描写了牧童放牛的场景。“牧童骑黄牛，歌声振林樾”写牧童的天真快乐，“意欲捕鸣蝉，忽然闭口立”以牧童的动作变化，将儿童的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "终南别业|王维": {
    y: "中年以后存有较浓的好道之心，直到晚年才安家于终南山边陲。\n兴趣浓时常常独来独往去游玩，有快乐的事自我欣赏自我陶醉。\n间或走到水的尽头去寻求源流，间或坐看上升的云雾千变万化。\n偶然在林间遇见个把乡村父老，偶与他谈笑聊天每每忘了还家。",
    s: "《终南别业》是王维的代表作，“行到水穷处，坐看云起时”是抖音上极火的诗句，表达了随遇而安、豁达从容的人生态度。全诗描写了隐居终南山的悠闲生活，意境悠远，充满禅意，是王维山水诗的精品。"
  },
  "南园十三首·五|李贺": {
    y: "男子汉大丈夫为什么不腰带武器，去收复黄河南北被割据的关塞河山五十州呢？\n请你暂且登上那凌烟阁去看一看，又有哪一个书生曾被封为食邑万户的列侯？",
    s: "《南园十三首·其五》是李贺的名作，“男儿何不带吴钩，收取关山五十州”是抖音上最火的“杀气诗词”之一，充满少年人的意气风发和报国豪情。全诗语言刚劲，气势磅礴，表达了诗人渴望建功立业的雄心壮志。"
  },
  "山园小梅·其一|林逋": {
    y: "百花凋零，独有梅花迎着寒风昂然盛开，那明媚艳丽的景色把小园的风光占尽。\n稀疏的影儿，横斜在清浅的水中，清幽的芬芳浮动在黄昏的月光之下。\n寒雀想飞落下来时，先偷看梅花一眼；蝴蝶如果知道梅花的妍美，定会消魂失魄。\n幸喜我能低声吟诵，和梅花亲近，不用敲着檀板唱歌，执着金杯饮酒来欣赏它了。",
    s: "《山园小梅》是林逋的代表作，“疏影横斜水清浅，暗香浮动月黄昏”是咏梅的千古绝唱，2026年春晚后在抖音上爆火。这两句以极简练的笔墨写出了梅花的姿态和香气，意境清雅，被誉为咏梅诗的巅峰之作。"
  },
  "沁园春·长沙|毛泽东": {
    y: "深秋季节，我独自站立在橘子洲头，望着滔滔的湘水向北奔流。万千山峰全都变成了红色，层层树林好像染过颜色一样；江水清澈澄碧，一艘艘大船乘风破浪，争先恐后。鹰在广阔的天空里飞，鱼在清澈的水里游，万物都在秋光中争着过自由自在的生活。面对广阔的宇宙惆怅感慨：这旷远苍茫大地的盛衰沉浮，该由谁来主宰呢？\n曾经我和我的同学，经常携手结伴来到这里漫游。在一起商讨国家大事，那无数不平凡的岁月至今还萦绕在我的心头。同学们正值青春年少，风华正茂；大家踌躇满志，意气奔放，劲头正足。评论国家大事，写出这些激浊扬清的文章，把当时那些军阀官僚看得如同粪土。可曾记得，那时我们在江水深急的地方游泳，那激起的浪花几乎挡住了疾驰而来的行船？",
    s: "《沁园春·长沙》是毛泽东的代表作，“怅寥廓，问苍茫大地，谁主沉浮”是抖音上极火的词句，气势磅礴，充满青年革命者的豪情壮志。全词上阕写景，下阕抒情，将个人抱负与国家命运融为一体，是中国现代诗词的巅峰之作。"
  },
  "临江仙·滚滚长江东逝水|杨慎": {
    y: "滚滚长江向东流去，不再回头，多少英雄像翻飞的浪花般消逝。争什么是与非、成功与失败，到头来都是一场空。只有青山依然存在，依然的日升日落。\n江上白发渔翁，早已习惯于四时的变化。和朋友难得见了面，痛快地畅饮一杯酒。古往今来的纷纷扰扰，都成为下酒闲谈的材料。",
    s: "《临江仙·滚滚长江东逝水》是杨慎的代表作，因《三国演义》电视剧主题曲而家喻户晓，也是抖音上极火的诗词。“古今多少事，都付笑谈中”表达了对历史兴亡的旷达态度，全词意境雄浑，情感深沉，是中国古典诗词中的千古绝唱。"
  },
  "登科后|孟郊": {
    y: "以往在生活上的困顿与思想上的局促不安再不值得一提了，今朝金榜题名，郁结的闷气已如风吹云散，心上真有说不尽的畅快，真想拥抱一下这大自然。\n策马奔驰于春花烂漫的长安道上，今日的马蹄格外轻盈，不知不觉中早已把长安的繁荣花朵看完了。",
    s: "《登科后》是孟郊进士及第后所作，“春风得意马蹄疾，一日看尽长安花”是抖音上极火的诗句，描写了金榜题名后的狂喜心情。全诗节奏明快，情感奔放，“春风得意”也成为成语，形容事业顺利、心情舒畅。"
  },
  "行行重行行|佚名": {
    y: "走啊走啊走，一直在不停的走，就这样与你活生生的分离。\n从此你我之间相距千万里，我在天这头你就在天那头。\n路途那样艰险又那样遥远，要见面可知道是什么时候？\n北马南来仍然依恋着北风，南鸟北飞筑巢还在南枝头。\n彼此分离的时间越长越久，衣服越发宽大人越发消瘦。\n飘荡的浮云遮住了太阳，游子却还不想回家。\n只因为想你使我都变老了，又是一年很快地到了年关。\n还有许多心里话都不说了，只愿你多保重切莫受饥寒。",
    s: "《行行重行行》是《古诗十九首》的首篇，“思君令人老，岁月忽已晚”是抖音上极火的诗句，道尽了相思之苦和岁月之叹。全诗以朴素的语言描写了思妇对远行丈夫的思念，情感真挚，是五言诗的典范之作。"
  },
  "望月怀远|张九龄": {
    y: "茫茫的海上升起一轮明月，你我相隔天涯却共赏月亮。\n多情的人都怨恨月夜漫长，整夜里不眠而把亲人怀想。\n熄灭蜡烛怜爱这满屋月光，我披衣徘徊深感夜露寒凉。\n不能把美好的月色捧给你，只望能够与你相见在梦乡。",
    s: "《望月怀远》是张九龄的代表作，“海上生明月，天涯共此时”是千古传诵的中秋名句，也是抖音上极火的诗句。全诗以明月起兴，描写了对远方亲人的思念，意境开阔，情感深沉，是唐诗中最著名的望月诗之一。"
  },
  "感遇十二首·一|张九龄": {
    y: "兰草逢春，枝叶繁盛；桂花到秋，皎洁芬芳。\n世间万物都顺应季节，生机勃勃，欣欣向荣。\n谁知那些山林中的隐士，闻到兰桂的芬芳，心生爱慕。\n草木散发香气本是天性，哪里是为了求美人折取呢？",
    s: "《感遇》是张九龄的组诗，这一首以兰桂自喻，“草木有本心，何求美人折”表达了诗人坚守本心、不慕荣利的高洁品格。全诗托物言志，语言清雅，是盛唐五言古诗的代表作。"
  },
  "在岳咏蝉|骆宾王": {
    y: "深秋季节寒蝉叫个不停，蝉声把我这囚徒的愁绪带到远方。\n怎么能忍受这秋蝉扇动乌黑双翅，对我一头斑斑白发，不尽不止地长吟。\n秋露浓重，蝉儿纵使展开双翼也难以高飞，寒风瑟瑟，轻易地把它的鸣唱淹没。\n虽然蝉儿居高食洁，又有谁能相信我的清白，代我表述内心的沉冤？",
    s: "《在狱咏蝉》是骆宾王被诬下狱时所作，以蝉自喻，“无人信高洁，谁为表予心”表达了诗人品行高洁却不被理解的悲愤。全诗托物言志，情感深沉，是初唐咏物诗的代表作。"
  },
  "代悲白头吟|刘希夷": {
    y: "洛阳城东的桃花李花，飘来飘去落在谁家？\n洛阳女子有着美丽的容颜，坐在落花边长声叹息。\n今年花谢了容颜也改了，明年花开时还有谁在呢？\n已经看见松柏被摧折为柴薪，又听说桑田变成了大海。\n古人不再到洛城东了，今人还对着落花的春风。\n年年岁岁花还是相似的，岁岁年年人却不同了。",
    s: "《代悲白头翁》是刘希夷的代表作，“年年岁岁花相似，岁岁年年人不同”是千古传诵的名句，也是抖音上极火的诗句，道尽了时光流逝、物是人非的感慨。全诗以落花起兴，抒发了对青春易逝、人生无常的感叹，是初唐七言歌行的杰作。"
  },
  "渡汉江|宋之问": {
    y: "客居岭外与家里音信断绝，经过了一个冬天又到了春天。\n离故乡越近心中越胆怯，不敢询问从家那边过来的人。",
    s: "《渡汉江》是宋之问从泷州贬所逃归洛阳时所作，“近乡情更怯，不敢问来人”是千古传诵的名句，将游子归乡时的复杂心理写得入木三分。全诗仅二十字，却将思乡之情写得真挚深沉，是唐诗五绝的精品。"
  },
  "杂诗三首·二|王维": {
    y: "您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？",
    s: "《杂诗》是王维的名作，以询问故乡窗前梅花是否开花的细节，表达了对故乡的深切思念。“来日绮窗前，寒梅著花未”以小见大，将思乡之情写得含蓄深沉。全诗语言朴素，情感真挚，是唐诗五绝的精品。"
  },
  "相思|王维": {
    y: "红豆生长在阳光明媚的南方，每逢春天不知长多少新枝。\n希望思念的人儿多多采集，小小红豆引人相思。",
    s: "《相思》是王维的名作，“红豆生南国，春来发几枝”以红豆寄托相思之情，“愿君多采撷，此物最相思”将红豆作为爱情的象征，成为千古传诵的爱情名句。全诗语言朴素，情感真挚，是唐诗中最著名的爱情诗之一。"
  },
  "辋川集·竹里馆|王维": {
    y: "独自闲坐在幽静竹林，一边弹琴一边高歌长啸。\n深深的山林中无人知晓，只有一轮明月静静与我相伴。",
    s: "《竹里馆》是王维《辋川集》中的名篇，描写了隐居竹林的悠闲生活。“独坐幽篁里，弹琴复长啸”写出了诗人的孤高自赏，“深林人不知，明月来相照”以明月为伴，表达了诗人超然物外的心境。全诗意境清幽，充满禅意。"
  },
  "送别|王维": {
    y: "请你下马来喝一杯酒，敢问朋友你要去往哪里？\n你说因为生活不得意，要归隐在终南山边。\n只管去吧我不再多问，那白云没有穷尽的时候。",
    s: "《送别》是王维的名作，“但去莫复问，白云无尽时”以白云无尽比喻归隐生活的自在，表达了对友人归隐的理解和祝福。全诗语言朴素，意境悠远，是唐诗五绝的精品。"
  },
  "青谿|王维": {
    y: "进入黄花川游览，每每都去追逐那条青溪。\n溪水随着山势，百转千回，经过的路途，却不足百里。\n水声在山间乱石中喧嚣，水色在深密的松林里幽静。\n清澈的溪水漾起菱荇，澄明的水面倒映着芦苇。\n我的心一向闲静，清澈的溪水也如此淡泊。\n就让我留在这盘石上，垂钓终老吧。",
    s: "《青溪》是王维山水诗的代表作，“声喧乱石中，色静深松里”以动衬静，写出了青溪的幽静之美。全诗以青溪的淡泊比喻自己的心境，表达了对隐居生活的向往，是王维山水诗的佳作。"
  },
  "渭川田家|王维": {
    y: "夕阳的余晖洒向村庄，牛羊沿着深巷纷纷回归。\n老叟惦念着放牧的孙儿，柱杖等候在自家的柴扉。\n雉鸡鸣叫麦儿即将抽穗，蚕儿成眠桑叶已经薄稀。\n农夫们荷锄回到了村里，相见欢声笑语恋恋依依。\n如此安逸怎不叫我羡慕？我不禁怅然地吟起《式微》。",
    s: "《渭川田家》是王维田园诗的代表作，描写了夕阳西下时农村的宁静景象。“斜光照墟落，穷巷牛羊归”写出了乡村的温馨，“即此羡闲逸，怅然吟式微”表达了对田园生活的向往。全诗意境优美，充满生活气息。"
  },
  "终南山|王维": {
    y: "巍巍的终南山高入云霄，与天帝的住所临近。山峦连绵不断，一直延伸到海边。\n回望山间白云，茫茫一片，走进山中，青霭却又看不见了。\n中峰两侧，分野不同，群山沟壑中，阴晴各异。\n想要找个有人烟的地方投宿，隔着溪水询问樵夫。",
    s: "《终南山》是王维山水诗的代表作，“白云回望合，青霭入看无”以传神的笔墨写出了终南山云雾变幻的奇妙景象。全诗气势雄浑，意境开阔，是王维山水诗的杰作。"
  },
  "汉江临泛|王维": {
    y: "汉江流经楚塞又折入三湘，西起荆门往东与九江相通。\n江水滔滔远去，好像一直涌流到天地之外，两岸山色时隐时现，若有若无。\n远处的城郭好像在水面上飘动，波翻浪涌，辽远的天空也仿佛为之摇荡。\n襄阳的风景天气好，我愿在此地酣饮陪伴山翁。",
    s: "《汉江临泛》是王维山水诗的代表作，“江流天地外，山色有无中”以极简练的笔墨写出了汉江的辽阔和山色的朦胧，是千古传诵的写景名句。全诗意境开阔，气势雄浑，是王维山水诗的杰作。"
  },
  "观猎|王维": {
    y: "狂风声里，角弓鸣响，将军狩猎在渭城。\n秋草枯黄，鹰眼更加锐利；冰雪消融，马蹄格外轻快。\n转眼已过新丰市，不久又回细柳营。\n回头远眺射雕的地方，千里暮云，一片平展。",
    s: "《观猎》是王维描写将军打猎的名作，“草枯鹰眼疾，雪尽马蹄轻”以工整的对仗写出了打猎时的紧张与轻快，“回看射雕处，千里暮云平”以景结情，余味无穷。全诗节奏明快，气势雄浑，是王维边塞诗的佳作。"
  },
  "桃源行|王维": {
    y: "渔舟顺着溪水，贪恋山中春色，两岸桃花夹着古老的渡口。\n坐着看红树，不知走了多远，走完青溪，却不见人。\n从山口悄悄进去，开始曲折幽深，山一开，视野开阔，忽然出现平原。\n远远看见一处云树聚集，走近是千家散居在花竹之间。\n樵夫刚传汉代的姓名，居民还没改秦代的衣服。\n居民一起住在武陵源，还从尘世之外建起田园。\n月照松下，房栊寂静，日出云中，鸡犬喧闹。\n惊讶地听说有俗客来，争着聚集，竞相引回家问都城情况。\n清晨街巷扫花开门，傍晚渔樵乘水归来。\n当初因避乱离开人间，到成仙就不再回去。\n峡谷里谁知有人事，世上遥望空见云山。\n不怀疑灵境难以见到，尘心未尽思念家乡。\n出洞后无论隔山隔水，辞家终打算长久漫游。\n自以为经过旧路不会迷路，哪知峰壑如今已变。\n当时只记得入山很深，青溪几度到云林。\n春天来遍是桃花水，辨不清仙源何处寻。",
    s: "《桃源行》是王维根据陶渊明《桃花源记》改写的七言歌行，“春来遍是桃花水，不辨仙源何处寻”写出了桃花源的神秘与不可寻觅。全诗将散文的叙事转化为诗歌的意境，语言优美，意境悠远，是王维七言古诗的代表作。"
  },
  "老将行|王维": {
    y: "当年十五二十岁青春之时，徒步就能夺得胡人战马骑。\n年轻力壮射杀山中白额虎，数英雄岂止邺下的黄须儿。\n身经百战驰骋疆场三千里，曾以一剑抵当百万雄师。\n汉军声势迅猛如惊雷霹雳，虏骑互相践踏是怕遇蒺藜。\n卫青不败是由于天神辅助，李广无功却缘于命运不济。\n自被摈弃不用便开始衰朽，世事随时光流逝人成白首。\n当年百步穿杨箭无虚发，如今臂病不能拉弓。\n像故侯邵平在路旁卖瓜，像陶渊明门前学种五柳。\n苍茫的古树连接着偏僻的里巷，冷落的寒山对着空窗。\n发誓要像耿恭那样让疏勒城飞出泉水，不愿像灌夫那样只会借酒使气。\n贺兰山下军阵如云，紧急的军书日夜不断传来。\n使臣到三河招募少年，皇帝下诏书五路派出将军。\n试拂铁衣如雪色，且持宝剑闪动星文。\n愿得燕地强弓射杀敌军大将，耻于让越甲惊动我君。\n不要嫌旧日云中太守魏尚年老，还能一战建立功勋。",
    s: "《老将行》是王维的名作，抖音上“杀气诗词”榜单中常引用此诗。全诗描写了一位老将从少年英勇到年老被弃，再到重新上阵的故事，“一身转战三千里，一剑曾当百万师”气势磅礴，“莫嫌旧日云中守，犹堪一战取功勋”表达了老当益壮的豪情。全诗叙事曲折，情感深沉，是王维七言古诗的杰作。"
  },
  "洛阳女儿行|王维": {
    y: "洛阳有一位女子住在我对门，年龄才十五六岁，容貌美丽。\n丈夫骑着玉勒装饰的青白马，侍女用金端着切细的鲤鱼。\n画阁朱楼处处相望，红桃绿柳垂在屋檐下。\n罗帷送上七香车，宝扇迎回九华帐。\n丈夫青春年少又富贵，意气骄奢超过石崇。\n亲自教碧玉般的爱妾跳舞，不惜把珊瑚树拿给人打碎。\n春窗天亮才灭九微灯，九微灯的碎片飞落在花格窗上。\n嬉戏完了没有练习曲子的时候，梳妆好了只是熏香坐着。\n城中相识的都是富贵人家，日夜经过赵李等豪门。\n谁可怜越地女子颜如玉，贫贱时只能在江边自己浣纱。",
    s: "《洛阳女儿行》是王维的名作，描写了洛阳豪门贵妇的奢华生活，结尾以“谁怜越女颜如玉，贫贱江头自浣纱”对比，表达了对贫富不均的感慨。全诗辞藻华丽，对比鲜明，是王维七言古诗的代表作。"
  },
  "秋夜曲|王涯": {
    y: "月亮初升时秋露已经稀薄，丝罗衣已单薄却还没有更换。\n夜深了还在殷勤地拨弄银筝，心里害怕空房冷清而不忍回去。",
    s: "《秋夜曲》是王维的闺怨诗，“桂魄初生秋露微”写秋夜的清冷，“心怯空房不忍归”写女子的孤独与思念。全诗意境凄清，情感细腻，是王维七绝中的佳作。"
  },
  "哭晁卿衡|李白": {
    y: "日本友人晁衡卿辞别长安帝都，乘船扬帆绕过蓬莱群岛。\n明月一样的人儿不归，沉入碧海，白云带着愁色笼罩着苍梧山。",
    s: "《哭晁卿衡》是李白为日本遣唐使阿倍仲麻吕（晁衡）所作的悼诗，“明月不归沉碧海，白云愁色满苍梧”以明月沉海比喻晁衡的遇难，以白云愁色表达悲痛。全诗情感真挚，是中日文化交流史上的重要诗篇。"
  },
  "春思|李白": {
    y: "燕地小草像碧丝般青绿，秦地的桑树已叶翠枝绿。\n当你怀念家园盼归之日，我早就因思念你而愁肠百结。\n春风啊你与我素不相识，为何吹进罗帏撩动我的愁思？",
    s: "《春思》是李白的闺怨诗，“燕草如碧丝，秦桑低绿枝”以两地春景对比，“当君怀归日，是妾断肠时”将思妇的思念写得真挚动人，“春风不相识，何事入罗帏”以反问作结，含蓄深沉。全诗语言优美，情感细腻。"
  },
  "月下独酌四首·一|李白": {
    y: "在花丛中摆上一壶美酒，我自斟自饮，身边没有一个亲友。\n举杯向天，邀请明月，与我的影子相对，便成了三人。\n明月既不能理解开怀畅饮之乐，影子也只能默默地跟随在我的左右。\n暂且以明月和影子作伴吧，要趁春宵及时行乐。\n我吟诵诗篇，月亮伴随我徘徊，我手舞足蹈，影子便随之零乱。\n醒时一起欢乐，醉后各自分散。\n我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。",
    s: "《月下独酌》是李白的代表作，“举杯邀明月，对影成三人”是千古传诵的名句，以奇特的想象将孤独写得浪漫而旷达。全诗描写了诗人在月夜独自饮酒的情景，表达了孤独寂寞却又超然物外的心境，是李白浪漫主义诗风的典型体现。"
  },
  "子夜吴歌·秋歌|李白": {
    y: "长安城内一片月光，千户万户都在捣衣。\n秋风吹送捣衣声声，家家怀念戍边之人。\n何时才能平息边境战争，让我丈夫结束远征。",
    s: "《子夜吴歌·秋歌》是李白的名作，“长安一片月，万户捣衣声”以极简练的笔墨勾勒出长安月夜捣衣的场景，“何日平胡虏，良人罢远征”表达了思妇对和平的渴望。全诗意境优美，情感真挚，是李白乐府诗的代表作。"
  },
  "关山月|李白": {
    y: "一轮明月从祁连山升起，穿行在苍茫云海之间。\n浩荡的长风吹越几万里，吹过将士驻守的玉门关。\n当年汉兵直指白登山道，吐蕃觊觎青海大片河山。\n这里就是历代征战之地，出征将士很少能够生还。\n戍守兵士远望边城景象，思归家乡不禁满面愁容。\n此时将士的妻子在高楼，哀叹何时能见远方亲人。",
    s: "《关山月》是李白的边塞诗名作，“明月出天山，苍茫云海间。长风几万里，吹度玉门关”气势雄浑，写出了边塞的辽阔与苍凉。全诗将征人的思乡与思妇的思念结合，意境苍茫，情感深沉，是李白边塞诗的代表作。"
  },
  "长干行二首·一|李白": {
    y: "我的头发刚刚盖过额头，便同你在门前做折花的游戏。\n你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。\n我们同在长干里居住，两个人从小都没什么猜忌。\n十四岁时嫁给你作妻子，害羞得没有露出过笑脸。\n低着头对着墙壁的暗处，一再呼唤也不敢回头。\n十五岁才舒展眉头，愿意永远和你在一起。\n常抱着至死不渝的信念，怎么能想到会走上望夫台。\n十六岁时你离家远行，要去瞿塘峡滟滪堆。\n五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。\n门前是你离家时徘徊的足迹，渐渐地长满了绿苔。\n绿苔太厚，不好清扫，树叶飘落，秋天早早来到。\n八月里，黄色的蝴蝶飞舞，双双飞到西园草地上。\n看到这种情景我很伤心，因而忧愁容颜衰老。\n无论什么时候你想下三巴回家，请预先把家书捎给我。\n迎接你不怕道路遥远，一直走到长风沙。",
    s: "《长干行》是李白的乐府诗名作，“郎骑竹马来，绕床弄青梅”是“青梅竹马”成语的来源，描写了一对男女从小一起长大、结婚后又离别的故事。全诗以女子的口吻，将爱情的纯真与离别的思念写得真挚动人，是李白乐府诗的代表作。"
  },
  "宣州谢朓楼饯别校书叔云|李白": {
    y: "弃我而去的昨天，早已不可挽留；\n乱我心绪的今天，使人无限烦忧。\n万里长风吹送鸿雁，面对此景可以在高楼上畅饮。\n你的文章有建安风骨，又有谢朓那样的清新秀发。\n我们都满怀豪情逸兴，飞跃的神思像要腾空而上，去摘取那皎洁的明月。\n抽刀切断江水，江水却流得更急，举杯想要消愁，愁绪却更加浓重。\n人生在世不能称心如意，不如明天披散头发，驾舟归隐江湖。",
    s: "《宣州谢朓楼饯别校书叔云》是李白的名作，“抽刀断水水更流，举杯消愁愁更愁”是千古传诵的名句，以奇特的比喻写出了愁绪的难以排遣。全诗情感跌宕，从“弃我去者”的苦闷到“欲上青天揽明月”的豪情，再到“人生在世不称意”的旷达，是李白浪漫主义诗风的典型体现。"
  },
  "行路难三首·二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "荅王十二寒夜独酌有怀|李白": {
    y: "昨夜吴中下雪，你像王子猷那样兴起了佳兴。\n万里浮云卷绕着碧山，青天中流着一轮孤月。\n孤月沧浪，银河清澈，北斗错落，长庚明亮。\n你怀念我，对酒独酌，夜霜洁白，玉栏金井，冰棱峥嵘。\n人生飘忽不过百年，应当酣畅地抒发万古之情。\n你不能像那些斗鸡徒，用狸膏金距斗鸡，让鼻息吹到虹霓。\n你不能学哥舒翰，横行青海夜带刀，西屠石堡取紫袍。\n你在北窗下吟诗作赋，万言不值一杯水。\n世人听了都掉头而去，就像东风吹马耳一样。\n鱼目也笑我，说和明月一样。\n骅骝蜷缩不能吃食，跛驴得志在春风中鸣叫。\n《折杨》《黄华》迎合流俗，晋君听琴枉自清角。\n巴人谁肯和阳春，楚地从来轻视奇璞。\n黄金散尽交不成朋友，白首为儒身被轻视。\n一谈一笑就失颜色，苍蝇般的谗言喧嚣。\n曾参岂是杀人的人，谗言三次传到，慈母也受惊。\n与你论心握住你的手，荣辱对我又算什么。\n孔子还曾感伤凤麟不出，董龙更是何鸡狗。\n一生傲岸苦于不谐于世，恩宠疏远，媒人徒劳，志意多乖违。\n严陵对汉天子长揖不拜，何必长剑拄颐侍奉玉阶。\n显达也不足贵，穷困也不足悲。\n韩信羞与绛灌并列，祢衡耻于追逐屠沽之辈。\n你不见李北海，英风豪气如今何在。\n你不见裴尚书，土坟三尺长满蒿棘。\n少年时早就想去五湖隐居，见此更加疏远钟鼎。",
    s: "《答王十二寒夜独酌有怀》是李白的名作，全诗以寒夜独酌起兴，抒发了怀才不遇的愤懑和对现实的批判。“吟诗作赋北窗里，万言不直一杯水”道尽了文人的辛酸，“达亦不足贵，穷亦不足悲”表达了旷达的人生态度。全诗气势磅礴，情感深沉，是李白七言古诗的杰作。"
  },
  "庐山谣寄卢侍御虚舟|李白": {
    y: "我本是像楚狂接舆那样的人，唱着凤歌嘲笑孔丘。\n手里拿着绿玉杖，早晨告别黄鹤楼。\n为了寻仙，走遍五岳也不嫌远，一生就喜欢游名山。\n庐山秀丽，高耸在南斗星旁，九叠屏风像云锦张开。\n山影落在明湖上，泛着青黛的光，金阙前两座山峰耸立，银河倒挂在三石梁上。\n香炉峰瀑布遥遥相望，山崖曲折，层峦叠嶂，直上苍天。\n翠影红霞映着朝阳，鸟儿飞不过这吴地的长天。\n登高壮观天地，大江茫茫一去不还。\n黄云万里，风云变色，九道白波奔流，像雪山一样。\n喜欢作庐山谣，诗兴因庐山而发。\n闲时照石镜，清净我心，谢灵运走过的地方，已长满苍苔。\n早已服了还丹，没有世俗之情，琴心三叠，道初步修成。\n远远看见仙人在彩云里，手把芙蓉朝玉京而去。\n先约定在九天之上漫游，愿接卢敖同游太清。",
    s: "《庐山谣寄卢侍御虚舟》是李白的名作，“我本楚狂人，凤歌笑孔丘”开篇便展现了诗人狂放不羁的性格，“五岳寻仙不辞远，一生好入名山游”写出了诗人对名山大川的热爱。全诗描写了庐山的壮丽景色，表达了求仙学道的愿望，气势磅礴，想象奇绝，是李白七言古诗的代表作。"
  },
  "金陵酒肆留别|李白": {
    y: "春风吹起柳絮，酒店满屋飘香，侍女捧出美酒，劝我细细品尝。\n金陵年轻朋友，纷纷赶来相送，欲走还留之间，各自畅饮。\n请你问问东流的江水，我们的离情别意，和它相比谁短谁长？",
    s: "《金陵酒肆留别》是李白离金陵时所作，“请君试问东流水，别意与之谁短长”以流水比喻离情，将抽象的情感写得具体可感。全诗语言明快，情感真挚，是李白七绝中的佳作。"
  },
  "听蜀僧濬弹琴|李白": {
    y: "蜀僧濬怀抱着绿绮琴，从西面的峨眉峰上下来。\n为我挥手弹奏一曲，好像听到万壑松涛。\n我的心像被流水洗涤，余响融入霜钟。\n不知不觉碧山已暮色苍茫，秋云暗淡了几重。",
    s: "《听蜀僧濬弹琴》是李白描写音乐的名作，“为我一挥手，如听万壑松”以万壑松涛比喻琴声，写出了琴声的雄浑。全诗将琴声与自然景色融为一体，意境悠远，是李白五言律诗的佳作。"
  },
  "夜泊牛渚怀古|李白": {
    y: "秋夜行舟停泊在西江牛渚山，天空湛蓝湛蓝没有一丝游云。\n我登上小船仰望明朗的秋月，徒然地怀想起东晋谢尚将军。\n我也能够吟哦袁宏的咏史诗，可惜没有那识贤的将军倾听。\n明早我将挂起船帆离开牛渚，这里只有满天枫叶飘落纷纷。",
    s: "《夜泊牛渚怀古》是李白的名作，借袁宏被谢尚赏识的典故，抒发了怀才不遇的感慨。“余亦能高咏，斯人不可闻”将自己的才能与不遇对比，含蓄深沉。全诗意境清远，情感真挚，是李白五言律诗的佳作。"
  },
  "玉阶怨|李白": {
    y: "玉石砌的台阶上生起了露水，深夜独立很久，露水浸湿了罗袜。\n回房放下水晶帘，仍然隔着帘子望着玲珑的秋月。",
    s: "《玉阶怨》是李白的宫怨诗，全诗无一“怨”字，却处处含怨。“玉阶生白露，夜久侵罗袜”写宫女久立等待，“却下水晶帘，玲珑望秋月”写回房后仍望月难眠。全诗意境凄清，含蓄深沉，是唐诗五绝的精品。"
  },
  "怨情|李白": {
    y: "美人卷起珠帘，深深坐着，眉头紧锁。\n只见泪痕湿了面颊，不知她心里在恨谁。",
    s: "《怨情》是李白的闺怨诗，“但见泪痕湿，不知心恨谁”以问语作结，将女子的幽怨写得含蓄深沉。全诗仅二十字，却将美人的哀怨写得生动传神，是唐诗五绝的精品。"
  },
  "赠孟浩然|李白": {
    y: "我敬重孟先生的庄重潇洒，他的高尚品格天下闻名。\n少年时就鄙弃官职，晚年隐居在山林。\n月夜常常醉酒，迷恋花草不侍奉君王。\n高山似的品格怎么能仰望呢，只能在此拜揖他的清美芬芳。",
    s: "《赠孟浩然》是李白写给孟浩然的赠诗，“吾爱孟夫子，风流天下闻”开篇便表达了对孟浩然的敬仰，“红颜弃轩冕，白首卧松云”概括了孟浩然的一生。全诗语言朴素，情感真挚，是李白五言律诗的代表作。"
  },
  "渡荆门送别|李白": {
    y: "我乘舟渡江来到遥远的荆门外，来到战国时期楚国的境内游览。\n山随着低平的原野地出现逐渐消失，江水在一望无际的原野中奔流。\n江面月影好似天上飞来的明镜，云层缔构城外幻出海市蜃楼。\n我依然怜爱这来自故乡之水，不远万里来送我东行的小舟。",
    s: "《渡荆门送别》是李白出蜀时所作，“山随平野尽，江入大荒流”写出了荆门一带的壮阔景象，“仍怜故乡水，万里送行舟”将故乡水拟人化，表达了对故乡的眷恋。全诗意境开阔，情感真挚，是李白五言律诗的代表作。"
  },
  "送友人|李白": {
    y: "青翠的山峦横卧在城墙的北面，波光粼粼的流水围绕着城的东边。\n在此地我们相互道别，你就像孤蓬那样随风飘荡，到万里之外远行去了。\n浮云像游子一样行踪不定，夕阳徐徐下山，似乎有所留恋。\n频频挥手作别从此离去，马儿也为惜别声声嘶鸣。",
    s: "《送友人》是李白的送别诗名作，“浮云游子意，落日故人情”以浮云比喻游子，以落日比喻故人之情，对仗工整，意境优美。全诗情景交融，将送别之情写得含蓄深沉，是李白五言律诗的代表作。"
  },
  "秋浦歌十七首·十四|李白": {
    y: "炉火熊熊燃烧，红星四溅，紫烟蒸腾，广袤的天地被红彤彤的炉火照得通明。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。",
    s: "《秋浦歌·其十四》是李白描写冶炼工人劳动的诗篇，“炉火照天地，红星乱紫烟”写出了冶炼场面的壮观，“赧郎明月夜，歌曲动寒川”写出了工人的乐观精神。全诗色彩浓烈，充满生活气息，是中国古代诗歌中少有的描写工人劳动的作品。"
  },
  "陪侍郎叔游洞庭醉后三首·三|李白": {
    y: "把君山削去才好，让湘水平铺流淌。\n巴陵有无限的美酒，醉倒在洞庭秋色中。",
    s: "《陪侍郎叔游洞庭醉后》是李白的名作，“刬却君山好，平铺湘水流”以奇特的想象，想要铲平君山让湘水平铺，展现了诗人豪放不羁的性格。全诗想象奇绝，气势磅礴，是李白七绝中的佳作。"
  },
  "与夏十二登岳阳楼|李白": {
    y: "登上岳阳楼，远望岳阳城尽收眼底，江水辽远，洞庭湖开阔。\n大雁引走了我的愁心，月亮从山后升起，带来了好月。\n在云间下榻，在天上举杯。\n醉后凉风四起，吹得人衣袖飞舞。",
    s: "《与夏十二登岳阳楼》是李白登岳阳楼时所作，“雁引愁心去，山衔好月来”以拟人手法写雁和山，将愁心被带走、好月被送来的情景写得生动有趣。全诗意境开阔，情调欢快，是李白五言律诗的佳作。"
  },
  "峨眉山月歌|李白": {
    y: "半轮明月高高悬挂在峨眉山前，青衣江澄澈的水面倒映着月影。\n夜间乘船出发，离开清溪直奔三峡。想你却难相见，只能依依不舍顺江去向渝州。",
    s: "《峨眉山月歌》是李白出蜀时所作，全诗连用了峨眉山、平羌江、清溪、三峡、渝州五个地名，却毫无堆砌之感，“峨眉山月半轮秋，影入平羌江水流”写出了月映清江的美景。全诗意境优美，语言流畅，是李白七绝中的佳作。"
  },
  "春夜洛城闻笛|李白": {
    y: "这是从谁家飘出的悠扬笛声呢？它随着春风飘扬，传遍洛阳全城。\n就在客居的今夜，听到《折杨柳》的曲调，谁能不生出怀恋故乡的深情？",
    s: "《春夜洛城闻笛》是李白客居洛阳时所作，“此夜曲中闻折柳，何人不起故园情”以《折杨柳》曲触发思乡之情，将游子的思乡写得真挚动人。全诗意境优美，情感深沉，是李白七绝中的佳作。"
  },
  "清平调·一|李白": {
    y: "见到云就联想到她华艳的衣裳，见到花就联想到她艳丽的容貌；春风吹拂栏杆，露珠润泽花色更浓。\n如此天姿国色，不是群玉山头所见的飘飘仙子，就是瑶台殿前月光照耀下的神女。",
    s: "《清平调·其一》是李白为杨贵妃所作，“云想衣裳花想容，春风拂槛露华浓”以云喻衣，以花喻容，将杨贵妃的美貌写得如梦如幻。全诗想象奇绝，辞藻华丽，是李白七绝中的佳作，也是抖音上极火的诗词。"
  },
  "清平调·二|李白": {
    y: "像一枝红艳的牡丹，带着露水凝聚着芳香，楚王为巫山神女枉自断肠。\n请问汉宫之中谁能与她相比？可怜那赵飞燕还要依靠新妆才能比得上。",
    s: "《清平调·其二》以牡丹喻杨贵妃，“一枝红艳露凝香”写出了杨贵妃的美艳，“借问汉宫谁得似，可怜飞燕倚新妆”以赵飞燕衬托杨贵妃的美貌。全诗辞藻华丽，想象丰富，是李白七绝中的佳作。"
  },
  "清平调·三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "兵车行|杜甫": {
    y: "大路上车轮滚滚，战马嘶叫，出征的青年弓箭挂在腰间。\n爹娘妻子儿女奔跑来相送，行军时扬起的尘土遮天蔽日以致看不见咸阳桥。\n拦在路上牵着士兵衣服顿脚哭，哭声直上天空冲入云霄。\n路旁经过的人问出征士兵怎么样，出征士兵只是说按名册征兵很频繁。\n有的人十五岁到黄河以北去戍守，纵然到了四十岁还要到西部边疆去屯田。\n到里长那里用头巾把头发束起来，他们回时已经白头还要去守边疆。\n边疆无数士兵流血形成了海水，武皇开拓边疆的念头还没停止。\n您没听说汉家华山以东两百州，百千村落长满了草木。\n即使有健壮的妇女手拿锄犁耕种，田土里的庄稼也长得没有东西行列。\n更何况秦地的士兵又能够苦战，被驱使去作战与鸡狗没有分别。\n尽管长辈有疑问，服役的人们怎敢申诉怨恨？\n就像今年冬天，还没有停止征调函谷关以西的士兵。\n县官紧急地催逼百姓交租税，租税从哪里出？\n如果确实知道生男孩是坏事情，反而不如生女孩好。\n生下女孩还能够嫁给近邻，生下男孩死于沙场埋没在荒草间。\n您没有看见，青海的边上，自古以来战死士兵的白骨没人掩埋。\n新鬼烦恼地怨恨旧鬼哭泣，天阴雨湿时众鬼啾啾地喊叫。",
    s: "《兵车行》是杜甫的代表作，“边庭流血成海水，武皇开边意未已”以强烈的对比，揭露了唐玄宗穷兵黩武的罪恶。“生女犹得嫁比邻，生男埋没随百草”一反传统重男轻女的观念，道尽了战争给人民带来的苦难。全诗叙事与抒情结合，情感深沉，是杜甫新乐府诗的杰作。"
  },
  "丽人行|杜甫": {
    y: "三月三日阳春时节天气清新，长安曲江河畔聚集好多美人。\n姿态凝重神情高远文静自然，肌肤丰润胖瘦适中身材匀称。\n绫花绫罗衣裳映衬暮春风光，金丝绣的孔雀银丝刺的麒麟。\n头上戴的是什么珠宝首饰呢？翡翠玉做的花饰垂挂在两鬓。\n在她们的背后能看见什么呢？珠宝镶嵌的裙腰多稳当合身。\n其中有几位都是后妃的亲戚，她们有虢国夫人和秦国夫人的封号。\n翡翠蒸锅端出香喷的紫驼峰，水晶圆盘送来肥美的白鱼鲜。\n她们捏着犀角筷子久久不动，厨师们快刀细切空忙了一场。\n宦官骑马飞驰不敢扬起灰尘，御厨络绎不绝送来海味山珍。\n笙箫鼓乐缠绵宛转感动鬼神，宾客随从满座都是达官贵人。\n有一个骑马官人是何等骄横，车前下马从绣毯上走进帐门。\n白雪似的杨花飘落覆盖浮萍，青鸟飞去衔起地上的红丝帕。\n杨家气焰很高权势无与伦比，切勿近前以免丞相发怒斥人。",
    s: "《丽人行》是杜甫的代表作，通过描写杨贵妃姐妹曲江游宴的奢华场面，讽刺了杨氏家族的骄奢淫逸。“炙手可热势绝伦，慎莫近前丞相嗔”以冷峻的笔调写出了杨国忠的权势。全诗铺陈细腻，讽刺深刻，是杜甫新乐府诗的杰作。"
  },
  "哀江头|杜甫": {
    y: "少陵野老强忍悲痛，吞声哭泣，春日里偷偷走到曲江的角落。\n江头的宫殿千门紧锁，细柳新蒲为谁而绿？\n回忆当年皇帝的旌旗来到南苑，苑中万物都增添了光彩。\n昭阳殿里的第一人杨贵妃，与皇帝同车随侍在皇帝身边。\n车辇前的才人带着弓箭，白马咬着黄金的马勒。\n翻身向天仰射云中的飞鸟，一笑之间正射下双飞的鸟。\n明眸皓齿如今在哪里？血污的游魂归不得。\n清渭东流，剑阁深远，死去的和活着的彼此都没有消息。\n人生有情，泪水沾湿了胸襟，江水江花哪里有尽头！\n黄昏时胡骑的尘土满城，想要往城南去，却望着城北。",
    s: "《哀江头》是杜甫在安史之乱中所作，“明眸皓齿今何在？血污游魂归不得”以杨贵妃的惨死，写出了安史之乱的悲剧。全诗将对往昔繁华的回忆与今日的荒凉对比，情感深沉，是杜甫七言古诗的代表作。"
  },
  "登楼|杜甫": {
    y: "登楼望春近看繁花游子越发伤心，万方多难愁思满腹我来此处登临。\n锦江的春色从天地边际迎面扑来，玉垒山的浮云变幻莫测从古到今。\n大唐的朝廷真像北极星不可动摇，吐蕃夷狄莫再前来骚扰徒劳入侵。\n可叹刘后主那么昏庸还立庙祠祀，日暮时分我要学孔明聊作梁甫吟。",
    s: "《登楼》是杜甫的代表作，“锦江春色来天地，玉垒浮云变古今”以壮阔的景色写出了历史的沧桑，“北极朝廷终不改，西山寇盗莫相侵”表达了对国家命运的关切。全诗意境开阔，情感深沉，是杜甫七律的杰作，叶梦得称此诗“气象雄盖宇宙”。"
  },
  "客至|杜甫": {
    y: "草堂的南北绿水缭绕、春意荡漾，只见一群群鸥鸟日日结队飞来。\n长满花草的庭院小路没有因为迎客而打扫，只是为了你的到来，我家草门首次打开。\n离集市太远盘中没好菜肴，家境贫寒只有陈酒浊酒招待。\n如肯与邻家老翁举杯一起对饮，那我就隔着篱笆将他唤来，一起喝尽这余下的几杯。",
    s: "《客至》是杜甫在成都草堂时所作，“花径不曾缘客扫，蓬门今始为君开”以朴素的语言写出了对客人的热情欢迎。全诗充满生活气息，情感真挚，是杜甫七律中少有的轻快之作。"
  },
  "咏怀古迹五首·三|杜甫": {
    y: "成千上万的山峦山谷连绵不断，如向荆门奔去一般，王昭君生长的山村还至今留存。\n从紫台一去直通向塞外沙漠，最后只留荒郊上的一座孤坟对着黄昏。\n糊涂的君王只依凭画图识别昭君的容颜，月夜里环佩叮当是昭君归魂。\n千载流传她作的胡音琵琶曲，曲中倾诉的分明是满腔悲愤。",
    s: "《咏怀古迹·其三》是杜甫咏怀王昭君的名作，“一去紫台连朔漠，独留青冢向黄昏”以工整的对仗写出了昭君出塞的悲剧，“千载琵琶作胡语，分明怨恨曲中论”将昭君的怨恨写得深沉感人。全诗意境苍凉，情感真挚，是杜甫七律的代表作。"
  },
  "阁夜|杜甫": {
    y: "岁末时节白天的时间就越来越短，夔州霜雪停了的寒冬夜晚，雪光映照下，明朗如昼。\n破晓时军营中鼓角声更显得悲壮凄凉，银河倒映江面，在湍急的三峡中摇曳，繁星随着波浪摇动。\n战乱的消息传来，千家万户的哭声响彻四野，好几个地方的渔民、樵夫唱起了夷歌。\n像诸葛亮和公孙述这样的历史人物，最终也成了黄土中的枯骨，人事与音书，都只能任其寂寞了。",
    s: "《阁夜》是杜甫在夔州时所作，“五更鼓角声悲壮，三峡星河影动摇”以壮阔的景色写出了战乱的悲凉，“卧龙跃马终黄土，人事音书漫寂寥”表达了对历史和人生的感慨。全诗意境苍凉，情感深沉，是杜甫七律的杰作。"
  },
  "又呈吴郎|杜甫": {
    y: "来堂前打枣我从不阻拦任随西邻，因为她是一个无食无儿的老妇人。\n若不是由于穷困怎会做这样的事？正因她心存恐惧反更该与她相亲。\n见你来就防着你虽然是多此一举，但你一来就插上篱笆却甚像是真。\n她说官府征租逼税已经一贫如洗，想起时局兵荒马乱不禁涕泪满巾。",
    s: "《又呈吴郎》是杜甫写给亲戚吴郎的诗，通过劝阻吴郎不要插篱笆阻止西邻老妇打枣，表达了对贫苦人民的深切同情。“不为困穷宁有此？只缘恐惧转须亲”道尽了穷人的辛酸。全诗语言朴素，情感真挚，体现了杜甫忧国忧民的情怀。"
  },
  "月夜|杜甫": {
    y: "今夜里鄜州上空那轮圆月，只有你在闺房中独自遥看。\n远在他方怜惜幼小的儿女，还不懂得你为何思念长安。\n蒙蒙雾气沾湿了你的鬓发，清冷的月光使你的玉臂生寒。\n什么时候才能在一起共同靠在透光的窗帘或帷幔旁，让月光擦干两人的思念的泪。",
    s: "《月夜》是杜甫在安史之乱中被困长安时所作，全词从对方落笔，想象妻子在鄜州独自望月思念自己的情景，“香雾云鬟湿，清辉玉臂寒”以细腻的笔触写出了妻子的深情。全诗构思巧妙，情感真挚，是杜甫五言律诗的佳作。"
  },
  "月夜忆舍弟|杜甫": {
    y: "戍楼上的更鼓声断绝了人行，秋夜的边塞传来了孤雁哀鸣。\n从今夜就进入了白露节气，月亮还是故乡的最明亮。\n虽有兄弟但都离散各去一方，已经无法打听到他们的消息。\n寄往洛阳城的家书老是不能送到，何况战乱频繁还没有停止。",
    s: "《月夜忆舍弟》是杜甫在安史之乱中所作，“露从今夜白，月是故乡明”是千古传诵的名句，将思乡之情写得真挚动人。全诗在战乱的背景下思念离散的兄弟，情感深沉，是杜甫五言律诗的佳作。"
  },
  "天末忆李白|杜甫": {
    y: "凉风飕飕从天边刮起，不知此时你心境怎样。\n鸿雁捎信什么时候才能到，江湖之上秋水浩渺风波多。\n有才华的人总是命途多舛，山精水怪喜欢人们经过。\n你应该与冤魂屈原共语，把诗投进汨罗江赠给他。",
    s: "《天末怀李白》是杜甫为李白被流放夜郎而作，“文章憎命达，魑魅喜人过”道尽了文人的命运多舛，“应共冤魂语，投诗赠汨罗”将李白与屈原相比，表达了对李白的深切同情。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "奉济驿重送严公四韵|杜甫": {
    y: "远送你从此分别，青山空自增添离情。\n什么时候能再把杯共饮，昨夜我们还在月光下同行。\n各郡的百姓都讴歌惋惜，你历事三朝出入荣耀。\n我独自回到江村的住处，寂寞地度过残生。",
    s: "《奉济驿重送严公四韵》是杜甫送别好友严武的诗作，“几时杯重把，昨夜月同行”将对友人的思念写得真挚动人，“江村独归处，寂寞养残生”表达了送别后的孤独。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "别房太尉墓|杜甫": {
    y: "我在他乡又要奔走，停下马告别你的孤坟。\n眼泪落下，近处的土都湿了，低空中有断云飘浮。\n当年像谢安那样陪你下棋，如今像季札那样把剑挂在你的墓前。\n只见林中的花飘落，黄莺的啼叫声像在为我送行。",
    s: "《别房太尉墓》是杜甫拜谒好友房琯墓时所作，“近泪无干土，低空有断云”以景衬情，将悲痛写得深沉感人，“对棋陪谢傅，把剑觅徐君”用典故表达了对友人的深情。全诗意境凄清，情感真挚，是杜甫五言律诗的佳作。"
  },
  "旅夜书怀|杜甫": {
    y: "微风吹拂着江岸的细草，那立着高高桅杆的小船在夜里孤零地停泊着。\n星星垂在天边，平野显得宽阔；月光随波涌动，大江滚滚东流。\n我难道是因为文章而著名吗？年老病多也应该休官了。\n自己到处漂泊像什么呢？就像天地间的一只孤零零的沙鸥。",
    s: "《旅夜书怀》是杜甫晚年漂泊时所作，“星垂平野阔，月涌大江流”以壮阔的景色反衬诗人的孤独，“飘飘何所似，天地一沙鸥”以沙鸥自喻，将漂泊无依的感慨写得深沉感人。全诗意境开阔，情感深沉，是杜甫五言律诗的杰作。"
  },
  "江南逢李龟年|杜甫": {
    y: "当年在岐王宅里，常常见到你的演出；在崔九堂前，也曾多次欣赏你的艺术。\n现在正好是江南风景秀美的时候，在这暮春季节再次遇见了你。",
    s: "《江南逢李龟年》是杜甫晚年在江南遇见著名乐师李龟年时所作，“正是江南好风景，落花时节又逢君”以乐景写哀情，将时代的沧桑和人生的感慨写得含蓄深沉。全诗仅二十八字，却蕴含了丰富的历史内容，是杜甫七绝的代表作。"
  },
  "绝句二首·一|杜甫": {
    y: "沐浴在春光下的江山显得格外秀丽，春风送来花草的芳香。\n泥土随着春天的来临而融化变得松软，燕子衔泥筑巢，暖和的沙子上睡着成双成对的鸳鸯。",
    s: "《绝句·迟日江山丽》是杜甫在成都草堂时所作，“泥融飞燕子，沙暖睡鸳鸯”以生动的细节写出了春日的生机和温馨。全诗色彩明丽，意境优美，是杜甫五言绝句的代表作。"
  },
  "八阵图|杜甫": {
    y: "三国鼎立你建立了盖世功绩，创八阵图你成就了永久声名。\n任凭江流冲击，石头却依然如故，千年遗恨，在于刘备失策想吞吴。",
    s: "《八阵图》是杜甫咏怀诸葛亮的名作，“功盖三分国，名成八阵图”以工整的对仗概括了诸葛亮的功绩，“江流石不转，遗恨失吞吴”表达了对诸葛亮壮志未酬的惋惜。全诗仅二十字，却蕴含了丰富的历史内容，是杜甫五言绝句的佳作。"
  },
  "相见欢·无言独上西楼|李煜": {
    y: "孤独的人默默无语，独自一人缓缓登上西楼。仰视天空，残月如钩。梧桐树寂寞地孤立院中，幽深的庭院被笼罩在清冷凄凉的秋色之中。\n那剪也剪不断，理也理不清，让人心乱如麻的，正是亡国之苦。这样的离异思念之愁，而今在心头上却又是另一般不同的滋味。",
    s: "《相见欢》是李煜亡国后的作品，“剪不断，理还乱，是离愁”以丝麻比喻离愁，将抽象的愁绪写得具体可感，“别是一般滋味在心头”则将亡国之痛写得难以言说。全词语言朴素，情感深沉，是李煜词的代表作。"
  },
  "虞美人·春花秋月何时了|李煜": {
    y: "春花秋月的美好时光什么时候结束的，以前的事情还记得多少！昨夜小楼上又吹来了春风，在这皓月当空的夜晚怎能忍受得了回忆故国的伤痛。\n精雕细刻的栏杆、玉石砌成的台阶应该都还在，只是所怀念的人已衰老。要问我心中有多少哀愁，就像那不尽的春江之水滚滚东流。",
    s: "《虞美人》是李煜的绝命词，也是他最著名的作品。“问君能有几多愁？恰似一江春水向东流”以春水比喻愁绪，将抽象的愁写得汪洋恣肆、无穷无尽，成为千古传诵的名句。全词将故国之思、亡国之痛写得淋漓尽致，是词史上最伟大的作品之一。"
  },
  "浪淘沙令·帘外雨潺潺|李煜": {
    y: "门帘外传来雨声潺潺，浓郁的春意又要凋残。即使身盖罗织的锦被也受不住五更时的冷寒。只有迷梦中忘掉自身是羁旅之客，才能享受片时的欢愉。\n不该独自一人登楼凭栏远望，引起对故国的无尽思念和感慨。离开容易再见故土就难了。流水带走落花，春光已经逝去，好景一去不返。今昔对比，一个是天上一个是人间。",
    s: "《浪淘沙令》是李煜亡国后的作品，“梦里不知身是客，一晌贪欢”以梦中的欢愉反衬现实的凄凉，“流水落花春去也，天上人间”将亡国之痛写得深沉绝望。全词语言自然，情感真挚，是李煜词的代表作。"
  },
  "菩萨蛮·一|温庭筠": {
    y: "眉妆漫染，额上的额黄半明半暗的闪耀，鬓边发丝飘过，洁白的香腮似雪。懒懒地无心去描弯弯的眉，迟了好久才起身梳理晨妆。\n插一朵花，前后都照镜子，看花朵与面容交相辉映。刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。",
    s: "《菩萨蛮》是温庭筠的代表作，也是花间词的典范。全词以细腻的笔触描写了一位女子晨起梳妆的过程，“小山重叠金明灭”写闺房陈设，“懒起画蛾眉，弄妆梳洗迟”写女子的慵懒情态，“双双金鹧鸪”以鹧鸪成双反衬女子的孤独，含蓄深婉，是花间词风的典型体现。"
  },
  "踏莎行|欧阳修": {
    y: "馆舍前的梅花已经凋残，溪桥旁新生细柳轻垂，春风踏芳草远行人跃马扬鞭。走得越远离愁越没有穷尽，就像那迢迢不断的春江之水。\n寸寸柔肠痛断，行行盈淌粉泪，不要登高楼望远把栏杆凭倚。平坦的草地尽头就是重重春山，行人还在那重重春山之外。",
    s: "《踏莎行》是欧阳修婉约词的代表作，“离愁渐远渐无穷，迢迢不断如春水”以春水比喻离愁，将抽象的愁绪写得具体可感，“平芜尽处是春山，行人更在春山外”以景结情，将思念写得悠远绵长。全词意境优美，情感细腻。"
  },
  "生查子|欧阳修": {
    y: "去年元宵节的时候，花市被灯光照的如同白昼。与佳人相约在黄昏之后、月上柳梢头之时同叙衷肠。\n今年正月十五元宵节，月光与灯光仍同去年一样。再也看不到去年的故人，相思之泪沾湿了春衫的衣袖。",
    s: "《生查子·元夕》通过去年与今年元宵的对比，抒发了物是人非的怅惘。“月上柳梢头，人约黄昏后”是千古传诵的名句，写出了恋人约会的温馨美好；“不见去年人，泪湿春衫袖”则写出了旧情难续的悲伤。全词语言朴素，情感真挚。"
  },
  "望海潮|柳永": {
    y: "杭州地处东南方，地理形势优越，风景优美，是三吴的都会，这里自古以来就十分繁华。雾气笼罩着的柳树、装饰华美的桥梁，挡风的帘子、青绿色的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的树木，围绕着钱塘江沙堤，汹涌的江水卷起雪白的浪花，天堑般的钱塘江一望无边。市场上陈列着珍宝，家家户户都存满了绫罗绸缎，争相比奢华。\n里湖、外湖与重重叠叠的山岭非常清秀美丽，有秋天的桂子，十里的荷花。晴天欢快地奏乐，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官，乘醉听吹箫击鼓，观赏、吟唱烟霞风光。他日画上美好景致，回京升官时向人们夸耀。",
    s: "《望海潮》是柳永描写杭州繁华景象的名作，“三秋桂子，十里荷花”以极简练的笔墨概括了杭州的美景，成为千古传诵的名句。全词铺叙了杭州的自然风光、市井繁华和百姓生活，是宋词中描写城市风貌的杰作，相传金主完颜亮读此词后，遂起投鞭渡江之志。"
  },
  "八声甘州|柳永": {
    y: "面对着潇潇暮雨从天空洒落在江面上，经过一番雨洗的秋景，分外寒凉清朗。凄凉的霜风一阵紧似一阵，关山江河一片冷清萧条，落日的余光照耀在高楼上。到处红花凋零翠叶枯落，一切美好的景物渐渐地衰残。只有那滔滔的长江水，不声不响地向东流淌。\n不忍心登高遥看远方，眺望渺茫遥远的故乡，渴求回家的心思难以收拢。叹息这些年来的行踪，为什么苦苦地长期停留在异乡？想着佳人正在华丽的楼上抬头凝望思念着我，多少次错把远处驶来的船当作心上人回家的船。她哪会知道我，倚着栏杆，愁思正如此的深重。",
    s: "《八声甘州》是柳永羁旅词的代表作，“渐霜风凄紧，关河冷落，残照当楼”被苏轼评为“不减唐人高处”。全词以萧瑟的秋景衬托游子的思乡之情，“想佳人妆楼颙望，误几回、天际识归舟”从对方落笔，将思念写得曲折深婉，是柳永慢词的杰作。"
  },
  "念奴娇|苏轼": {
    y: "大江浩浩荡荡向东流去，滔滔巨浪淘尽了千古以来的英雄人物。那旧营垒的西边，人们说就是三国时周瑜大破曹军的赤壁。陡峭的乱石直插云霄，汹涌的惊涛拍打着江岸，卷起千万堆白雪般的浪花。江山壮美如画，一时间涌现出多少英雄豪杰。\n遥想当年的周瑜，小乔刚刚嫁给他，英姿勃发，气度不凡。他手摇羽扇，头戴纶巾，谈笑之间，就把曹军的战船烧得灰飞烟灭。我今日神游古战场，应该笑我太多愁善感，早早地生出了白发。人生就像一场梦，且洒一杯酒，祭奠这江上的明月。",
    s: "《念奴娇·赤壁怀古》是豪放词的巅峰之作，也是苏轼最具代表性的作品。全词借赤壁怀古，写尽历史沧桑与人生旷达，气势雄浑，境界开阔。“大江东去”四字开篇，便奠定了全词磅礴的基调，是宋词中流传最广、影响力最大的作品之一。"
  },
  "水龙吟|苏轼": {
    y: "非常像花又好像不是花，无人怜惜任凭衰零坠地。它飘泊无家，傍路而行，仔细思量起来，看似无情，却自有愁思。萦绕牵挂，愁坏了柔肠，困倦得睁不开娇媚的眼睛，刚要睁开又闭上。梦中随风万里，去寻觅情郎的去处，却又被黄莺的啼叫声唤起。\n不恨杨花飘飞落尽，只恨西园里的落花难以再连缀。清晨一阵雨过后，杨花的踪迹何在？已化作一池碎萍。如果把春色分为三分，二分化为了尘土，一分付诸了流水。细细看来，那飘飞的不是杨花，点点都是离人的眼泪。",
    s: "《水龙吟·次韵章质夫杨花词》是苏轼咏物词的代表作，王国维称“东坡杨花词，和韵而似原唱”。“似花还似非花”抓住了杨花的特点，“细看来，不是杨花，点点是离人泪”以杨花比喻离人泪，将咏物与抒情融为一体，意境优美，情感深沉，是咏物词的千古绝唱。"
  },
  "卜算子|苏轼": {
    y: "弯弯的勾月悬挂在疏落的梧桐树上；夜阑人静，漏壶的水早已滴光了。有谁见到幽居的人独自往来，仿佛天边孤雁般缥缈的身影。\n突然惊起又回过头来，心有遗憾却无人知情。挑遍了寒枝也不肯栖息，甘愿在沙洲忍受寂寞凄冷。",
    s: "《卜算子》是苏轼被贬黄州时所作，以孤鸿自喻，“拣尽寒枝不肯栖，寂寞沙洲冷”表达了诗人虽身处逆境，却依然坚守高洁品格、不肯随波逐流的精神。全词意境幽冷，情感深沉，是苏轼婉约词的代表作。"
  },
  "鹊桥仙|秦观": {
    y: "纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。\n缱绻的柔情像流水般绵绵不断，重逢的约会如梦影般缥缈虚幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。",
    s: "《鹊桥仙》是秦观最著名的词作，借牛郎织女的神话故事，歌颂了坚贞不渝的爱情。“两情若是久长时，又岂在朝朝暮暮”一反传统七夕词的伤感，表达了爱情贵在长久、不在朝夕的独到见解，成为千古传诵的爱情名句。"
  },
  "踏莎行|秦观": {
    y: "暮霭沉沉，楼台消失在浓雾中，月色朦胧，渡口也隐没不见。望断了天涯，理想中的桃花源无处寻觅。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！\n远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你本来是环绕着郴山奔流，为什么偏偏要流到潇湘去呢？",
    s: "《踏莎行·郴州旅舍》是秦观被贬郴州时所作，“郴江幸自绕郴山，为谁流下潇湘去”以郴江绕郴山却又流向潇湘，比喻自己本想安居却被迫漂泊，含蓄深沉。苏轼极爱此两句，曾书于扇上。全词意境凄迷，情感深沉，是秦观词的代表作。"
  },
  "声声慢|李清照": {
    y: "苦苦地寻觅，却只落得冷冷清清，一派凄惨悲戚的景象。天气忽暖忽寒的时候，最难调养身体。喝两三杯淡酒，又怎么抵挡得住傍晚袭来的寒风？一行大雁从天上飞过，正让人伤心，却发现它们都是当年见过的旧相识。\n满地的黄花堆积零落，花儿都已经憔悴不堪，如今还有谁来采摘？守着窗子，独自一人，怎么挨到天黑？梧桐叶上滴着细雨，到了黄昏时分，还是点点滴滴下个不停。这般情景，怎么是一个“愁”字就能说得尽的！",
    s: "《声声慢》是李清照南渡之后的代表作，也是婉约词的千古绝唱。开篇七组叠词，一气呵成，将孤苦无依的心境渲染到极致。全词围绕一个“愁”字，从日常景物入手，层层递进，将国破家亡、身世飘零的沉痛写得入木三分，读来催人泪下。"
  },
  "武陵春|李清照": {
    y: "风停了，尘土里带有花的香气，花儿已凋落殆尽。日头已经升的老高，我却懒得来梳妆。景物依旧，人事已变，一切事情都已经完结。想要倾诉自己的感慨，还未开口，眼泪先流下来。\n听说双溪春景尚好，我也打算泛舟前去。只恐怕双溪蚱蜢般的小船，载不动我内心沉重的忧愁。",
    s: "《武陵春》是李清照南渡后的作品，“只恐双溪舴艋舟，载不动许多愁”以小船载不动愁的奇特比喻，将抽象的愁绪写得具体可感，与李煜“问君能有几多愁，恰似一江春水向东流”异曲同工。全词语言朴素，情感深沉，是李清照晚年词的代表作。"
  },
  "永遇乐|辛弃疾": {
    y: "历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛。\n然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着中原仍然记得，当年扬州路上，到处是金兵南侵的战火烽烟。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，只把他当作一位神祇来供奉，还有谁会记得，这曾是异族皇帝的行宫？还有谁会问，廉颇老了，饭量还好吗？",
    s: "《永遇乐·京口北固亭怀古》是辛弃疾晚年的代表作，也是豪放词的巅峰之作。全词借古讽今，用孙权、刘裕、刘义隆、廉颇等历史典故，抒发了自己渴望收复中原、却不被重用的悲愤。“想当年，金戈铁马，气吞万里如虎”“凭谁问：廉颇老矣，尚能饭否”都是千古传诵的名句，全词用典精当，气势雄浑，是辛弃疾词的压卷之作。"
  },
  "丑奴儿・采桑子|辛弃疾": {
    y: "人年轻的时候不懂忧愁的滋味，喜欢登高远望。喜欢登高远望，为了写出新词，没有愁而硬要说有愁。\n现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说道：好个凉爽的秋天呀！",
    s: "《丑奴儿》以“少年”与“而今”的对比，写出了对“愁”的不同理解。少年时“为赋新词强说愁”，是无病呻吟；而今“识尽愁滋味”，却“欲说还休”，因为真正的愁是无法言说的。全词以浅近的语言表达了深沉的人生感慨，是辛弃疾词的名篇。"
  },
  "卜算子|陆游": {
    y: "驿站之外的断桥边，梅花孤单寂寞地绽开了花，无人过问。暮色降临，梅花无依无靠，已经够愁苦了，却又遭到了风雨的摧残。\n梅花并不想费尽心思去争艳斗宠，对百花的妒忌与排斥毫不在乎。即使凋零了，被碾作泥土，又化作尘土了，梅花依然和往常一样散发出缕缕清香。",
    s: "《卜算子·咏梅》是陆游咏物言志的名作，以梅花自喻，“零落成泥碾作尘，只有香如故”表达了诗人虽屡遭排挤、身处逆境，却依然坚守高洁品格的精神。全词以梅喻人，托物言志，是咏梅词中的杰作。"
  },
  "破阵子|晏殊": {
    y: "燕子飞来正赶上社祭之时，梨花落了之后就是清明。池塘边点缀着几点青苔，树叶底下传来一两声黄鹂的啼叫。白日渐长，柳絮轻盈地飞舞。\n东邻的少女们笑得天真烂漫，在采桑的路上相遇。怪不得昨夜做了个好梦，原来是今天斗草赢了。笑容从双颊上绽开。",
    s: "《破阵子·春景》是晏殊描写春日少女生活的词作，“池上碧苔三四点，叶底黄鹂一两声”以细腻的笔触写出了春日的生机，“笑从双脸生”将少女的天真快乐写得生动传神。全词语言明快，充满生活气息，是晏殊词中少有的轻快之作。"
  },
  "采桑子|欧阳修": {
    y: "西湖风光好，驾轻舟划短桨多么逍遥。碧绿的湖水绵延不断，长堤上花草散出芳香。隐隐传来的音乐歌唱，像是随着船儿在湖上飘荡。\n无风的水面，光滑得好似琉璃一样，不觉得船儿在前进，只见微微的细浪在船边荡漾。看，被船儿惊起的水鸟，正掠过湖岸在飞翔。",
    s: "《采桑子·轻舟短棹西湖好》是欧阳修描写颍州西湖的组词之一，“无风水面琉璃滑，不觉船移”以细腻的笔触写出了西湖的宁静之美，“微动涟漪，惊起沙禽掠岸飞”以动写静，意境优美。全词语言清丽，充满生活气息。"
  },
  "临江仙|晏几道": {
    y: "深夜梦回楼台朱门紧锁，宿酒醒后帘幕重重低垂。去年的春恨涌上心头时，人在落花纷扬中幽幽独立，燕子在微风细雨中双双翱飞。\n记得与小蘋初次相见，她穿着绣有两重心字的罗衣。琵琶轻弹，声声诉说相思之情。当时的明月如今还在，曾经照着她像彩云一样归去。",
    s: "《临江仙·梦后楼台高锁》是晏几道的代表作，“落花人独立，微雨燕双飞”以工整的对仗写出了孤独与相思，“当时明月在，曾照彩云归”以明月和彩云比喻往事，将对恋人的思念写得含蓄深沉。全词意境优美，情感真挚，是婉约词的杰作。"
  },
  "卜算子|王观": {
    y: "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。要是到江南赶上春天，千万要把春天的景色留住。",
    s: "《卜算子·送鲍浩然之浙东》是王观的名作，“水是眼波横，山是眉峰聚”以美人的眼波和眉峰比喻山水，构思巧妙，“若到江南赶上春，千万和春住”将送别与迎春结合，表达了对友人的祝福。全词语言清丽，构思新颖，是宋词中的佳作。"
  },
  "满庭芳|苏轼": {
    y: "微小的虚名，微薄的小利，算来有什么值得忙碌的。凡事都已前定，谁弱谁强又怎样。且趁现在身体还未衰老，让我放浪一些，疏狂一些。百年之中，就算都让我醉，也不过三万六千场。\n细想，人生能有多少时间，忧愁风雨，就占去了一半，又何必拼命去说短论长。有幸面对清风皓月，以苔藓为席，以云幕为帐。江南好啊，千钟美酒，一曲满庭芳。",
    s: "《满庭芳·蜗角虚名》是苏轼的代表作，“蜗角虚名，蝇头微利”以比喻手法写出了名利的微不足道，表达了诗人对名利的淡泊和对自由生活的向往。全词语言旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "玉蝴蝶|柳永": {
    y: "望着雨收云散的天空，我默默凭倚栏杆，目送秋日的时光渐渐远去。晚景萧瑟凄凉，足以引起宋玉那样的悲凉。水面风轻，蘋花渐渐老去，月光露水寒冷，梧桐叶飘黄。这情景让人感伤。故人在哪里，烟水茫茫。\n难忘，我们一起饮酒赋诗的聚会，多少次辜负了风月，多少次变换了星霜。海阔山遥，不知哪里是潇湘。想那双燕，难以凭它们传递远信，指着暮色的天空，空自辨认归航的船。黯然相望。在孤雁的哀鸣声中，我一直站到夕阳西下。",
    s: "《玉蝴蝶·望处雨收云断》是柳永的名作，“故人何在，烟水茫茫”以景结情，将对故人的思念写得含蓄深沉，“断鸿声里，立尽斜阳”以孤雁和夕阳衬托诗人的孤独。全词意境凄清，情感深沉，是柳永慢词的佳作。"
  },
  "翦牡丹|张先": {
    y: "野外的绿色连着天空，青天垂到水面，白色的水光荡漾都很明净。柳树下的小路没有人，柳絮飘落飞无影。汀洲上日落人归，长巾薄袖，采香拾翠竞相游玩。好像懂得凌波微步，停泊在烟渚的春夜。\n彩绦朱索刚刚整理好。宿在绣屏边，画船上风已定。金凤凰响在双槽上，弹出今古的幽思谁能领会。玉盘大小乱珠迸溅。酒上了妆面，花艳和媚相并。再听。弹尽汉妃一曲，江空月静。",
    s: "《剪牡丹·舟中闻双琵琶》是张先的名作，描写了舟中听琵琶的情景。“玉盘大小乱珠迸”以比喻手法写出了琵琶声的美妙，“江空月静”以景结情，余味无穷。全词意境优美，描写细腻，是宋词中的佳作。"
  },
  "点绛唇|王禹": {
    y: "雨绵绵，云愁闷，江南依然称得上美丽。水村渔市，一缕孤烟细细升起。\n天边的大雁，远远看去行列相连。平生的事，此时凝神注视，谁能理解我凭栏的心意。",
    s: "《点绛唇·感兴》是王禹偁的名作，“天际征鸿，遥认行如缀”以大雁比喻自己的志向，“谁会凭栏意”将怀才不遇的感慨写得含蓄深沉。全词意境开阔，情感深沉，是宋初词的佳作。"
  },
  "酒泉子|潘阆": {
    y: "常常回忆观潮的情景，满城的人争着到江上眺望。潮水来时，怀疑沧海全都空了，万面鼓声中。\n弄潮儿站在浪头上，手举红旗，红旗不被水打湿。离别后几次在梦中看到，梦醒还心有余悸。",
    s: "《酒泉子·长忆观潮》是潘阆的名作，描写了钱塘江大潮的壮观景象。“来疑沧海尽成空，万面鼓声中”以夸张手法写出了潮水的磅礴气势，“弄潮儿向涛头立，手把红旗旗不湿”写出了弄潮儿的英勇。全词气势磅礴，是宋词中少有的描写大潮的作品。"
  },
  "满庭芳|秦观": {
    y: "会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，连绵无穷。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情爱的往事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。",
    s: "《满庭芳·山抹微云》是秦观的代表作，秦观也因此被称为“山抹微云君”。“山抹微云，天连衰草”以极简练的笔墨写出了秋日的苍茫，“斜阳外，寒鸦万点，流水绕孤村”化用隋炀帝诗句，意境优美。全词将离别之情写得真挚动人，是婉约词的杰作。"
  },
  "定风波|柳永": {
    y: "自从春天以来，绿叶红花都让人发愁，芳心对什么事都漫不经心。太阳升到花梢，黄莺穿过柳带，还压着香被躺着。肌肤消瘦，头发散乱，整天懒得梳妆。无奈。恨薄情郎一去，连个音信都没有。\n早知道这样，后悔当初没把他的马鞍锁住。在书房里，只给他纸和笔，管束着让他吟诗学习。永远相随，不要抛躲，闲着时拿着针线陪他坐着。和我在一起，免得年少时光白白度过。",
    s: "《定风波·自春来》是柳永的名作，以市井女子的口吻，描写了对丈夫的思念和对平凡夫妻生活的向往。“针线闲拈伴伊坐”写出了女子对温馨生活的渴望，相传晏殊曾以此词讥讽柳永。全词语言通俗，情感真挚，是柳永俚词的代表作。"
  },
  "夜半乐|柳永": {
    y: "寒云暗淡的天气，我乘一叶扁舟，乘兴离开江渚。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，山风忽然吹起，又听到商旅相互呼唤。船帆高高举起，画船轻快地驶过南浦。\n望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰杨掩映，岸边两两三三，是浣纱的游女。躲避行人，含羞笑着相互说话。\n到此因此思念，轻易抛弃了绣阁中的佳人，像浪萍一样难以停留。感叹后约的叮咛究竟有什么凭据。离怀凄惨，空自恨岁晚归期受阻。泪眼凝望，遥远的京城路。孤雁声远，长天暮色。",
    s: "《夜半乐》是柳永的长调名作，全词分三片，描写了舟行所见的江南景色和对佳人的思念。“败荷零落，衰杨掩映，岸边两两三三，浣纱游女”以细腻的笔触写出了江南水乡的生活气息，“断鸿声远长天暮”以景结情，余味无穷。全词意境优美，是柳永慢词的佳作。"
  },
  "踏莎行|晏殊": {
    y: "小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。",
    s: "《踏莎行·小径红稀》是晏殊的名作，“春风不解禁杨花，濛濛乱扑行人面”以拟人手法写春风，生动有趣，“一场愁梦酒醒时，斜阳却照深深院”以景结情，将闲愁写得含蓄深沉。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "南歌子|欧阳修": {
    y: "凤凰发髻上束着金泥带，龙纹玉掌梳插在发间。走到窗下笑着相扶，爱问画眉深浅合不合时宜？\n依偎着人摆弄笔很久，初次试着描花。轻易耽误了绣花功夫，笑着问鸳鸯两个字怎么写？",
    s: "《南歌子·凤髻金泥带》是欧阳修的名作，以细腻的笔触描写了新婚夫妇的甜蜜生活。“爱道画眉深浅入时无”化用朱庆余诗句，“笑问鸳鸯两字怎生书”将少女的娇羞写得生动传神。全词语言明快，充满生活气息，是欧阳修词中少有的轻快之作。"
  },
  "临江仙|苏轼": {
    y: "夜里在东坡饮酒，醉而复醒，醒了又饮。回来的时候仿佛已经三更。家里的童仆早已睡熟鼾声如雷鸣。反复敲门里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n长恨身在宦途，这身子已不是我自己所有。什么时候能忘却为功名利禄而奔竞钻营！夜深了，风停了，江面上的水波也平静下来。真想乘上小船从此消逝，在江河湖海中了却余生。",
    s: "《临江仙·夜归临皋》是苏轼被贬黄州时所作，“小舟从此逝，江海寄余生”表达了诗人对自由生活的向往，相传苏轼写此词后，“挂冠服江边，拏舟长啸去矣”，太守徐君猷闻之大惊，以为苏轼逃走。全词意境旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "西江月|苏轼": {
    y: "我三次经过平山堂下，半生在弹指声中过去了。十年没见老仙翁欧阳修了，墙壁上他的字迹还龙蛇飞动。\n想要悼念文章太守欧阳修，仍然歌唱他的杨柳春风。不要说万事转头就空，没转头的时候也都是梦。",
    s: "《西江月·平山堂》是苏轼经过扬州平山堂时，为悼念恩师欧阳修而作。“壁上龙蛇飞动”写出了欧阳修书法的雄健，“休言万事转头空，未转头时皆梦”表达了对人生的深刻感悟。全词情感真挚，意境旷达，是苏轼婉约词的佳作。"
  },
  "永遇乐|苏轼": {
    y: "明月如霜，好风如水，清景无限。曲折的港湾里鱼儿跳跃，圆圆的荷叶上露珠滚落，寂寞无人看见。三更鼓声响起，一片叶子铿然落下，黯黯的梦云被惊断。夜色茫茫，重寻无处，醒来后把小园走遍。\n天涯的倦客，山中的归路，望断了故园的视线。燕子楼空，佳人在哪里，空锁住楼中的燕子。古今如梦，何曾从梦中醒来，只有旧欢新怨。他日对着黄楼夜景，会为我长叹。",
    s: "《永遇乐·明月如霜》是苏轼夜宿燕子楼时所作，“燕子楼空，佳人何在，空锁楼中燕”是千古传诵的名句，将对历史的感慨写得含蓄深沉。全词意境凄清，情感深沉，是苏轼婉约词的杰作，晁补之称“燕子楼空，佳人何在，空锁楼中燕”为“三句说尽张建封事”。"
  },
  "洞仙歌|苏轼": {
    y: "冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹开，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n起来携着她的纤纤素手，走到无声的庭院，时时看到稀疏的星星渡过银河。试问夜有多深？已经是三更时分，月光淡了，玉绳星低低转动。屈指算西风几时吹来，又不道流年在暗中偷偷变换。",
    s: "《洞仙歌·冰肌玉骨》是苏轼根据蜀主孟昶与花蕊夫人的故事改写的词作，“冰肌玉骨，自清凉无汗”写出了花蕊夫人的清丽，“但屈指西风几时来，又不道流年暗中偷换”将时光流逝的感慨写得含蓄深沉。全词意境优美，情感细腻，是苏轼婉约词的佳作。"
  },
  "越调·天净沙秋思|马致远": {
    y: "枯萎的藤蔓，苍老的古树，黄昏时归巢的乌鸦；小桥下溪水潺潺，旁边有几户人家；古老的道路上，萧瑟的西风里，走着一匹疲惫的瘦马。夕阳向西边落下，漂泊在外的游子，还远在天涯，愁肠寸断。",
    s: "《天净沙·秋思》被称为“秋思之祖”，仅用28个字，便勾勒出一幅苍凉的秋日羁旅图。全曲无一“愁”字，却字字含愁，情景交融，是元曲中最广为人知的作品，也是中国古典诗歌中描写乡愁的巅峰之作。"
  },
  "南吕·四块玉别情|关汉卿": {
    y: "自从送别之后，心中难舍，这一点相思什么时候才能断绝？凭栏远望，衣袖拂过如雪的杨花。溪水又斜，青山又遮，人已经去了！",
    s: "《四块玉·别情》是关汉卿的小令名作，以女子的口吻写送别后的相思。“凭阑袖拂杨花雪”以动作写思念，“溪又斜，山又遮，人去也”以景结情，将离别的惆怅写得含蓄深沉。全曲语言朴素，情感真挚。"
  },
  "离骚（节选）|屈原": {
    y: "我是古帝高阳氏的子孙，我已去世的父亲字伯庸。\n岁星在寅那年的孟春月，正当庚寅日那天我降生。\n父亲仔细揣测我的生辰，于是赐给我相应的美名。\n父亲把我的名取为正则，同时把我的字叫作灵均。\n天赋给我很多良好素质，我不断加强自己的修养。\n我把江离芷草披在肩上，把秋兰结成索佩挂身旁。\n光阴似箭我好像跟不上，岁月不等待人令我心慌。\n早晨我在大坡采集木兰，傍晚在小洲中摘取宿莽。\n时光迅速逝去不能久留，四季更相代谢变化有常。\n我想到草木已由盛到衰，恐怕自己身体逐渐衰老。\n何不利用盛时扬弃秽政，为何还不改变这些法度？\n乘上千里马纵横驰骋吧，来呀我在前面引导开路！",
    s: "《离骚》是屈原的代表作，也是中国古代最长的抒情诗，共373句。这里节选的是开篇部分，诗人自叙身世、生辰和名字，表达了自己的高洁品质和对国家的忧虑。“路漫漫其修远兮，吾将上下而求索”的精神贯穿全诗，奠定了中国浪漫主义文学的传统，对后世影响深远。"
  },
  "鹿柴|王维": {
    y: "幽静的山谷里看不见人，只听到人说话的声音。\n落日的影晕映入了深林，又照在幽暗处的青苔上。",
    s: "《鹿柴》是王维《辋川集》中的名篇，全诗仅二十字，却营造出一种空寂幽深的意境。“空山不见人，但闻人语响”以有声衬无声，“返景入深林，复照青苔上”以光亮写幽暗，充满禅意，体现了王维“诗佛”的艺术特色。"
  },
  "送元二使安西|王维": {
    y: "渭城早晨一场春雨沾湿了轻尘，客舍周围柳树的枝叶翠嫩一新。\n老朋友请你再干一杯美酒，向西出了阳关就难以遇到故旧亲人。",
    s: "《送元二使安西》又名《渭城曲》，是王维最著名的送别诗，后被谱成《阳关三叠》，广为传唱。“劝君更尽一杯酒，西出阳关无故人”两句，将依依惜别之情浓缩在一杯酒中，含蓄深沉，余味无穷，是唐诗中最动人的送别名句。"
  },
  "从军行·其四|王昌龄": {
    y: "青海湖上乌云密布，遮得连绵雪山一片黯淡。边塞古城，玉门雄关，远隔千里，遥遥相望。\n守边将士身经百战，铠甲磨穿，壮志不灭，不打败进犯之敌，誓不返回家乡。",
    s: "《从军行》是王昌龄边塞诗的代表作，“黄沙百战穿金甲，不破楼兰终不还”两句，以铿锵的音调、坚定的语气，写出了戍边将士誓死报国的英雄气概，是唐诗中最具豪情壮志的名句之一。"
  },
  "蜀道难|李白": {
    y: "唉呀呀！多么高峻伟岸！蜀道难以攀越，简直难于上青天。\n传说中蚕丛和鱼凫建立了蜀国，开国的年代实在久远无法详谈。\n从那时至今约有四万八千年了吧，秦蜀被秦岭所阻从不沟通往返。\n西边太白山高峻无路只有飞鸟可通行，飞鸟可以直通峨眉山巅。\n山崩地裂，埋葬了五位开山英雄壮士，这样高险的山路和栈道才相互勾连。\n蜀中上有挡住太阳神六龙车的山巅，下有激浪排空曲折的大川。\n善于高飞的黄鹤尚且无法飞过，即使猢狲要想翻过也愁于攀援。\n青泥岭的泥路曲曲弯弯，百步九折萦绕着山峦。\n屏住呼吸仰头就可触摸参星和井星，紧张得透不过气来，用手抚胸惊恐不已徒长吁短叹。\n好朋友呵请问你西游何时回还？可怕的岩山栈道实在难以登攀！\n只见那悲鸟在古树上哀鸣啼叫，雄雌相随飞翔在树丛之间。\n月夜又听到杜鹃凄凉悲啼，在空山中传响令人愁思绵绵。\n蜀道难以攀越呵简直难于上青天，使人听到这些怎么不脸色突变？\n山峰座座相连离天还不到一尺，枯松老枝倒挂倚贴在绝壁之间。\n漩涡飞转瀑布飞泻争相喧闹着，飞流撞击着巨石在山谷中滚动像万壑鸣雷一般。\n这样危险的地方，唉呀呀你这个远方而来的客人，为什么非要来这里不可呀？\n剑阁所在崇峻巍峨高入云端，只要一人把守千军万马难攻占。\n驻守的官员倘若不是可信赖的人，难免要变为豺狼，据险作乱。\n每日每夜都要躲避猛虎和长蛇，它们磨牙吮血，杀人如麻。\n锦官城虽然说是个快乐的所在，如此险恶还不如早早地把家还。\n蜀道难以攀越呵简直难于上青天，侧身西望令人不免感慨与长叹！",
    s: "《蜀道难》是李白浪漫主义诗歌的代表作，以雄奇奔放的笔调描绘了蜀道的艰险壮丽。全诗以“蜀道之难，难于上青天”为主旋律，三次反复出现，一唱三叹，气势磅礴。诗人运用夸张、想象、神话传说等手法，将蜀道的奇险写得惊心动魄，是唐诗中最具想象力的杰作。"
  },
  "行路难·其一|李白": {
    y: "金杯中的美酒一斗价十千，玉盘里的菜肴珍贵值万钱。\n心中郁闷，我放下杯筷不愿进餐；拔出宝剑环顾四周，心里一片茫然。\n想渡黄河，冰雪却冻封了河川；想登太行山，莽莽风雪早已封山。\n像姜尚垂钓溪，闲待东山再起；又像伊尹做梦，他乘船经过日边。\n人生道路多么艰难，多么艰难；歧路纷杂，如今又身在何处？\n相信乘风破浪的时机总会到来，到时定要扬起征帆，横渡沧海！",
    s: "《行路难》是李白在仕途受挫时所作，全诗情感跌宕起伏，从“停杯投箸不能食”的苦闷茫然，到“长风破浪会有时，直挂云帆济沧海”的豪迈自信，展现了诗人虽身处逆境却依然乐观进取的精神。结尾两句是千古传诵的励志名句。"
  },
  "秋浦歌·其十五|李白": {
    y: "白发长达三千丈，是因为愁才长得这样长。\n不知在明镜之中，是何处的秋霜落在了我的头上？",
    s: "《秋浦歌》以“白发三千丈”的极度夸张开篇，将愁思之深之长写得惊心动魄。“缘愁似个长”点明白发因愁而生，后两句以问语作结，含蓄深沉。全诗仅二十字，却将怀才不遇的悲愤写得淋漓尽致，是李白浪漫主义夸张手法的典范。"
  },
  "江畔独步寻花·其六|杜甫": {
    y: "黄四娘家周围的小路旁开满了鲜花，千朵万朵鲜花把枝条都压得低垂了。\n嬉闹的彩蝶恋恋不舍地盘旋飞舞，自由自在的小黄莺在花间不断欢唱。",
    s: "《江畔独步寻花》是杜甫在成都草堂时的组诗，这一首描写了春日繁花似锦、蝶舞莺啼的美好景象。全诗语言明快，色彩明丽，充满生活气息，展现了杜甫诗歌中轻松愉悦的一面，是描写春景的名篇。"
  },
  "绝句|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，四句四景，对仗工整，色彩明丽。“两个黄鹂鸣翠柳，一行白鹭上青天”以黄、翠、白、青四种颜色交织，画面感极强；“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗是杜甫七绝中的精品。"
  },
  "琵琶行|白居易": {
    y: "秋夜我到浔阳江头送一位归客，冷风吹着枫叶和芦花秋声瑟瑟。\n我下马和客人在船上饯别设宴，举起酒杯要饮却无助兴的管弦。\n酒喝得不痛快更伤心将要分别，临别时夜茫茫江水倒映着明月。\n忽听得江面上传来琵琶清脆声，我忘却了回归客人也不想动身。\n循身轻轻探问弹琵琶的是何人？琵琶停了许久却迟迟没有动静。\n我们移船靠近邀请她出来相见，叫下人添酒回灯重新摆起酒宴。\n千呼万唤她才缓缓地走出来，怀里还抱着琵琶半遮着脸面。\n转紧琴轴拨动琴弦试弹了几声，尚未成曲调那形态就非常有情。\n弦弦凄楚悲切声音隐含着沉思，似乎在诉说着她平生的不得志。\n她低着头随手连续地弹个不停，用琴声把心中无限的往事说尽。\n轻轻抚拢慢慢捻滑抹了又加挑，初弹霓裳羽衣曲接着再弹六幺。\n大弦浑宏悠长嘈嘈如暴风骤雨，小弦和缓幽细切切如有人私语。\n嘈嘈声切切声互为交错地弹奏，就像大珠小珠一串串掉落玉盘。\n琵琶声一会儿像花底下宛转流畅的鸟鸣声，一会儿又像水在冰下流动受阻艰涩低沉。\n水泉冷涩琵琶声开始凝结，凝结而不通畅声音渐渐地中断。\n像另有一种愁思幽恨暗暗滋生，此时闷闷无声却比有声更动人。\n突然间好像银瓶撞破水浆四溅，又好像铁甲骑兵厮杀刀枪齐鸣。\n一曲终了她对准琴弦中心划拨，四弦一声轰鸣好像撕裂了布帛。\n东船西舫人们都静悄悄地聆听，只见江心之中映着白白秋月影。\n她沉吟着收起拨片插在琴弦中，整顿衣裳依然显出庄重的颜容。\n她说我原是京城负有盛名的歌女，老家住在长安城东南的虾蟆陵。\n弹奏琵琶技艺十三岁就已学成，教坊乐团第一队中列有我姓名。\n每曲弹罢都令艺术大师们叹服，每次妆成都被同行歌妓们嫉妒。\n京都豪富子弟争先恐后来献彩，弹完一曲收来的红绡不知其数。\n钿头银篦打节拍常常断裂粉碎，红色罗裙被酒渍染污也不后悔。\n年复一年都在欢笑打闹中度过，秋去春来美好的时光白白消磨。\n兄弟从军姊妹死家道已经破败，暮去朝来我也渐渐地年老色衰。\n门前车马减少光顾者落落稀稀，青春已逝我只得嫁给商人为妻。\n商人重利不重情常常轻易别离，上个月他去浮梁做茶叶的生意。\n他去了留下我在江口孤守空船，秋月与我作伴绕舱的秋水凄寒。\n更深夜阑常梦少年时作乐狂欢，梦中哭醒纵横了泪水和脂粉。\n我听了琵琶声早已摇头叹息，又听到她这番诉说更加歔欷。\n同样都是天涯沦落的可怜人，今日相逢何必问是否曾经相识！\n自从去年我离开繁华长安京城，被贬居住在浔阳江畔常常卧病。\n浔阳这地方荒凉偏僻没有音乐，一年到头也听不到管弦的乐器声。\n住在湓江附近低洼潮湿的地方，黄芦和苦竹绕着宅第丛生。\n在这里早晚能听到的是什么呢？尽是杜鹃猿猴那些悲凄的哀鸣。\n春江花朝秋江月夜那样好光景，也无可奈何常常取酒独酌独饮。\n难道这里就没有山歌和村笛吗？只是那音调嘶哑粗涩实在难听。\n今晚我听你弹奏琵琶诉说衷情，就像听到仙乐眼也亮来耳也明。\n请你不要推辞坐下来再弹一曲，我要为你创作一首新诗琵琶行。\n被我的话所感动她站立了好久，回身坐下再转紧琴弦拨出急声。\n凄凄切切不再像刚才那种声音，在座的人重听都掩面哭泣不停。\n要问在座之中谁流的眼泪最多？我江州司马泪水湿透青衫衣襟！",
    s: "《琵琶行》是白居易贬官江州时所作，通过描写琵琶女的高超技艺和不幸身世，抒发了自己被贬的愤懑之情。“同是天涯沦落人，相逢何必曾相识”是千古传诵的名句，将诗人与琵琶女的命运联系在一起，感人至深。诗中对琵琶音乐的描写更是出神入化，“大珠小珠落玉盘”“此时无声胜有声”等句成为描写音乐的经典。"
  },
  "忆江南·其一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "钱塘湖春行|白居易": {
    y: "从孤山寺的北面到贾亭的西面，湖面春水刚与堤平，白云低垂，同湖面上连成一片。\n几只早出的黄莺争相飞往向阳的树木，谁家新飞来的燕子忙着筑巢衔泥。\n纷繁的花朵渐渐开放使人眼花缭乱，浅浅的青草刚刚够上遮没马蹄。\n最爱的湖东美景百游不厌，杨柳成排绿荫中穿过一条白沙堤。",
    s: "《钱塘湖春行》是白居易任杭州刺史时所作，描写了西湖早春的明媚风光。“几处早莺争暖树，谁家新燕啄春泥”以莺燕的活动写出早春的生机，“乱花渐欲迷人眼，浅草才能没马蹄”写花草的繁茂，全诗充满春天的气息，是描写西湖春景的名篇。"
  },
  "卖炭翁|白居易": {
    y: "有位卖炭的老翁，整年在南山里砍柴烧炭。\n他满脸灰尘，显出被烟熏火燎的颜色，两鬓头发灰白，十个手指也被炭烧得很黑。\n卖炭得到的钱用来干什么？买身上穿的衣裳和嘴里吃的食物。\n可怜他身上只穿着单薄的衣服，心里却担心炭卖不出去，还希望天更寒冷。\n夜里城外下了一尺厚的大雪，清晨，老翁驾着炭车碾轧冰冻的车轮印往集市上赶去。\n牛累了，人饿了，但太阳已经升得很高了，他们就在集市南门外泥泞中歇息。\n那得意忘形的骑着两匹马的人是谁啊？是皇宫内的太监和太监的手下。\n太监手里拿着文书，嘴里却说是皇帝的命令，吆喝着牛朝皇宫拉去。\n一车的炭，一千多斤，太监差役们硬是要赶着走，老翁是百般不舍，但又无可奈何。\n那些人把半匹红纱和一丈绫，朝牛头上一挂，就充当炭的价钱了。",
    s: "《卖炭翁》是白居易《新乐府》中的名篇，通过卖炭翁的遭遇，深刻揭露了宫市制度的罪恶，对劳动人民寄予深切同情。“可怜身上衣正单，心忧炭贱愿天寒”将老人矛盾的心理写得入木三分，是白居易现实主义诗歌的代表作。"
  },
  "无题·相见时难别亦难|李商隐": {
    y: "相见很难，离别更难，何况在这东风无力、百花凋谢的暮春时节。\n春蚕结茧到死时丝才吐完，蜡烛要烧成灰烬时像泪一样的蜡油才能滴干。\n早晨梳妆照镜，只担忧如云的鬓发改变颜色，容颜消失。长夜独自吟诗不寐，必然感到冷月侵人。\n蓬莱山离这儿不算太远，却无路可通，烦请青鸟一样的使者，殷勤地为我去探看。",
    s: "《无题》是李商隐爱情诗的代表作，“春蚕到死丝方尽，蜡炬成灰泪始干”以春蚕吐丝、蜡烛燃烧比喻至死不渝的爱情，成为千古传诵的爱情名句。全诗意境朦胧，情感深沉，是李商隐“无题诗”中最著名的一首。"
  },
  "登乐游原|李商隐": {
    y: "傍晚时分我心情不太好，独自驱车登上了乐游原。\n这夕阳晚景的确十分美好，只不过已是黄昏。",
    s: "《登乐游原》仅二十字，却蕴含着深沉的哲理。“夕阳无限好，只是近黄昏”既写出了夕阳的美丽，又感叹好景不长，既有对美好事物的珍惜，又有对时光流逝的无奈，成为千古传诵的名句。"
  },
  "嫦娥|李商隐": {
    y: "云母屏风上烛影暗淡，银河渐渐斜落，晨星也隐没低沉。\n嫦娥应该后悔偷取了长生不老之药，如今空对碧海青天夜夜孤寂。",
    s: "《嫦娥》借嫦娥奔月的神话故事，抒发了诗人孤寂清高的心境。“嫦娥应悔偷灵药，碧海青天夜夜心”以嫦娥的孤独比喻自己的处境，含蓄深沉，意境悠远，是李商隐七绝中的佳作。"
  },
  "江南春|杜牧": {
    y: "辽阔的江南，到处莺歌燕舞，绿树红花相映，水边村寨山麓城郭处处酒旗飘动。\n南朝遗留下的许多座古寺，如今有多少笼罩在这蒙胧烟雨之中。",
    s: "《江南春》以极简练的笔触描绘了江南春天的美丽景象，“千里莺啼绿映红”从听觉和视觉写江南春景，“南朝四百八十寺，多少楼台烟雨中”在写景中融入历史兴亡的感慨，意境深远，是描写江南春景的千古名篇。"
  },
  "悯农·其二|李绅": {
    y: "盛夏中午，烈日炎炎，农民还在劳作，汗珠滴入泥土。\n有谁想到，我们碗中的米饭，粒粒饱含着农民的血汗？",
    s: "《悯农》是李绅最著名的诗作，“谁知盘中餐，粒粒皆辛苦”以朴素的语言道出了粮食的来之不易，告诫人们珍惜粮食、尊重劳动。全诗语言浅近，寓意深刻，是中国流传最广的诗篇之一。"
  },
  "离思·其四|元稹": {
    y: "经历过波澜壮阔的大海，别处的水再也不值得一观。陶醉过巫山的云雨的梦幻，别处的风景就不称之为云雨了。\n即使身处万花丛中，我也懒得回头顾盼；这缘由，一半是因为修道人的清心寡欲，一半是因为曾经拥有过的你。",
    s: "《离思》是元稹悼念亡妻韦丛所作，“曾经沧海难为水，除却巫山不是云”以沧海之水和巫山之云比喻爱情的深广与美好，表达了对亡妻的忠贞不渝。全诗情感真挚，意境深远，是中国文学史上最著名的悼亡诗之一。"
  },
  "凉州词|王翰": {
    y: "酒筵上甘醇的葡萄美酒盛满在夜光杯之中，正要畅饮时，马上琵琶也声声响起，仿佛催人出征。\n如果醉卧在沙场上，也请你不要笑话，古来出外打仗的能有几人返回家乡？",
    s: "《凉州词》是王翰的代表作，描写了边塞将士在出征前开怀畅饮的场景。“醉卧沙场君莫笑，古来征战几人回”以豪迈旷达的语气写出了战争的残酷和将士们视死如归的气概，全诗格调苍凉而豪放，是唐代边塞诗的名篇。"
  },
  "回乡偶书·其一|贺知章": {
    y: "年少时离乡老年才归家，我的乡音虽未改变，但鬓角的毛发却已经疏落。\n家乡的儿童们看见我，没有一个认识我。他们笑着询问我：你是从哪里来的呀？",
    s: "《回乡偶书》是贺知章八十多岁告老还乡时所作，“少小离家老大回，乡音无改鬓毛衰”写出了久客他乡的感慨，“儿童相见不相识，笑问客从何处来”以儿童的天真提问，反衬出诗人的沧桑与悲凉，全诗语言朴素，情感深沉，是唐诗中最感人的思乡名篇。"
  },
  "饮湖上初晴后雨·其二|苏轼": {
    y: "在灿烂的阳光照耀下，西湖水微波粼粼，波光艳丽，看起来很美；雨天时，在雨幕的笼罩下，西湖周围的群山迷迷茫茫，若有若无，也显得非常奇妙。\n若把西湖比作美人西施，淡妆浓抹都是那么得十分适宜。",
    s: "《饮湖上初晴后雨》是苏轼描写西湖的名篇，“欲把西湖比西子，淡妆浓抹总相宜”以西施比喻西湖，既写出了西湖晴雨皆宜的美丽，又赋予西湖以人的神韵，成为描写西湖的千古名句，西湖也因此被称为“西子湖”。"
  },
  "夏日田园杂兴·其七|范成大": {
    y: "白天去田里锄草，夜晚在家中搓麻线，村中男男女女各有各的家务劳动。\n小孩子虽然不会耕田织布，也在那桑树荫下学着种瓜。",
    s: "《夏日田园杂兴》是范成大田园诗的代表作，描写了农村夏日的劳动场景。“童孙未解供耕织，也傍桑阴学种瓜”以儿童学种瓜的细节，写出了农村劳动的代代相传，充满生活气息，全诗语言朴素，意境清新，是宋代田园诗的佳作。"
  },
  "江南|佚名": {
    y: "江南又到了适宜采莲的季节了，莲叶浮出水面，挨挨挤挤，重重叠叠，迎风招展。在茂密如盖的荷叶下面，欢快的鱼儿在不停的嬉戏玩耍。\n一会儿在这儿，一会儿又忽然游到了那儿，说不清究竟是在东边，还是在西边，还是在南边，还是在北边。",
    s: "《江南》是汉乐府民歌，描写了江南水乡采莲的欢乐场景。全诗以“鱼戏莲叶”的反复咏唱，营造出活泼欢快的氛围，充满江南水乡的生活气息，是小学课本中的经典篇目。"
  },
  "画|王维": {
    y: "远看高山色彩明亮，走近一听水却没有声音。\n春天过去，可是依旧有许多花草争奇斗艳，人走近，可是鸟却依然没有被惊动。",
    s: "《画》是一首谜语诗，每句都在描写画中的景物，远看山有颜色，近听水却无声，春去花还在，人来鸟不惊，处处暗示这是一幅画。全诗构思巧妙，语言浅近，是小学生最喜爱的古诗之一。"
  },
  "古朗月行（节选）|李白": {
    y: "小时候不认识月亮，把它称为白玉盘。\n又怀疑是瑶台仙镜，飞在夜空青云之上。",
    s: "《古朗月行》是李白的作品，这里节选的是前四句，以儿童的视角描写月亮，“呼作白玉盘”“又疑瑶台镜”两个比喻天真可爱，充满童趣，是小学课本中的经典篇目。"
  },
  "渔歌子|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "塞下曲|卢纶": {
    y: "死寂之夜，乌云遮月，天边大雁惊飞，单于的军队想要趁着夜色悄悄潜逃。\n正想要带领轻骑兵一路追赶，大雪纷纷扬扬落满了身上的弓刀。",
    s: "《塞下曲》是卢纶的边塞诗名作，“月黑雁飞高，单于夜遁逃”写敌军夜逃，“欲将轻骑逐，大雪满弓刀”写将士追击，全诗没有直接写战斗，却充满紧张的战斗氛围，气势雄浑，是唐代边塞诗的佳作。"
  },
  "浪淘沙·其一|刘禹锡": {
    y: "弯弯曲曲的黄河，挟带着泥沙，波涛滚滚如巨风掀簸来自天涯。\n如今好像要直飞上高空的银河，请你带上我一起去寻访牛郎织女的家。",
    s: "《浪淘沙》是刘禹锡的组诗，这一首描写黄河的雄伟景象。“九曲黄河万里沙”写出黄河的蜿蜒与泥沙，“如今直上银河去，同到牵牛织女家”由黄河联想到银河，想象奇特，充满浪漫主义色彩。"
  },
  "忆江南|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  },
  "池上|白居易": {
    y: "小娃撑着小船，偷偷地从池塘里采了白莲回来。\n他不懂得掩藏自己的行踪，浮萍被船儿荡开，水面上留下了一条长长的水线。",
    s: "《池上》是白居易描写儿童生活的小诗，“小娃撑小艇，偷采白莲回”写出了小孩的天真淘气，“不解藏踪迹，浮萍一道开”以浮萍被分开的细节，将小孩的天真可爱写得生动传神。全诗充满童趣，是小学课本中的经典篇目。"
  },
  "悯农·其一|李绅": {
    y: "春天只要播下一粒种子，秋天就可收获很多粮食。\n普天之下，没有荒废不种的田地，却仍有劳苦农民被饿死。",
    s: "《悯农·其一》以“春种一粒粟，秋收万颗子”的丰收景象，与“农夫犹饿死”的残酷现实形成强烈对比，揭露了封建社会农民的悲惨命运，表达了对劳动人民的深切同情。全诗语言朴素，对比鲜明，发人深省。"
  },
  "江上渔者|范仲淹": {
    y: "江上来来往往的行人，只喜爱味道鲜美的鲈鱼。\n你看那一叶小小渔船，时隐时现在滔滔风浪里。",
    s: "《江上渔者》是范仲淹的名作，以“江上往来人，但爱鲈鱼美”与“君看一叶舟，出没风波里”对比，写出了捕鱼人的艰辛，表达了对劳动人民的同情。全诗语言朴素，对比鲜明，是小学课本中的经典篇目。"
  },
  "南园十三首·其五|李贺": {
    y: "男子汉大丈夫为什么不腰带武器，去收复黄河南北被割据的关塞河山五十州呢？\n请你暂且登上那凌烟阁去看一看，又有哪一个书生曾被封为食邑万户的列侯？",
    s: "《南园十三首·其五》是李贺的名作，“男儿何不带吴钩，收取关山五十州”是抖音上最火的“杀气诗词”之一，充满少年人的意气风发和报国豪情。全诗语言刚劲，气势磅礴，表达了诗人渴望建功立业的雄心壮志。"
  },
  "唐多令·芦叶满汀洲|刘过": {
    y: "芦苇的枯叶落满沙洲，浅浅的寒水在沙滩上无声无息地流过。二十年光阴似箭，如今我又重新登上这南楼。柳树下的船还未系稳，能有几天呢，又到了中秋时节。\n黄鹤矶头，旧日的友人如今还在吗？旧日的江山全是新添的愁绪。想要买上桂花，带着美酒一同去水上泛舟逍遥，却终究没有了少年时出游的那种意气风发的情怀。",
    s: "《唐多令·芦叶满汀洲》是刘过的代表作，“欲买桂花同载酒，终不似，少年游”是抖音上最火的词句之一，道尽了物是人非、青春不再的感慨。全词今昔对比，情感深沉，是南宋豪放词中的佳作。"
  },
  "赠刘景文|苏轼": {
    y: "荷花凋谢连那擎雨的荷叶也枯萎了，只有那开败了菊花的花枝还傲寒斗霜。\n一年中最好的光景你一定要记住，那就是橙子金黄、橘子青绿的秋末冬初的时节啊。",
    s: "《赠刘景文》是苏轼送给好友刘景文的诗，“一年好景君须记，最是橙黄橘绿时”是抖音上秋天最火的诗句，写出了秋末冬初的美好景色，也暗含了对友人的勉励。全诗意境开阔，格调高昂，是苏轼写景诗的佳作。"
  },
  "浣溪沙·一曲新词酒一杯|晏殊": {
    y: "填一曲新词品尝一杯美酒，时令气候亭台池榭依旧，西下的夕阳几时才能回转？\n无可奈何中百花再残落，似曾相识的春燕又归来，独自在花香小径里徘徊。",
    s: "《浣溪沙》是晏殊最著名的词作，“无可奈何花落去，似曾相识燕归来”以花落燕归的自然景象，抒发了对时光流逝、美好事物消逝的感慨，对仗工整，意境深远，成为千古传诵的名句，也是抖音上极火的词句。"
  },
  "白头吟|卓文君": {
    y: "爱情应该像山上的雪一般纯洁，像云间月亮一样皎洁。\n听说你怀有二心，所以来与你决裂。\n今日置酒作最后一次聚会，明日便在沟头分手。\n我缓缓地移动脚步沿沟走去，过去的生活宛如沟水东流，一去不返。\n当初我毅然离家随君，就不像一般女孩那样哭哭啼啼。\n满以为嫁了一个情意专心的称心郎，可以相爱到老永远幸福。\n男女情投意合就像钓竿那样轻细柔长，鱼儿那样活波可爱。\n男子应当以情意为重，失去了真诚的爱情是任何钱财珍宝都无法补偿的。",
    s: "《白头吟》相传为卓文君所作，“愿得一心人，白头不相离”是抖音上最火的爱情诗句之一，表达了对忠贞爱情的向往。全诗以雪山明月起兴，语言刚健，情感真挚，是中国文学史上最著名的爱情诗之一。"
  },
  "上邪|佚名": {
    y: "上天呀！我渴望与你相知相惜，长存此心永不褪减。\n除非巍巍群山消逝不见，除非滔滔江水干涸枯竭。除非凛凛寒冬雷声翻滚，除非炎炎酷暑白雪纷飞，除非天地相交聚合连接，我才敢将对你的情意抛弃决绝！",
    s: "《上邪》是汉乐府民歌，“山无陵，江水为竭，冬雷震震，夏雨雪，天地合，乃敢与君绝”以五种不可能发生的自然现象来发誓，表达了对爱情的坚贞不渝，是抖音上极火的爱情诗句。全诗感情热烈，想象奇特，是中国文学史上最著名的爱情诗之一。"
  },
  "生年不满百|佚名": {
    y: "人生在世只有短短几十年，却常常怀有无限的忧虑。\n既然白天那么短暂，黑夜那么漫长，为何不拿着蜡烛，日夜游乐呢？\n行乐应当及时，哪能等到将来呢？\n愚蠢的人总是吝啬钱财，为后世所讥笑。\n像王子乔那样成仙的人，实在是难以企及啊。",
    s: "《生年不满百》是《古诗十九首》中的名篇，“生年不满百，常怀千岁忧”是抖音上极火的诗句，表达了人生苦短、及时行乐的思想。全诗语言朴素，哲理深刻，是汉代文人五言诗的代表作。"
  },
  "西洲曲|佚名": {
    y: "思念梅花的时候就到西洲去，折一枝梅花寄给江北的心上人。\n她穿着杏红色的单衫，两鬓的头发像小乌鸦的羽毛一样黑亮。\n西洲在哪里呢？在两桨可到的桥头渡口。\n傍晚伯劳鸟飞过，风吹动乌臼树。\n树下就是她的家门，门里露出她翠绿的发饰。\n打开门心上人没有来，她就出门去采红莲。\n秋天在南塘采莲，莲花高过人头。\n低头拨弄莲子，莲子清如水。\n把莲子放在怀袖中，莲心红得透彻。\n思念心上人他却不来，抬头仰望飞鸿。\n飞鸿飞满西洲，她登上青楼望心上人。\n楼太高望不见，整天靠在栏杆上。\n栏杆弯弯曲曲，她垂下的手洁白如玉。\n卷起帘子天空高远，海水摇荡着空绿的波光。\n海水悠悠如梦，你忧愁我也忧愁。\n南风如果知道我的心意，请把我的梦吹到西洲。",
    s: "《西洲曲》是南朝乐府民歌的代表作，“南风知我意，吹梦到西洲”是抖音上极火的诗句，表达了女子对远方情人的深切思念。全诗以折梅、采莲、望鸿等细节，层层递进地描写相思之情，语言优美，意境悠远，是南朝乐府的巅峰之作。"
  },
  "感遇·其一|张九龄": {
    y: "兰草逢春，枝叶繁盛；桂花到秋，皎洁芬芳。\n世间万物都顺应季节，生机勃勃，欣欣向荣。\n谁知那些山林中的隐士，闻到兰桂的芬芳，心生爱慕。\n草木散发香气本是天性，哪里是为了求美人折取呢？",
    s: "《感遇》是张九龄的组诗，这一首以兰桂自喻，“草木有本心，何求美人折”表达了诗人坚守本心、不慕荣利的高洁品格。全诗托物言志，语言清雅，是盛唐五言古诗的代表作。"
  },
  "在狱咏蝉|骆宾王": {
    y: "深秋季节寒蝉叫个不停，蝉声把我这囚徒的愁绪带到远方。\n怎么能忍受这秋蝉扇动乌黑双翅，对我一头斑斑白发，不尽不止地长吟。\n秋露浓重，蝉儿纵使展开双翼也难以高飞，寒风瑟瑟，轻易地把它的鸣唱淹没。\n虽然蝉儿居高食洁，又有谁能相信我的清白，代我表述内心的沉冤？",
    s: "《在狱咏蝉》是骆宾王被诬下狱时所作，以蝉自喻，“无人信高洁，谁为表予心”表达了诗人品行高洁却不被理解的悲愤。全诗托物言志，情感深沉，是初唐咏物诗的代表作。"
  },
  "代悲白头翁|刘希夷": {
    y: "洛阳城东的桃花李花，飘来飘去落在谁家？\n洛阳女子有着美丽的容颜，坐在落花边长声叹息。\n今年花谢了容颜也改了，明年花开时还有谁在呢？\n已经看见松柏被摧折为柴薪，又听说桑田变成了大海。\n古人不再到洛城东了，今人还对着落花的春风。\n年年岁岁花还是相似的，岁岁年年人却不同了。",
    s: "《代悲白头翁》是刘希夷的代表作，“年年岁岁花相似，岁岁年年人不同”是千古传诵的名句，也是抖音上极火的诗句，道尽了时光流逝、物是人非的感慨。全诗以落花起兴，抒发了对青春易逝、人生无常的感叹，是初唐七言歌行的杰作。"
  },
  "杂诗|王维": {
    y: "您是刚从我们家乡来的，一定了解家乡的人情世态。\n请问您来的时候我家雕画花纹的窗户前，那一株腊梅花开了没有？",
    s: "《杂诗》是王维的名作，以询问故乡窗前梅花是否开花的细节，表达了对故乡的深切思念。“来日绮窗前，寒梅著花未”以小见大，将思乡之情写得含蓄深沉。全诗语言朴素，情感真挚，是唐诗五绝的精品。"
  },
  "竹里馆|王维": {
    y: "独自闲坐在幽静竹林，一边弹琴一边高歌长啸。\n深深的山林中无人知晓，只有一轮明月静静与我相伴。",
    s: "《竹里馆》是王维《辋川集》中的名篇，描写了隐居竹林的悠闲生活。“独坐幽篁里，弹琴复长啸”写出了诗人的孤高自赏，“深林人不知，明月来相照”以明月为伴，表达了诗人超然物外的心境。全诗意境清幽，充满禅意。"
  },
  "青溪|王维": {
    y: "进入黄花川游览，每每都去追逐那条青溪。\n溪水随着山势，百转千回，经过的路途，却不足百里。\n水声在山间乱石中喧嚣，水色在深密的松林里幽静。\n清澈的溪水漾起菱荇，澄明的水面倒映着芦苇。\n我的心一向闲静，清澈的溪水也如此淡泊。\n就让我留在这盘石上，垂钓终老吧。",
    s: "《青溪》是王维山水诗的代表作，“声喧乱石中，色静深松里”以动衬静，写出了青溪的幽静之美。全诗以青溪的淡泊比喻自己的心境，表达了对隐居生活的向往，是王维山水诗的佳作。"
  },
  "秋夜曲|王维": {
    y: "月亮初升时秋露已经稀薄，丝罗衣已单薄却还没有更换。\n夜深了还在殷勤地拨弄银筝，心里害怕空房冷清而不忍回去。",
    s: "《秋夜曲》是王维的闺怨诗，“桂魄初生秋露微”写秋夜的清冷，“心怯空房不忍归”写女子的孤独与思念。全诗意境凄清，情感细腻，是王维七绝中的佳作。"
  },
  "月下独酌·其一|李白": {
    y: "在花丛中摆上一壶美酒，我自斟自饮，身边没有一个亲友。\n举杯向天，邀请明月，与我的影子相对，便成了三人。\n明月既不能理解开怀畅饮之乐，影子也只能默默地跟随在我的左右。\n暂且以明月和影子作伴吧，要趁春宵及时行乐。\n我吟诵诗篇，月亮伴随我徘徊，我手舞足蹈，影子便随之零乱。\n醒时一起欢乐，醉后各自分散。\n我愿与他们永远结下忘掉伤情的友谊，相约在缥缈的银河边。",
    s: "《月下独酌》是李白的代表作，“举杯邀明月，对影成三人”是千古传诵的名句，以奇特的想象将孤独写得浪漫而旷达。全诗描写了诗人在月夜独自饮酒的情景，表达了孤独寂寞却又超然物外的心境，是李白浪漫主义诗风的典型体现。"
  },
  "长干行·其一|李白": {
    y: "我的头发刚刚盖过额头，便同你在门前做折花的游戏。\n你骑着竹马过来，我们一起绕着井栏，互掷青梅为戏。\n我们同在长干里居住，两个人从小都没什么猜忌。\n十四岁时嫁给你作妻子，害羞得没有露出过笑脸。\n低着头对着墙壁的暗处，一再呼唤也不敢回头。\n十五岁才舒展眉头，愿意永远和你在一起。\n常抱着至死不渝的信念，怎么能想到会走上望夫台。\n十六岁时你离家远行，要去瞿塘峡滟滪堆。\n五月水涨时，滟滪堆不可相触，两岸猿猴的啼叫声传到天上。\n门前是你离家时徘徊的足迹，渐渐地长满了绿苔。\n绿苔太厚，不好清扫，树叶飘落，秋天早早来到。\n八月里，黄色的蝴蝶飞舞，双双飞到西园草地上。\n看到这种情景我很伤心，因而忧愁容颜衰老。\n无论什么时候你想下三巴回家，请预先把家书捎给我。\n迎接你不怕道路遥远，一直走到长风沙。",
    s: "《长干行》是李白的乐府诗名作，“郎骑竹马来，绕床弄青梅”是“青梅竹马”成语的来源，描写了一对男女从小一起长大、结婚后又离别的故事。全诗以女子的口吻，将爱情的纯真与离别的思念写得真挚动人，是李白乐府诗的代表作。"
  },
  "行路难·其二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "答王十二寒夜独酌有怀|李白": {
    y: "昨夜吴中下雪，你像王子猷那样兴起了佳兴。\n万里浮云卷绕着碧山，青天中流着一轮孤月。\n孤月沧浪，银河清澈，北斗错落，长庚明亮。\n你怀念我，对酒独酌，夜霜洁白，玉栏金井，冰棱峥嵘。\n人生飘忽不过百年，应当酣畅地抒发万古之情。\n你不能像那些斗鸡徒，用狸膏金距斗鸡，让鼻息吹到虹霓。\n你不能学哥舒翰，横行青海夜带刀，西屠石堡取紫袍。\n你在北窗下吟诗作赋，万言不值一杯水。\n世人听了都掉头而去，就像东风吹马耳一样。\n鱼目也笑我，说和明月一样。\n骅骝蜷缩不能吃食，跛驴得志在春风中鸣叫。\n《折杨》《黄华》迎合流俗，晋君听琴枉自清角。\n巴人谁肯和阳春，楚地从来轻视奇璞。\n黄金散尽交不成朋友，白首为儒身被轻视。\n一谈一笑就失颜色，苍蝇般的谗言喧嚣。\n曾参岂是杀人的人，谗言三次传到，慈母也受惊。\n与你论心握住你的手，荣辱对我又算什么。\n孔子还曾感伤凤麟不出，董龙更是何鸡狗。\n一生傲岸苦于不谐于世，恩宠疏远，媒人徒劳，志意多乖违。\n严陵对汉天子长揖不拜，何必长剑拄颐侍奉玉阶。\n显达也不足贵，穷困也不足悲。\n韩信羞与绛灌并列，祢衡耻于追逐屠沽之辈。\n你不见李北海，英风豪气如今何在。\n你不见裴尚书，土坟三尺长满蒿棘。\n少年时早就想去五湖隐居，见此更加疏远钟鼎。",
    s: "《答王十二寒夜独酌有怀》是李白的名作，全诗以寒夜独酌起兴，抒发了怀才不遇的愤懑和对现实的批判。“吟诗作赋北窗里，万言不直一杯水”道尽了文人的辛酸，“达亦不足贵，穷亦不足悲”表达了旷达的人生态度。全诗气势磅礴，情感深沉，是李白七言古诗的杰作。"
  },
  "夜思|李白": {
    y: "明亮的月光洒在窗户纸上，好像地上泛起了一层白霜。\n我抬起头来，看那天窗外空中的明月，不由得低头沉思，想起远方的家乡。",
    s: "《静夜思》是李白最著名的诗篇，也是中国流传最广的唐诗之一。全诗仅二十字，语言朴素自然，却将游子思乡之情写得真挚动人。“举头望明月，低头思故乡”两个动作，将思乡之情表现得含蓄而深沉，千百年来引起无数游子的共鸣。"
  },
  "秋浦歌·其十四|李白": {
    y: "炉火熊熊燃烧，红星四溅，紫烟蒸腾，广袤的天地被红彤彤的炉火照得通明。\n炼铜工人在明月之夜，一边唱歌一边劳动，他们的歌声响彻了寒峭的山谷。",
    s: "《秋浦歌·其十四》是李白描写冶炼工人劳动的诗篇，“炉火照天地，红星乱紫烟”写出了冶炼场面的壮观，“赧郎明月夜，歌曲动寒川”写出了工人的乐观精神。全诗色彩浓烈，充满生活气息，是中国古代诗歌中少有的描写工人劳动的作品。"
  },
  "陪侍郎叔游洞庭醉后|李白": {
    y: "把君山削去才好，让湘水平铺流淌。\n巴陵有无限的美酒，醉倒在洞庭秋色中。",
    s: "《陪侍郎叔游洞庭醉后》是李白的名作，“刬却君山好，平铺湘水流”以奇特的想象，想要铲平君山让湘水平铺，展现了诗人豪放不羁的性格。全诗想象奇绝，气势磅礴，是李白七绝中的佳作。"
  },
  "清平调·其一|李白": {
    y: "见到云就联想到她华艳的衣裳，见到花就联想到她艳丽的容貌；春风吹拂栏杆，露珠润泽花色更浓。\n如此天姿国色，不是群玉山头所见的飘飘仙子，就是瑶台殿前月光照耀下的神女。",
    s: "《清平调·其一》是李白为杨贵妃所作，“云想衣裳花想容，春风拂槛露华浓”以云喻衣，以花喻容，将杨贵妃的美貌写得如梦如幻。全诗想象奇绝，辞藻华丽，是李白七绝中的佳作，也是抖音上极火的诗词。"
  },
  "清平调·其二|李白": {
    y: "像一枝红艳的牡丹，带着露水凝聚着芳香，楚王为巫山神女枉自断肠。\n请问汉宫之中谁能与她相比？可怜那赵飞燕还要依靠新妆才能比得上。",
    s: "《清平调·其二》以牡丹喻杨贵妃，“一枝红艳露凝香”写出了杨贵妃的美艳，“借问汉宫谁得似，可怜飞燕倚新妆”以赵飞燕衬托杨贵妃的美貌。全诗辞藻华丽，想象丰富，是李白七绝中的佳作。"
  },
  "清平调·其三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "咏怀古迹·其三|杜甫": {
    y: "成千上万的山峦山谷连绵不断，如向荆门奔去一般，王昭君生长的山村还至今留存。\n从紫台一去直通向塞外沙漠，最后只留荒郊上的一座孤坟对着黄昏。\n糊涂的君王只依凭画图识别昭君的容颜，月夜里环佩叮当是昭君归魂。\n千载流传她作的胡音琵琶曲，曲中倾诉的分明是满腔悲愤。",
    s: "《咏怀古迹·其三》是杜甫咏怀王昭君的名作，“一去紫台连朔漠，独留青冢向黄昏”以工整的对仗写出了昭君出塞的悲剧，“千载琵琶作胡语，分明怨恨曲中论”将昭君的怨恨写得深沉感人。全诗意境苍凉，情感真挚，是杜甫七律的代表作。"
  },
  "天末怀李白|杜甫": {
    y: "凉风飕飕从天边刮起，不知此时你心境怎样。\n鸿雁捎信什么时候才能到，江湖之上秋水浩渺风波多。\n有才华的人总是命途多舛，山精水怪喜欢人们经过。\n你应该与冤魂屈原共语，把诗投进汨罗江赠给他。",
    s: "《天末怀李白》是杜甫为李白被流放夜郎而作，“文章憎命达，魑魅喜人过”道尽了文人的命运多舛，“应共冤魂语，投诗赠汨罗”将李白与屈原相比，表达了对李白的深切同情。全诗情感真挚，是杜甫五言律诗的佳作。"
  },
  "绝句·两个黄鹂鸣翠柳|杜甫": {
    y: "两只黄鹂在翠绿的柳树间鸣叫，一行白鹭直冲向蔚蓝的天空。\n坐在窗前可以看见西岭千年不化的积雪，门前停泊着自万里外的东吴远行而来的船只。",
    s: "《绝句》是杜甫在成都草堂时所作，全诗四句四景，“两个黄鹂鸣翠柳，一行白鹭上青天”色彩明丽，“窗含西岭千秋雪，门泊东吴万里船”时空交错，意境开阔。全诗对仗工整，是杜甫七绝的代表作。"
  },
  "绝句·迟日江山丽|杜甫": {
    y: "沐浴在春光下的江山显得格外秀丽，春风送来花草的芳香。\n泥土随着春天的来临而融化变得松软，燕子衔泥筑巢，暖和的沙子上睡着成双成对的鸳鸯。",
    s: "《绝句·迟日江山丽》是杜甫在成都草堂时所作，“泥融飞燕子，沙暖睡鸳鸯”以生动的细节写出了春日的生机和温馨。全诗色彩明丽，意境优美，是杜甫五言绝句的代表作。"
  },
  "菩萨蛮·小山重叠金明灭|温庭筠": {
    y: "眉妆漫染，额上的额黄半明半暗的闪耀，鬓边发丝飘过，洁白的香腮似雪。懒懒地无心去描弯弯的眉，迟了好久才起身梳理晨妆。\n插一朵花，前后都照镜子，看花朵与面容交相辉映。刚穿上的绫罗裙襦，绣着一双双的金鹧鸪。",
    s: "《菩萨蛮》是温庭筠的代表作，也是花间词的典范。全词以细腻的笔触描写了一位女子晨起梳妆的过程，“小山重叠金明灭”写闺房陈设，“懒起画蛾眉，弄妆梳洗迟”写女子的慵懒情态，“双双金鹧鸪”以鹧鸪成双反衬女子的孤独，含蓄深婉，是花间词风的典型体现。"
  },
  "蝶恋花·槛菊愁烟兰泣露|晏殊": {
    y: "栏外的菊花笼罩着一层愁惨的烟雾，兰花沾露好似在哭泣，罗幕之间荡漾着一缕轻寒，燕子双双穿过帘幕飞走了。明月不明白离别之苦，斜斜的银辉直到破晓还穿入朱户。\n昨天夜里秋风劲吹，凋零了绿树。我独自登上高楼，望尽那消失在天涯的道路。想给我的心上人寄一封信。但是高山连绵，碧水无尽，又不知道我思念的人究竟在何处。",
    s: "《蝶恋花》是晏殊的名作，“昨夜西风凋碧树，独上高楼，望尽天涯路”被王国维称为“古今之成大事业、大学问者”的第一境界。全词以秋景写离愁，意境高远，情感深沉，是婉约词的佳作。"
  },
  "踏莎行·候馆梅残|欧阳修": {
    y: "馆舍前的梅花已经凋残，溪桥旁新生细柳轻垂，春风踏芳草远行人跃马扬鞭。走得越远离愁越没有穷尽，就像那迢迢不断的春江之水。\n寸寸柔肠痛断，行行盈淌粉泪，不要登高楼望远把栏杆凭倚。平坦的草地尽头就是重重春山，行人还在那重重春山之外。",
    s: "《踏莎行》是欧阳修婉约词的代表作，“离愁渐远渐无穷，迢迢不断如春水”以春水比喻离愁，将抽象的愁绪写得具体可感，“平芜尽处是春山，行人更在春山外”以景结情，将思念写得悠远绵长。全词意境优美，情感细腻。"
  },
  "生查子·元夕|欧阳修": {
    y: "去年元宵节的时候，花市被灯光照的如同白昼。与佳人相约在黄昏之后、月上柳梢头之时同叙衷肠。\n今年正月十五元宵节，月光与灯光仍同去年一样。再也看不到去年的故人，相思之泪沾湿了春衫的衣袖。",
    s: "《生查子·元夕》通过去年与今年元宵的对比，抒发了物是人非的怅惘。“月上柳梢头，人约黄昏后”是千古传诵的名句，写出了恋人约会的温馨美好；“不见去年人，泪湿春衫袖”则写出了旧情难续的悲伤。全词语言朴素，情感真挚。"
  },
  "雨霖铃·寒蝉凄切|柳永": {
    y: "秋蝉的叫声凄凉而急促，傍晚时分，面对着长亭，骤雨刚停。在京都郊外设帐饯行，却没有畅饮的心绪，正在依依不舍的时候，船上的人已催着出发。握着对方的手含着泪对视，哽咽的说不出话来。想到这一去路途遥远，千里烟波渺茫，傍晚的云雾笼罩着南天，深厚广阔，不知尽头。\n自古以来，多情的人总是为离别而伤感，更何况是在这冷清、凄凉的秋天！谁知我今夜酒醒时身在何处？怕是只有杨柳岸边，面对凄厉的晨风和黎明的残月了。这一去长年相别，我料想即使遇到好天气、好风景，也如同虚设。即使有满腹的情意，又再同谁去诉说呢？",
    s: "《雨霖铃》是柳永最著名的词作，也是婉约词的巅峰之作。“执手相看泪眼，竟无语凝噎”将离别时的难舍难分写得入木三分，“今宵酒醒何处？杨柳岸，晓风残月”以景写情，将离别后的凄凉孤寂写得淋漓尽致，成为千古传诵的名句。全词铺叙委婉，情景交融，是柳永慢词的代表作。"
  },
  "望海潮·东南形胜|柳永": {
    y: "杭州地处东南方，地理形势优越，风景优美，是三吴的都会，这里自古以来就十分繁华。雾气笼罩着的柳树、装饰华美的桥梁，挡风的帘子、青绿色的帐幕，楼阁高高低低，大约有十万户人家。高耸入云的树木，围绕着钱塘江沙堤，汹涌的江水卷起雪白的浪花，天堑般的钱塘江一望无边。市场上陈列着珍宝，家家户户都存满了绫罗绸缎，争相比奢华。\n里湖、外湖与重重叠叠的山岭非常清秀美丽，有秋天的桂子，十里的荷花。晴天欢快地奏乐，夜晚划船采菱唱歌，钓鱼的老翁、采莲的姑娘都嬉笑颜开。千名骑兵簇拥着长官，乘醉听吹箫击鼓，观赏、吟唱烟霞风光。他日画上美好景致，回京升官时向人们夸耀。",
    s: "《望海潮》是柳永描写杭州繁华景象的名作，“三秋桂子，十里荷花”以极简练的笔墨概括了杭州的美景，成为千古传诵的名句。全词铺叙了杭州的自然风光、市井繁华和百姓生活，是宋词中描写城市风貌的杰作，相传金主完颜亮读此词后，遂起投鞭渡江之志。"
  },
  "八声甘州·对潇潇暮雨洒江天|柳永": {
    y: "面对着潇潇暮雨从天空洒落在江面上，经过一番雨洗的秋景，分外寒凉清朗。凄凉的霜风一阵紧似一阵，关山江河一片冷清萧条，落日的余光照耀在高楼上。到处红花凋零翠叶枯落，一切美好的景物渐渐地衰残。只有那滔滔的长江水，不声不响地向东流淌。\n不忍心登高遥看远方，眺望渺茫遥远的故乡，渴求回家的心思难以收拢。叹息这些年来的行踪，为什么苦苦地长期停留在异乡？想着佳人正在华丽的楼上抬头凝望思念着我，多少次错把远处驶来的船当作心上人回家的船。她哪会知道我，倚着栏杆，愁思正如此的深重。",
    s: "《八声甘州》是柳永羁旅词的代表作，“渐霜风凄紧，关河冷落，残照当楼”被苏轼评为“不减唐人高处”。全词以萧瑟的秋景衬托游子的思乡之情，“想佳人妆楼颙望，误几回、天际识归舟”从对方落笔，将思念写得曲折深婉，是柳永慢词的杰作。"
  },
  "蝶恋花·伫倚危楼风细细|柳永": {
    y: "我长时间倚靠在高楼的栏杆上，微风拂面一丝丝一细细，望不尽的春日离愁，沮丧忧愁从遥远无边的天际升起。碧绿的草色，飘忽缭绕的云霭雾气掩映在落日余晖里，默默无言谁理解我靠在栏杆上的心情。\n本想尽情放纵喝个一醉方休，想要在举杯歌唱时勉强寻欢作乐，反而觉得毫无意味。我日渐消瘦也不觉得懊悔，为了你我情愿一身憔悴。",
    s: "《蝶恋花》是柳永的名作，“衣带渐宽终不悔，为伊消得人憔悴”以身体的消瘦写对爱情的执着，被王国维称为“古今之成大事业、大学问者”的第二境界。全词以登高望远起笔，将相思之情写得深沉执着，是婉约词的佳作。"
  },
  "念奴娇·赤壁怀古|苏轼": {
    y: "大江浩浩荡荡向东流去，滔滔巨浪淘尽了千古以来的英雄人物。那旧营垒的西边，人们说就是三国时周瑜大破曹军的赤壁。陡峭的乱石直插云霄，汹涌的惊涛拍打着江岸，卷起千万堆白雪般的浪花。江山壮美如画，一时间涌现出多少英雄豪杰。\n遥想当年的周瑜，小乔刚刚嫁给他，英姿勃发，气度不凡。他手摇羽扇，头戴纶巾，谈笑之间，就把曹军的战船烧得灰飞烟灭。我今日神游古战场，应该笑我太多愁善感，早早地生出了白发。人生就像一场梦，且洒一杯酒，祭奠这江上的明月。",
    s: "《念奴娇·赤壁怀古》是豪放词的巅峰之作，也是苏轼最具代表性的作品。全词借赤壁怀古，写尽历史沧桑与人生旷达，气势雄浑，境界开阔。“大江东去”四字开篇，便奠定了全词磅礴的基调，是宋词中流传最广、影响力最大的作品之一。"
  },
  "水调歌头·明月几时有|苏轼": {
    y: "丙辰年的中秋节，我畅饮到天亮，喝得大醉，写下这首词，同时思念弟弟苏辙。明月是从什么时候开始有的？我端着酒杯问苍天。不知道天上的仙宫，今晚是哪一年。我想乘着清风回到天上，又怕那美玉砌成的楼宇太高，受不住那里的寒冷。起身在月光下起舞，影子也随着舞动，哪里比得上人间的温暖。\n月光转过朱红的楼阁，低低地照进雕花的门窗，照着无法入眠的人。月亮不该有什么怨恨吧，为什么偏偏在人们离别的时候变得圆满？人有悲欢离合的变迁，月有阴晴圆缺的更替，这样的事自古以来就难以周全。只希望世上所有人都能平安长久，即便相隔千里，也能共享这美好的月光。",
    s: "《水调歌头》被誉为“中秋词第一”，千百年来每逢中秋便被人反复吟诵。全词由望月发问起笔，从对天上的想象，落到人间的离别，最终以旷达的祝愿收尾，既有对亲人的思念，又有对人生的通透感悟。“但愿人长久，千里共婵娟”更是成为中国人最经典的中秋祝福。"
  },
  "江城子·密州出猎|苏轼": {
    y: "我姑且抒发一下少年的豪情壮志，左手牵着黄犬，右臂托起苍鹰，头戴华美鲜艳的帽子，身穿貂鼠皮衣，带着随从疾风般席卷平坦的山冈。为了报答全城的人跟随我出猎的盛意，我要像孙权一样，亲自射杀猛虎。\n我痛饮美酒，心胸开阔，胆气更为豪壮，两鬓微微发白，这又有何妨？什么时候皇帝会派人下来，就像汉文帝派遣冯唐去云中赦免魏尚一样信任我呢？那时我将使尽力气拉满雕弓就像满月一样，瞄准西北，射向西夏军队。",
    s: "《江城子·密州出猎》是苏轼第一首豪放词，“会挽雕弓如满月，西北望，射天狼”表达了诗人渴望为国戍边、抗击外敌的雄心壮志。全词气势磅礴，节奏明快，一改词为“艳科”的传统，开创了豪放词派，在词史上具有重要意义。"
  },
  "江城子·乙卯正月二十日夜记梦|苏轼": {
    y: "你我夫妻诀别已经整整十年，强忍不去思念可终究难相忘。千里之外那座遥远的孤坟啊，竟无处向你倾诉满腹的悲凉。纵然夫妻相逢你也认不出我，我已经是灰尘满面、两鬓如霜。\n昨夜我在梦中忽然回到了家乡，在小屋窗口你正在打扮梳妆。你我二人默默相对惨然不语，只有相对无言泪落千行。料想得到我当年想她的地方，就在明月的夜晚矮松的山冈。",
    s: "《江城子·乙卯正月二十日夜记梦》是苏轼悼念亡妻王弗的词作，也是中国文学史上最著名的悼亡词。“十年生死两茫茫，不思量，自难忘”开篇便将生死相隔的思念写得深沉动人，“相顾无言，惟有泪千行”将梦中重逢的悲喜写得淋漓尽致。全词情感真挚，感人至深。"
  },
  "定风波·莫听穿林打叶声|苏轼": {
    y: "三月七日，在沙湖道上赶上了下雨，拿着雨具的仆人先前离开了，同行的人都觉得很狼狈，只有我不这么觉得。过了一会儿天晴了，就做了这首词。不用注意那穿林打叶的雨声，何妨放开喉咙吟唱从容而行。竹杖和草鞋轻捷得胜过骑马，有什么可怕的？一身蓑衣任凭风吹雨打，照样过我的一生。\n春风微凉吹醒我的酒意，微微有些冷，山头初晴的斜阳却应时相迎。回头望一眼走过来的风雨萧瑟的地方，我信步归去，不管它是风雨还是放晴。",
    s: "《定风波》是苏轼被贬黄州时所作，借途中遇雨的小事，抒发了自己旷达超脱的人生态度。“一蓑烟雨任平生”“也无风雨也无晴”表达了诗人面对人生风雨的从容与豁达，是苏轼人生哲学的集中体现。全词以小见大，寓意深刻，是苏轼词的代表作。"
  },
  "水龙吟·次韵章质夫杨花词|苏轼": {
    y: "非常像花又好像不是花，无人怜惜任凭衰零坠地。它飘泊无家，傍路而行，仔细思量起来，看似无情，却自有愁思。萦绕牵挂，愁坏了柔肠，困倦得睁不开娇媚的眼睛，刚要睁开又闭上。梦中随风万里，去寻觅情郎的去处，却又被黄莺的啼叫声唤起。\n不恨杨花飘飞落尽，只恨西园里的落花难以再连缀。清晨一阵雨过后，杨花的踪迹何在？已化作一池碎萍。如果把春色分为三分，二分化为了尘土，一分付诸了流水。细细看来，那飘飞的不是杨花，点点都是离人的眼泪。",
    s: "《水龙吟·次韵章质夫杨花词》是苏轼咏物词的代表作，王国维称“东坡杨花词，和韵而似原唱”。“似花还似非花”抓住了杨花的特点，“细看来，不是杨花，点点是离人泪”以杨花比喻离人泪，将咏物与抒情融为一体，意境优美，情感深沉，是咏物词的千古绝唱。"
  },
  "卜算子·黄州定慧院寓居作|苏轼": {
    y: "弯弯的勾月悬挂在疏落的梧桐树上；夜阑人静，漏壶的水早已滴光了。有谁见到幽居的人独自往来，仿佛天边孤雁般缥缈的身影。\n突然惊起又回过头来，心有遗憾却无人知情。挑遍了寒枝也不肯栖息，甘愿在沙洲忍受寂寞凄冷。",
    s: "《卜算子》是苏轼被贬黄州时所作，以孤鸿自喻，“拣尽寒枝不肯栖，寂寞沙洲冷”表达了诗人虽身处逆境，却依然坚守高洁品格、不肯随波逐流的精神。全词意境幽冷，情感深沉，是苏轼婉约词的代表作。"
  },
  "鹊桥仙·纤云弄巧|秦观": {
    y: "纤薄的云彩在天空中变幻多端，天上的流星传递着相思的愁怨，遥远无垠的银河今夜我悄悄渡过。在秋风白露的七夕相会，就胜过尘世间那些长相厮守却貌合神离的夫妻。\n缱绻的柔情像流水般绵绵不断，重逢的约会如梦影般缥缈虚幻，分别之时不忍去看那鹊桥路。只要两情至死不渝，又何必贪求卿卿我我的朝欢暮乐呢。",
    s: "《鹊桥仙》是秦观最著名的词作，借牛郎织女的神话故事，歌颂了坚贞不渝的爱情。“两情若是久长时，又岂在朝朝暮暮”一反传统七夕词的伤感，表达了爱情贵在长久、不在朝夕的独到见解，成为千古传诵的爱情名句。"
  },
  "浣溪沙·漠漠轻寒上小楼|秦观": {
    y: "薄薄春寒无声无息地侵入小楼，拂晓阴云惨淡像荒凉的暮秋，彩色的屏风画着淡烟笼罩流水。\n柳絮飞舞如虚无缥缈的梦境，丝丝细雨落下如同我的忧愁，再看那缀着珠宝的帘子正随意悬挂在小小银钩之上。",
    s: "《浣溪沙》是秦观婉约词的代表作，“自在飞花轻似梦，无边丝雨细如愁”以梦喻花、以愁喻雨，将抽象的愁绪写得具体可感，对仗工整，意境优美。全词以轻灵的笔触描写了春日的闲愁，是婉约词的精品。"
  },
  "踏莎行·郴州旅舍|秦观": {
    y: "暮霭沉沉，楼台消失在浓雾中，月色朦胧，渡口也隐没不见。望断了天涯，理想中的桃花源无处寻觅。怎能忍受得了独居在孤寂的客馆，春寒料峭，斜阳西下，杜鹃声声哀鸣！\n远方的友人的音信，寄来了温暖的关心和嘱咐，却平添了我深深的别恨离愁。郴江啊，你本来是环绕着郴山奔流，为什么偏偏要流到潇湘去呢？",
    s: "《踏莎行·郴州旅舍》是秦观被贬郴州时所作，“郴江幸自绕郴山，为谁流下潇湘去”以郴江绕郴山却又流向潇湘，比喻自己本想安居却被迫漂泊，含蓄深沉。苏轼极爱此两句，曾书于扇上。全词意境凄迷，情感深沉，是秦观词的代表作。"
  },
  "苏幕遮·燎沉香|周邦彦": {
    y: "焚烧沉香，来消除夏天闷热潮湿的暑气。鸟雀鸣叫呼唤着晴天，拂晓时分我偷偷听它们在屋檐下窃窃私语。初出的阳光晒干了荷叶上昨夜的雨滴，水面上的荷花清润圆正，微风吹过，荷叶一一挺立。\n想到那遥远的故乡，什么时候才能回去啊？我家本在吴越一带，长久地客居长安。五月，我故乡的小时候的伙伴是否在想我？划着一叶扁舟，在我的梦中来到了过去的荷花塘。",
    s: "《苏幕遮》是周邦彦的名作，“叶上初阳干宿雨，水面清圆，一一风荷举”以极简练的笔墨写出了雨后荷叶的生动姿态，王国维评为“真能得荷之神理者”。全词由写景到思乡，过渡自然，意境清新，是周邦彦词的代表作。"
  },
  "兰陵王·柳|周邦彦": {
    y: "正午的柳荫直直地落下，雾霭中，丝丝柳枝随风摆动。在古老的隋堤上，曾经多少次看见柳絮飞舞，把匆匆离去的人相送。登上高堤，望故乡，谁能理解我这个在京城漂泊已久的倦客？在长亭送别的路上，年复一年，折下的柳枝恐怕已超过千尺了吧。\n闲暇时寻找旧日的踪迹，又一次在哀怨的弦乐声中饮酒，灯光照着离别的宴席。梨花盛开，榆火取新，寒食节又到了。令人忧愁的是船行如箭，风助船快，竹篙一点，水波荡漾，回头之间已经过了几个驿站，送行的人已远在天北。\n心中凄恻，离恨层层堆积！送别的水边渐渐迂回曲折，渡口的守望所一片寂静，夕阳缓缓西下，春色无边无际。想起当年在月光下的水榭携手，在露水沾湿的桥上听笛。沉思往事，恍如梦中，眼泪暗暗滴落。",
    s: "《兰陵王·柳》是周邦彦的代表作，也是宋代慢词的典范。全词以柳起兴，铺写离别之情，层次分明，回环往复。“柳阴直，烟里丝丝弄碧”写柳之美，“登临望故国，谁识京华倦客”点出羁旅之愁，“沉思前事，似梦里，泪暗滴”以情作结，余味无穷。全词格律严谨，语言典雅，是周邦彦词的代表作。"
  },
  "声声慢·寻寻觅觅|李清照": {
    y: "苦苦地寻觅，却只落得冷冷清清，一派凄惨悲戚的景象。天气忽暖忽寒的时候，最难调养身体。喝两三杯淡酒，又怎么抵挡得住傍晚袭来的寒风？一行大雁从天上飞过，正让人伤心，却发现它们都是当年见过的旧相识。\n满地的黄花堆积零落，花儿都已经憔悴不堪，如今还有谁来采摘？守着窗子，独自一人，怎么挨到天黑？梧桐叶上滴着细雨，到了黄昏时分，还是点点滴滴下个不停。这般情景，怎么是一个“愁”字就能说得尽的！",
    s: "《声声慢》是李清照南渡之后的代表作，也是婉约词的千古绝唱。开篇七组叠词，一气呵成，将孤苦无依的心境渲染到极致。全词围绕一个“愁”字，从日常景物入手，层层递进，将国破家亡、身世飘零的沉痛写得入木三分，读来催人泪下。"
  },
  "如梦令·常记溪亭日暮|李清照": {
    y: "经常记起在溪边的亭子游玩直到太阳落山的时候，被美景陶醉而流连忘返。游兴满足了，天黑往回划船，不小心划进了荷花池深处。划呀，划呀，惊动满滩的水鸟，都飞起来了。",
    s: "《如梦令》是李清照早期的作品，回忆了少女时代溪亭游赏的欢乐场景。“争渡，争渡，惊起一滩鸥鹭”以急促的节奏和生动的画面，写出了少女的天真活泼。全词语言明快，意境优美，是李清照早期词的代表作。"
  },
  "如梦令·昨夜雨疏风骤|李清照": {
    y: "昨夜雨虽然下得稀疏，但是风却劲吹不停，酣睡一夜仍有余醉未消。问那正在卷帘的侍女，外面的情况如何，她却说海棠花依然和昨天一样。知道吗？知道吗？这个时节应该是绿叶繁茂，红花凋零了。",
    s: "《如梦令》是李清照早期的名作，“知否，知否？应是绿肥红瘦”以“绿肥红瘦”概括暮春景象，“绿”代叶，“红”代花，“肥”“瘦”二字生动传神，将对春光流逝的惋惜写得含蓄深沉。全词篇幅短小，却意蕴丰富，是李清照词的精品。"
  },
  "一剪梅·红藕香残玉簟秋|李清照": {
    y: "粉红色的荷花已经凋谢，幽香也已消散，光滑如玉的竹席带着秋的凉意。解开绫罗裙，换着便装，独自登上小船。仰头凝望远天，那白云舒卷处，谁会将锦书寄来？雁群飞回来时，月光已经洒满了西楼。\n落花独自地飘零着，水独自地流淌着。彼此都在思念对方，可又不能互相倾诉，只好各在一方独自愁闷着。这相思的愁苦实在无法排遣，刚从微蹙的眉间消失，又隐隐缠绕上了心头。",
    s: "《一剪梅》是李清照写给丈夫赵明诚的词作，“此情无计可消除，才下眉头，却上心头”将相思之情写得生动传神，眉头刚舒展，心头又涌上愁思，把那种无法排遣的思念写得入木三分。全词语言清丽，情感真挚，是李清照婉约词的代表作。"
  },
  "醉花阴·薄雾浓云愁永昼|李清照": {
    y: "薄雾弥漫，云层浓密，日子过得郁闷愁烦，龙脑香在金兽香炉中缭袅。又到了重阳佳节，卧在玉枕纱帐中，半夜的凉气刚将全身浸透。\n在东篱边饮酒直到黄昏以后，淡淡的黄菊清香溢满双袖。此时此地怎么能不令人伤感呢？风乍起，卷帘而入，帘内的人儿因过度思念身形竟比那黄花还要瘦弱。",
    s: "《醉花阴》是李清照重阳节思念丈夫所作，“莫道不销魂，帘卷西风，人比黄花瘦”以黄花比喻人的消瘦，将相思之苦写得生动传神，成为千古传诵的名句。相传赵明诚收到此词后，闭门谢客，写了五十首词与李清照的词混在一起，请友人陆德夫品评，陆德夫说“只三句绝佳”，正是“莫道不销魂，帘卷西风，人比黄花瘦”。"
  },
  "武陵春·风住尘香花已尽|李清照": {
    y: "风停了，尘土里带有花的香气，花儿已凋落殆尽。日头已经升的老高，我却懒得来梳妆。景物依旧，人事已变，一切事情都已经完结。想要倾诉自己的感慨，还未开口，眼泪先流下来。\n听说双溪春景尚好，我也打算泛舟前去。只恐怕双溪蚱蜢般的小船，载不动我内心沉重的忧愁。",
    s: "《武陵春》是李清照南渡后的作品，“只恐双溪舴艋舟，载不动许多愁”以小船载不动愁的奇特比喻，将抽象的愁绪写得具体可感，与李煜“问君能有几多愁，恰似一江春水向东流”异曲同工。全词语言朴素，情感深沉，是李清照晚年词的代表作。"
  },
  "破阵子·为陈同甫赋壮词以寄之|辛弃疾": {
    y: "醉梦里挑亮油灯观看宝剑，梦中回到了当年的各个营垒，接连响起号角声。把烤牛肉分给部下，乐队演奏北疆歌曲。这是秋天在战场上阅兵。\n战马像的卢马一样跑得飞快，弓箭像惊雷一样，震耳离弦。我一心想替君主完成收复国家失地的大业，取得世代相传的美名。可怜已成了白发人！",
    s: "《破阵子》是辛弃疾写给好友陈亮的壮词，“醉里挑灯看剑，梦回吹角连营”开篇便写出了词人渴望收复中原的壮志，“了却君王天下事，赢得生前身后名”表达了词人的理想，结尾“可怜白发生”以壮志未酬的悲愤作结，全词气势磅礴，情感跌宕，是辛弃疾豪放词的代表作。"
  },
  "永遇乐·京口北固亭怀古|辛弃疾": {
    y: "历经千古的江山，再也难找到像孙权那样的英雄。当年的舞榭歌台还在，英雄人物却随着岁月的流逝早已不复存在。斜阳照着长满草树的普通小巷，人们说那是当年刘裕曾经住过的地方。回想当年，他领军北伐、收复失地的时候是何等威猛。\n然而刘裕的儿子刘义隆好大喜功，仓促北伐，却反而让北魏太武帝拓跋焘乘机挥师南下，兵抵长江北岸而返，遭到对手的重创。我回到南方已经有四十三年了，看着中原仍然记得，当年扬州路上，到处是金兵南侵的战火烽烟。怎么能回首啊，当年拓跋焘的行宫外竟有百姓在那里祭祀，乌鸦啄食祭品，人们过着社日，只把他当作一位神祇来供奉，还有谁会记得，这曾是异族皇帝的行宫？还有谁会问，廉颇老了，饭量还好吗？",
    s: "《永遇乐·京口北固亭怀古》是辛弃疾晚年的代表作，也是豪放词的巅峰之作。全词借古讽今，用孙权、刘裕、刘义隆、廉颇等历史典故，抒发了自己渴望收复中原、却不被重用的悲愤。“想当年，金戈铁马，气吞万里如虎”“凭谁问：廉颇老矣，尚能饭否”都是千古传诵的名句，全词用典精当，气势雄浑，是辛弃疾词的压卷之作。"
  },
  "青玉案·元夕|辛弃疾": {
    y: "东风吹开了元宵夜的火树银花，花灯灿烂，就像千树花开。从天而降的礼花，犹如星雨。豪华的马车在飘香的街道行过。悠扬的凤箫声四处回荡，玉壶般的明月渐渐向西边倾斜，一夜鱼龙灯飞舞笑语喧哗。\n美人头上都戴着亮丽的饰物，笑语盈盈地随人群走过，身上香气飘洒。我在人群中寻找她千百回，猛然回头，不经意间却在灯火零落之处发现了她。",
    s: "《青玉案·元夕》是辛弃疾婉约词的代表作，“众里寻他千百度，蓦然回首，那人却在，灯火阑珊处”被王国维称为“古今之成大事业、大学问者”的第三境界。全词以元夕的繁华热闹反衬“那人”的孤独清高，寄托了词人不与世俗同流合污的高洁品格，意境深远，余味无穷。"
  },
  "摸鱼儿·更能消几番风雨|辛弃疾": {
    y: "淳熙己亥年，我由湖北转运副使调任湖南转运副使，同僚王正之在小山亭设酒饯行，我写下这首词。还经得起几回风雨，春天又将匆匆归去。爱惜春天我常怕花开得过早，何况此时已落红无数。春天啊，请暂且留步，听说天涯芳草已经遮断了你的归路。我埋怨春天总是默默无语。算来只有画檐下的蜘蛛网，整天殷勤地沾惹飞舞的柳絮。\n长门宫的陈皇后，本约好的佳期又被耽误。美貌的女子从来遭人嫉妒。纵然能花千金买得司马相如的赋，这脉脉深情又能向谁倾诉？你们不要得意忘形地跳舞，难道没看见杨玉环、赵飞燕都化作了尘土！无端的闲愁最是痛苦。不要去倚靠高高的栏杆，夕阳正照在烟柳迷蒙的令人断肠之处。",
    s: "《摸鱼儿》是辛弃疾婉约词的代表作，以暮春景象寄托政治感慨。“更能消、几番风雨，匆匆春又归去”以春逝暗喻南宋国势的衰微，“斜阳正在，烟柳断肠处”以景结情，余味无穷。全词比兴深婉，寄托遥深，梁启超评此词“回肠荡气，至于此极，前无古人，后无来者”。"
  },
  "西江月·夜行黄沙道中|辛弃疾": {
    y: "皎洁的月光从树枝间掠过，惊飞了枝头喜鹊，清凉的晚风吹来仿佛听见了远处的蝉叫声。田里稻花飘香，蛙声阵阵，似乎在告诉人们今年是一个丰收年。\n天边几颗星星忽明忽暗，山前下起了淅淅沥沥的小雨。往日的小茅草屋还在土地庙的树林旁，道路转过溪水的源头，它便忽然出现在眼前。",
    s: "《西江月·夜行黄沙道中》是辛弃疾描写农村风光的名作，“稻花香里说丰年，听取蛙声一片”以蛙声和稻花香写出了农村的丰收景象，充满生活气息。全词语言清新自然，意境优美，是辛弃疾农村词的代表作。"
  },
  "丑奴儿·书博山道中壁|辛弃疾": {
    y: "人年轻的时候不懂忧愁的滋味，喜欢登高远望。喜欢登高远望，为了写出新词，没有愁而硬要说有愁。\n现在尝尽了忧愁的滋味，想说却说不出。想说却说不出，却说道：好个凉爽的秋天呀！",
    s: "《丑奴儿》以“少年”与“而今”的对比，写出了对“愁”的不同理解。少年时“为赋新词强说愁”，是无病呻吟；而今“识尽愁滋味”，却“欲说还休”，因为真正的愁是无法言说的。全词以浅近的语言表达了深沉的人生感慨，是辛弃疾词的名篇。"
  },
  "钗头凤·红酥手|陆游": {
    y: "你红润酥腻的手里，捧着盛上黄縢酒的杯子。满城荡漾着春天的景色，你却早已像宫墙中的绿柳那般遥不可及。春风多么可恶，将欢情吹得那样稀薄。满怀的忧愁情绪，离别几年来的生活十分萧索。遥想当初，只能感叹：错，错，错！\n春景依旧，只是人却白白相思地消瘦。泪水洗尽脸上的胭脂红，又把薄绸的手帕全都湿透。满春的桃花凋落在寂静空旷的池塘楼阁上。永远相爱的誓言还在，可是锦文书信再也难以交付。遥想当初，只能感叹：莫，莫，莫！",
    s: "《钗头凤》是陆游写给前妻唐琬的词作，讲述了陆游与唐琬的爱情悲剧。“红酥手，黄縢酒”写昔日的恩爱，“东风恶，欢情薄”写被迫分离的痛苦，“山盟虽在，锦书难托”写旧情难续的无奈。全词情感真挚，催人泪下，是中国文学史上最著名的爱情词之一。"
  },
  "卜算子·咏梅|陆游": {
    y: "驿站之外的断桥边，梅花孤单寂寞地绽开了花，无人过问。暮色降临，梅花无依无靠，已经够愁苦了，却又遭到了风雨的摧残。\n梅花并不想费尽心思去争艳斗宠，对百花的妒忌与排斥毫不在乎。即使凋零了，被碾作泥土，又化作尘土了，梅花依然和往常一样散发出缕缕清香。",
    s: "《卜算子·咏梅》是陆游咏物言志的名作，以梅花自喻，“零落成泥碾作尘，只有香如故”表达了诗人虽屡遭排挤、身处逆境，却依然坚守高洁品格的精神。全词以梅喻人，托物言志，是咏梅词中的杰作。"
  },
  "诉衷情·当年万里觅封侯|陆游": {
    y: "回想当年为了建功立业驰骋万里，单枪匹马奔赴边境戍守梁州。如今防守边疆要塞的从军生活只能在梦中出现，梦一醒不知身在何处？唯有曾穿过的貂裘，已积满灰尘变得又暗又旧。\n胡人还未消灭，自己的双鬓却早已白如秋霜，只能任忧国的眼泪白白地流淌。谁能料我这一生，心始终在前线抗敌，人却老死在沧洲！",
    s: "《诉衷情》是陆游晚年的作品，“当年万里觅封侯，匹马戍梁州”追忆了早年的抗金经历，“胡未灭，鬓先秋，泪空流”写出了壮志未酬的悲愤，“心在天山，身老沧洲”将理想与现实的矛盾写得淋漓尽致。全词情感沉郁，感人至深。"
  },
  "扬州慢·淮左名都|姜夔": {
    y: "淳熙丙申年冬至，我路过扬州。夜里初雪放晴，满眼都是荠菜麦子。进入城中，四顾萧条，寒水碧绿，暮色渐起，戍角悲鸣。我心中悲伤，感慨今昔，于是自创此曲。千岩老人认为此词有《黍离》之悲。\n扬州是淮河东边著名的大都，在竹西亭美好的住处，解下马鞍稍作停留，这是最初的路程。经过春风十里的扬州路，如今全是青青的荠麦。自从金兵进犯长江回去以后，荒废了池苑，伐去了乔木，至今还讨厌说起旧日用兵。天气渐渐到了黄昏，凄凉的号角吹起了寒气，这都是在被洗劫一空的空城中。\n杜牧有卓越的鉴赏力，料想今天重来此地一定会吃惊。即使有写“豆蔻”的精工词采，有写“青楼梦好”的才华，也难以表达出深沉的悲痛。二十四桥仍然还在，桥下江中的波浪荡漾，凄冷的月光默默无声。想桥边的红芍药，年年盛开，究竟是为谁而生呢？",
    s: "《扬州慢》是姜夔的代表作，描写了扬州经过金兵洗劫后的萧条景象，抒发了对国家衰亡的感慨。“过春风十里，尽荠麦青青”以昔日繁华与今日荒凉对比，“二十四桥仍在，波心荡，冷月无声”以景结情，余味无穷。全词意境凄清，情感深沉，是南宋婉约词的杰作。"
  },
  "暗香·旧时月色|姜夔": {
    y: "辛亥年冬天，我冒雪去拜访石湖居士。住了一个多月，他给我纸索要诗句，并要求创作新的曲调，我作了这两首曲子。石湖居士反复把玩，让歌女练习演唱，音节和谐婉转，于是命名为《暗香》《疏影》。\n昔日的月色，曾多少次照耀我，在梅花边吹笛？唤起美人，不顾清寒一起攀折梅花。何逊如今渐渐老去，都忘却了春风般的词笔。只奇怪竹外稀疏的梅花，冷香飘入华美的筵席。\n江南水乡，正一片寂静，感叹寄梅路途遥远，夜雪刚刚堆积。翠绿的酒杯前容易落泪，红梅无言，耿耿相忆。永远记得曾携手的地方，千树梅花压着西湖寒碧的湖水。如今梅花又一片片被吹尽了，什么时候才能再见到呢？",
    s: "《暗香》是姜夔自度曲的代表作，与《疏影》并为咏梅词的双璧。全词以梅花为线索，将个人身世之感与家国之恨融为一体，意境清空，情感深沉。张炎评姜夔词“如野云孤飞，去留无迹”，此词正是这种风格的典范。"
  },
  "苏幕遮·怀旧|范仲淹": {
    y: "云天蓝碧，黄叶落满地，天边秋色与秋波相连，波上弥漫着空翠略带寒意的秋烟。远山沐浴着夕阳天空连接着江水。不解思乡之苦的芳草，一直延伸到夕阳之外的天际。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，每天夜里除非是美梦才能留人入睡。当明月照射高楼时不要独自依倚，端起酒来洗涤愁肠，可是都化作相思的眼泪。",
    s: "《苏幕遮·怀旧》是范仲淹的代表作，“碧云天，黄叶地”是千古传诵的写景名句，“酒入愁肠，化作相思泪”将相思之情写得真挚动人。全词上阕写景，下阕抒情，意境开阔，情感深沉，是宋词中的佳作。"
  },
  "渔家傲·秋思|范仲淹": {
    y: "秋天到了，西北边塞的风光和江南大不同。大雁又飞回了衡阳，一点也没有停留之意。黄昏时分，号角吹起，边塞特有的风声、马啸声、羌笛声和着号角声从四面八方回响起来。连绵起伏的群山里，夕阳西下，青烟升腾，孤零零的一座城城门紧闭。\n饮一杯浊酒，不由得想起万里之外的亲人，眼下战事未平，功名未立，还不能早作归计。远方传来羌笛的悠悠之声，天气寒冷，霜雪满地。夜深了，在外征战的人都难以入睡，将军已是头发花白，士兵抹着思乡的泪水。",
    s: "《渔家傲·秋思》是范仲淹镇守西北边疆时所作，“塞下秋来风景异”开篇便写出了边塞的荒凉，“将军白发征夫泪”将将士们的思乡之情和报国之志写得深沉感人。全词意境苍凉，情感真挚，是宋词中少有的边塞词，开豪放词之先声。"
  },
  "浣溪沙·一向年光有限身|晏殊": {
    y: "人的生命是有限的，时光是短暂的，离别是容易让人销魂的。不要推辞频繁的酒筵歌席。\n空自思念远方的人，满目山河也无济于事，风雨中的落花更让人伤春。不如好好珍惜眼前的人。",
    s: "《浣溪沙·一向年光有限身》是晏殊的名作，“满目山河空念远，落花风雨更伤春。不如怜取眼前人”是千古传诵的名句，表达了珍惜当下、把握眼前的人生态度。全词语言清丽，情感深沉，是晏殊婉约词的代表作。"
  },
  "破阵子·春景|晏殊": {
    y: "燕子飞来正赶上社祭之时，梨花落了之后就是清明。池塘边点缀着几点青苔，树叶底下传来一两声黄鹂的啼叫。白日渐长，柳絮轻盈地飞舞。\n东邻的少女们笑得天真烂漫，在采桑的路上相遇。怪不得昨夜做了个好梦，原来是今天斗草赢了。笑容从双颊上绽开。",
    s: "《破阵子·春景》是晏殊描写春日少女生活的词作，“池上碧苔三四点，叶底黄鹂一两声”以细腻的笔触写出了春日的生机，“笑从双脸生”将少女的天真快乐写得生动传神。全词语言明快，充满生活气息，是晏殊词中少有的轻快之作。"
  },
  "蝶恋花·庭院深深深几许|欧阳修": {
    y: "庭院深深，不知有多深？杨柳依依，飞扬起片片烟雾，一重重帘幕不知有多少层。豪华的车马停在贵族公子寻欢作乐的地方，登上高楼也望不见通向章台的大路。\n风狂雨骤的暮春三月，再是重门将黄昏景色掩闭，也无法留住春意。泪眼汪汪问落花可知道我的心意，落花默默不语，纷乱的，零零落落一点一点飞到秋千外。",
    s: "《蝶恋花·庭院深深深几许》是欧阳修的名作，“庭院深深深几许”以三个“深”字渲染了闺房的幽深，“泪眼问花花不语，乱红飞过秋千去”以花的无情反衬人的多情，将闺怨写得含蓄深沉。全词意境凄清，情感细腻，是婉约词的佳作。"
  },
  "玉楼春·尊前拟把归期说|欧阳修": {
    y: "饯行的酒席前就想先把归期说定，一杯心切情切，欲说时佳人无语滴泪，如春风妩媚的娇容，先自凄哀低咽。啊，人生自是有情，情到深处痴绝，这凄凄别恨不关涉楼头的清风与中天的明月。\n饯别的酒宴前，不要再唱新的离歌了，一曲离歌能让人愁肠寸结。啊，此时只需要看遍洛阳城的牡丹，才能够和春风轻松地告别。",
    s: "《玉楼春·尊前拟把归期说》是欧阳修的名作，“人生自是有情痴，此恨不关风与月”是千古传诵的名句，将离别的愁恨归于人的多情，而非风月的无情。全词情感真挚，语言清丽，是欧阳修婉约词的代表作。"
  },
  "浪淘沙·把酒祝东风|欧阳修": {
    y: "端起酒杯向东风祈祷，请你再留些时日不要匆匆离去。洛阳城东郊外的小道已是柳枝满垂。大多是我们去年携手同游的地方，我们游遍了姹紫嫣红的花丛。\n人生的欢聚与别离总是苦短，这遗憾无穷无尽。今年的花比去年开得更红。可惜明年的花会更好，不知又能和谁一同欣赏？",
    s: "《浪淘沙·把酒祝东风》是欧阳修的名作，“今年花胜去年红。可惜明年花更好，知与谁同”以花的年年盛开，反衬人事的聚散无常，将对友人的思念写得含蓄深沉。全词语言清丽，情感真挚，是欧阳修婉约词的代表作。"
  },
  "采桑子·轻舟短棹西湖好|欧阳修": {
    y: "西湖风光好，驾轻舟划短桨多么逍遥。碧绿的湖水绵延不断，长堤上花草散出芳香。隐隐传来的音乐歌唱，像是随着船儿在湖上飘荡。\n无风的水面，光滑得好似琉璃一样，不觉得船儿在前进，只见微微的细浪在船边荡漾。看，被船儿惊起的水鸟，正掠过湖岸在飞翔。",
    s: "《采桑子·轻舟短棹西湖好》是欧阳修描写颍州西湖的组词之一，“无风水面琉璃滑，不觉船移”以细腻的笔触写出了西湖的宁静之美，“微动涟漪，惊起沙禽掠岸飞”以动写静，意境优美。全词语言清丽，充满生活气息。"
  },
  "桂枝香·金陵怀古|王安石": {
    y: "我登上城楼放眼远望，故都金陵正是深秋，天气已变得飒爽清凉。千里澄江宛如一条白练，青翠山峰像箭簇耸立前方。帆船在夕阳下往来穿梭，西风起处，斜插着的酒旗高高飘扬。画船如同在淡云中浮游，白鹭好像在银河里飞舞，丹青妙笔也难描画这壮美风光。\n遥想当年，故都金陵何等繁盛堂皇。可叹在朱雀门外结绮阁楼，六朝君主一个个地相继败亡。自古多少人在此登高怀古，无不对历代荣辱喟叹感伤。六朝旧事已随流水消逝，剩下的只有寒烟惨淡、绿草衰黄。直到如今的商女，还不知亡国的悲恨，时时放声歌唱《后庭》遗曲。",
    s: "《桂枝香·金陵怀古》是王安石的代表作，“千里澄江似练，翠峰如簇”写出了金陵的壮丽景色，“至今商女，时时犹唱，后庭遗曲”借古讽今，表达了对国家命运的忧虑。全词意境开阔，寓意深刻，是宋词中怀古的杰作，苏轼曾赞叹“此老乃野狐精也”。"
  },
  "临江仙·梦后楼台高锁|晏几道": {
    y: "深夜梦回楼台朱门紧锁，宿酒醒后帘幕重重低垂。去年的春恨涌上心头时，人在落花纷扬中幽幽独立，燕子在微风细雨中双双翱飞。\n记得与小蘋初次相见，她穿着绣有两重心字的罗衣。琵琶轻弹，声声诉说相思之情。当时的明月如今还在，曾经照着她像彩云一样归去。",
    s: "《临江仙·梦后楼台高锁》是晏几道的代表作，“落花人独立，微雨燕双飞”以工整的对仗写出了孤独与相思，“当时明月在，曾照彩云归”以明月和彩云比喻往事，将对恋人的思念写得含蓄深沉。全词意境优美，情感真挚，是婉约词的杰作。"
  },
  "鹧鸪天·彩袖殷勤捧玉钟|晏几道": {
    y: "你挥舞彩袖手捧酒杯殷勤劝酒，回想当年心甘情愿地醉倒在你的红颜中。翩翩起舞，舞到杨柳梢头的月亮西沉，尽情歌唱，唱到桃花扇底的风都停歇。\n自从离别后，总想重相逢，多少回你我在梦中重逢。今夜我反复把银灯照亮，只怕这次相逢又是在梦中。",
    s: "《鹧鸪天·彩袖殷勤捧玉钟》是晏几道的代表作，“舞低杨柳楼心月，歌尽桃花扇底风”以工整的对仗写出了昔日欢聚的欢乐，“今宵剩把银釭照，犹恐相逢是梦中”将久别重逢的惊喜写得真挚动人。全词情感真挚，语言清丽，是婉约词的杰作。"
  },
  "卜算子·送鲍浩然之浙东|王观": {
    y: "水像美人流动的眼波，山如美人蹙起的眉毛。想问行人去哪里？到山水交汇的地方。\n刚刚把春天送走，又要送你归去。要是到江南赶上春天，千万要把春天的景色留住。",
    s: "《卜算子·送鲍浩然之浙东》是王观的名作，“水是眼波横，山是眉峰聚”以美人的眼波和眉峰比喻山水，构思巧妙，“若到江南赶上春，千万和春住”将送别与迎春结合，表达了对友人的祝福。全词语言清丽，构思新颖，是宋词中的佳作。"
  },
  "水调歌头·黄州快哉亭赠张偓佺|苏轼": {
    y: "落日中卷起绣帘眺望，亭下江水与碧空相接，远处的夕阳与亭台相映，空阔无际。为了我的来到，你特意在窗户上涂上了清油的朱漆，色彩犹新。这让我想起当年在平山堂的时候，靠着枕席，欣赏江南的烟雨，遥望远方天际孤鸿出没的情景。今天看到眼前的景象，我方体会到欧阳醉翁词句中所描绘的，山色若隐若现的景致。\n广阔的水面十分明净，山峰翠绿的影子倒映其中。忽然江面波涛汹涌，一个渔翁驾着小舟在风浪中掀舞。见此不由得想起了宋玉的《风赋》，像宋玉这样可笑的人，是不可能理解庄子的风是天籁之说的，硬说什么风有雄雌。其实，一个人只要具备至大至刚的浩然之气，就能在任何境遇中都处之泰然，享受到无穷快意的千里雄风。",
    s: "《水调歌头·黄州快哉亭赠张偓佺》是苏轼的代表作，“一点浩然气，千里快哉风”是千古传诵的名句，表达了诗人旷达超脱的人生态度。全词将写景、抒情、议论融为一体，意境开阔，气势磅礴，是苏轼豪放词的代表作。"
  },
  "浣溪沙·游蕲水清泉寺|苏轼": {
    y: "游玩蕲水的清泉寺，寺庙在兰溪的旁边，溪水向西流淌。\n山脚下兰草新抽的幼芽浸润在溪水中，松林间的沙路被雨水冲洗得一尘不染，傍晚时分，细雨萧萧，传来子规的声声啼叫。\n谁说人生就不能再回到少年时期？门前的溪水都还能向西边流淌！不要在老年感叹时光的飞逝啊！",
    s: "《浣溪沙·游蕲水清泉寺》是苏轼被贬黄州时所作，“谁道人生无再少？门前流水尚能西！休将白发唱黄鸡”以溪水西流的现象，表达了老当益壮、积极进取的人生态度。全词意境清新，格调高昂，是苏轼婉约词中的佳作。"
  },
  "蝶恋花·春景|苏轼": {
    y: "花儿残红褪尽，树梢上长出了小小的青杏。燕子飞舞，清澈的河流围绕着村落人家。柳枝上的柳絮已被吹得越来越少，但不要担心，到处都可见茂盛的芳草。\n围墙里面，有一位少女正在荡秋千，墙外的行人都可听见。少女发出动听的笑声，慢慢地，围墙里边的笑声就听不见了，行人惘然若失，仿佛多情的自己被无情的少女所伤害。",
    s: "《蝶恋花·春景》是苏轼的名作，“天涯何处无芳草”是千古传诵的名句，“多情却被无情恼”将单相思的苦恼写得生动有趣。全词语言清丽，意境优美，是苏轼婉约词的代表作。"
  },
  "满庭芳·蜗角虚名|苏轼": {
    y: "微小的虚名，微薄的小利，算来有什么值得忙碌的。凡事都已前定，谁弱谁强又怎样。且趁现在身体还未衰老，让我放浪一些，疏狂一些。百年之中，就算都让我醉，也不过三万六千场。\n细想，人生能有多少时间，忧愁风雨，就占去了一半，又何必拼命去说短论长。有幸面对清风皓月，以苔藓为席，以云幕为帐。江南好啊，千钟美酒，一曲满庭芳。",
    s: "《满庭芳·蜗角虚名》是苏轼的代表作，“蜗角虚名，蝇头微利”以比喻手法写出了名利的微不足道，表达了诗人对名利的淡泊和对自由生活的向往。全词语言旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "行香子·述怀|苏轼": {
    y: "清静的夜晚没有尘埃，月色如银。斟酒时，要斟满十分。浮名浮利，白白地劳神费力。感叹时光如白驹过隙，如击石迸出的火花，如梦中之身。\n虽然怀抱文章之才，开口又有谁亲近。姑且欢乐，尽享天真。什么时候归去，做个闲人。对着一张琴，一壶酒，一溪云。",
    s: "《行香子·述怀》是苏轼的名作，“对一张琴，一壶酒，一溪云”以极简练的笔墨写出了隐居生活的美好，表达了诗人对自由生活的向往。全词语言清丽，意境悠远，是苏轼婉约词的佳作。"
  },
  "定风波·南海归赠王定国侍人寓娘|苏轼": {
    y: "常常羡慕这世间如玉雕琢般丰神俊朗的男子，就连上天也怜惜他，赠予他柔美聪慧的佳人与之相伴。人人称道那女子歌声轻妙，笑容柔美，风起时，那歌声如雪片飞过炎热的夏日使世界变得清凉。\n你从遥远的地方归来却看起来更加年轻了，笑容依旧，笑颜里好像还带着岭南梅花的清香。我问你：“岭南的风土应该不是很好吧？”你却坦然答道：“心安定的地方，便是我的故乡。”",
    s: "《定风波·南海归赠王定国侍人寓娘》是苏轼的名作，“此心安处是吾乡”是千古传诵的名句，表达了随遇而安、旷达超脱的人生态度。全词通过对寓娘的描写，展现了苏轼的人生哲学，语言清丽，情感真挚。"
  },
  "玉蝴蝶·望处雨收云断|柳永": {
    y: "望着雨收云散的天空，我默默凭倚栏杆，目送秋日的时光渐渐远去。晚景萧瑟凄凉，足以引起宋玉那样的悲凉。水面风轻，蘋花渐渐老去，月光露水寒冷，梧桐叶飘黄。这情景让人感伤。故人在哪里，烟水茫茫。\n难忘，我们一起饮酒赋诗的聚会，多少次辜负了风月，多少次变换了星霜。海阔山遥，不知哪里是潇湘。想那双燕，难以凭它们传递远信，指着暮色的天空，空自辨认归航的船。黯然相望。在孤雁的哀鸣声中，我一直站到夕阳西下。",
    s: "《玉蝴蝶·望处雨收云断》是柳永的名作，“故人何在，烟水茫茫”以景结情，将对故人的思念写得含蓄深沉，“断鸿声里，立尽斜阳”以孤雁和夕阳衬托诗人的孤独。全词意境凄清，情感深沉，是柳永慢词的佳作。"
  },
  "少年游·长安古道马迟迟|柳永": {
    y: "在长安古道上骑马缓行，高高的柳树上蝉声纷乱。夕阳在飞鸟之外，秋风在原野之上，极目远望，天幕四垂。\n归云一去没有踪迹，哪里是以前的约期？游冶的兴致已经生疏，酒友也稀少，不像少年时那样了。",
    s: "《少年游·长安古道马迟迟》是柳永的名作，“夕阳鸟外，秋风原上，目断四天垂”以极简练的笔墨写出了秋日的苍茫，“狎兴生疏，酒徒萧索，不似少年时”将人生的沧桑写得深沉感人。全词意境苍凉，情感真挚，是柳永小令的佳作。"
  },
  "鹤冲天·黄金榜上|柳永": {
    y: "在金字题名的榜上，我偶然失去了状元的希望。在圣明的时代暂时遗漏了贤才，该怎么办呢？没有得到好的机遇，怎能不恣意狂荡。何必计较得失？才子词人，自然就是白衣卿相。\n在烟花巷陌里，依约有丹青屏障。幸好有中意的人，可以去寻访。就这样偎红倚翠，风流事，是平生的畅快。青春不过片刻。忍心把浮名，换成了浅斟低唱。",
    s: "《鹤冲天·黄金榜上》是柳永科举落第后所作，“忍把浮名，换了浅斟低唱”表达了对科举功名的蔑视和对自由生活的向往，相传宋仁宗因此批“且去浅斟低唱，何要浮名”，柳永遂自称“奉旨填词柳三变”。全词情感奔放，语言率真，是柳永个性的集中体现。"
  },
  "忆帝京·薄衾小枕凉天气|柳永": {
    y: "小枕薄被，天气凉爽，忽然尝到了离别的滋味。辗转反侧数着寒夜的更鼓，起来了又重新睡下。毕竟不能成眠，一夜长得像一年。\n也打算勒转马头回去。又怎奈已经定下了出行的计划。万种思量，多方开解，只落得寂寞无聊。系住我一生的心，辜负了你千行眼泪。",
    s: "《忆帝京·薄衾小枕凉天气》是柳永的名作，“系我一生心，负你千行泪”以工整的对仗写出了爱情的真挚与离别的痛苦，是千古传诵的名句。全词语言朴素，情感真挚，是柳永婉约词的佳作。"
  },
  "诉衷情·芙蓉金菊斗馨香|晏殊": {
    y: "芙蓉和金菊争香斗艳，天气快要到重阳了。远处的村庄秋色如画，红叶树间夹杂着疏黄。\n流水淡远，碧天辽阔，道路茫茫。登高远望，鸿雁飞来时，引起无限思量。",
    s: "《诉衷情·芙蓉金菊斗馨香》是晏殊的名作，描写了秋日的美丽景色和登高怀远的情思。“芙蓉金菊斗馨香”写出了秋日的生机，“凭高目断，鸿雁来时，无限思量”将思乡之情写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "清平乐·红笺小字|晏殊": {
    y: "精美的红格信笺写满了密密的小字，写尽了我一生的情意。鸿雁在云端，鱼在水中，惆怅的是这份情意难以传递。\n夕阳西下，我独自倚在西楼，远山正对着帘钩。不知那人如今在何处，绿波依旧向东流去。",
    s: "《清平乐·红笺小字》是晏殊的名作，“鸿雁在云鱼在水，惆怅此情难寄”以鸿雁和鱼的典故，写出了书信难寄的惆怅，“人面不知何处，绿波依旧东流”以景结情，将物是人非的感慨写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "木兰花·春景|宋祁": {
    y: "漫步东城感受到风光越来越好，船儿行驶在波纹骤起的水面上。拂晓的轻寒笼罩着如烟的杨柳，惟见那红艳艳的杏花簇绽枝头，春天的意趣热闹非凡。\n人生总是怨恨欢乐太少，谁愿意吝惜千金而轻视欢笑呢。让我为你举起酒杯奉劝斜阳，请留下来把晚花照耀。",
    s: "《木兰花·春景》是宋祁的代表作，“红杏枝头春意闹”以一个“闹”字将春天的生机写得淋漓尽致，宋祁也因此被称为“红杏枝头春意闹尚书”。全词意境优美，情感真挚，是宋词中的佳作。"
  },
  "天仙子·水调数声持酒听|张先": {
    y: "手持酒杯听着《水调》曲，午醉醒来愁还没醒。送走了春天，春天什么时候回来？傍晚照镜，感伤流逝的光景，往事和未来的约定都空自记在心里。\n沙滩上鸳鸯并栖，池塘上暮色降临，云破月出，花影摇曳。重重帘幕密密遮住灯光，风不定，人刚静，明天落花应该铺满了小路。",
    s: "《天仙子·水调数声持酒听》是张先的代表作，“云破月来花弄影”以一个“弄”字将花影写得生动传神，张先也因此被称为“云破月来花弄影郎中”。全词意境优美，情感细腻，是宋词中的佳作。"
  },
  "青门引·春思|张先": {
    y: "天气刚刚变暖还有些微冷，风雨到傍晚才停。庭院寂寞，将近清明，对着残花饮酒，又犯了去年的病。\n楼头的画角声被风吹醒，入夜后重门寂静。哪能忍受，明月又把隔墙的秋千影送过来。",
    s: "《青门引·春思》是张先的名作，“那堪更被明月，隔墙送过秋千影”以明月和秋千影，将相思之情写得含蓄深沉。全词意境凄清，情感细腻，是宋词中的佳作。"
  },
  "剪牡丹·舟中闻双琵琶|张先": {
    y: "野外的绿色连着天空，青天垂到水面，白色的水光荡漾都很明净。柳树下的小路没有人，柳絮飘落飞无影。汀洲上日落人归，长巾薄袖，采香拾翠竞相游玩。好像懂得凌波微步，停泊在烟渚的春夜。\n彩绦朱索刚刚整理好。宿在绣屏边，画船上风已定。金凤凰响在双槽上，弹出今古的幽思谁能领会。玉盘大小乱珠迸溅。酒上了妆面，花艳和媚相并。再听。弹尽汉妃一曲，江空月静。",
    s: "《剪牡丹·舟中闻双琵琶》是张先的名作，描写了舟中听琵琶的情景。“玉盘大小乱珠迸”以比喻手法写出了琵琶声的美妙，“江空月静”以景结情，余味无穷。全词意境优美，描写细腻，是宋词中的佳作。"
  },
  "相思令·吴山青|林逋": {
    y: "吴山青翠，越山青翠，两岸的青山迎送着行人，谁知道离别的情意？\n你泪流满面，我泪流满面，罗带的同心结还没结成，江边的潮水已经平了。",
    s: "《相思令·吴山青》是林逋的名作，以民歌的笔调描写了离别的悲伤。“吴山青，越山青”以重叠的句式写出了江南的秀美，“罗带同心结未成”将爱情的遗憾写得真挚动人。全词语言朴素，情感真挚，是宋词中的佳作。"
  },
  "点绛唇·感兴|王禹偁": {
    y: "雨绵绵，云愁闷，江南依然称得上美丽。水村渔市，一缕孤烟细细升起。\n天边的大雁，远远看去行列相连。平生的事，此时凝神注视，谁能理解我凭栏的心意。",
    s: "《点绛唇·感兴》是王禹偁的名作，“天际征鸿，遥认行如缀”以大雁比喻自己的志向，“谁会凭栏意”将怀才不遇的感慨写得含蓄深沉。全词意境开阔，情感深沉，是宋初词的佳作。"
  },
  "酒泉子·长忆观潮|潘阆": {
    y: "常常回忆观潮的情景，满城的人争着到江上眺望。潮水来时，怀疑沧海全都空了，万面鼓声中。\n弄潮儿站在浪头上，手举红旗，红旗不被水打湿。离别后几次在梦中看到，梦醒还心有余悸。",
    s: "《酒泉子·长忆观潮》是潘阆的名作，描写了钱塘江大潮的壮观景象。“来疑沧海尽成空，万面鼓声中”以夸张手法写出了潮水的磅礴气势，“弄潮儿向涛头立，手把红旗旗不湿”写出了弄潮儿的英勇。全词气势磅礴，是宋词中少有的描写大潮的作品。"
  },
  "苏幕遮·碧云天|范仲淹": {
    y: "云天蓝碧，黄叶落满地，天边秋色与秋波相连，波上弥漫着空翠略带寒意的秋烟。远山沐浴着夕阳天空连接着江水。不解思乡之苦的芳草，一直延伸到夕阳之外的天际。\n默默思念故乡黯然神伤，缠人的羁旅愁思难以排遣，每天夜里除非是美梦才能留人入睡。当明月照射高楼时不要独自依倚，端起酒来洗涤愁肠，可是都化作相思的眼泪。",
    s: "《苏幕遮·碧云天》是范仲淹的代表作，“碧云天，黄叶地”是千古传诵的写景名句，王实甫《西厢记》中“碧云天，黄花地”即由此化用。“酒入愁肠，化作相思泪”将相思之情写得真挚动人。全词上阕写景，下阕抒情，意境开阔，情感深沉。"
  },
  "御街行·秋日怀旧|范仲淹": {
    y: "纷纷飘落的树叶，在香阶上堆积，夜色寂静，寒声细碎。珍珠帘子卷起，玉楼空寂，天色清淡，银河垂地。年年今夜，月光如白练，总是人在千里之外。\n愁肠已断，无法喝醉，酒还没到，先化成了泪。残灯明灭，枕头倾斜，尝尽了孤眠的滋味。这些事，眉间心上，没有办法回避。",
    s: "《御街行·秋日怀旧》是范仲淹的名作，“年年今夜，月华如练，长是人千里”以月光的永恒反衬人的分离，“都来此事，眉间心上，无计相回避”将相思之情写得真挚动人。全词意境凄清，情感深沉，是宋词中的佳作。"
  },
  "满庭芳·山抹微云|秦观": {
    y: "会稽山上，云朵淡淡的像是水墨画中轻抹上去的一半；越州城外，衰草连天，连绵无穷。城门楼上的号角声，时断时续。在北归的客船上，与歌妓举杯共饮，聊以话别。回首多少男女间情爱的往事，此刻已化作缕缕烟云散失而去。眼前夕阳西下，万点寒鸦点缀着天空，一弯流水围绕着孤村。\n悲伤之际又有柔情蜜意，心神恍惚下，解开腰间的系带，取下香囊。徒然赢得青楼中薄情的名声罢了。此一去，不知何时重逢？离别的泪水沾湿了衣襟与袖口。正是伤心悲情的时候，城已不见，万家灯火已起，天色已入黄昏。",
    s: "《满庭芳·山抹微云》是秦观的代表作，秦观也因此被称为“山抹微云君”。“山抹微云，天连衰草”以极简练的笔墨写出了秋日的苍茫，“斜阳外，寒鸦万点，流水绕孤村”化用隋炀帝诗句，意境优美。全词将离别之情写得真挚动人，是婉约词的杰作。"
  },
  "定风波·自春来|柳永": {
    y: "自从春天以来，绿叶红花都让人发愁，芳心对什么事都漫不经心。太阳升到花梢，黄莺穿过柳带，还压着香被躺着。肌肤消瘦，头发散乱，整天懒得梳妆。无奈。恨薄情郎一去，连个音信都没有。\n早知道这样，后悔当初没把他的马鞍锁住。在书房里，只给他纸和笔，管束着让他吟诗学习。永远相随，不要抛躲，闲着时拿着针线陪他坐着。和我在一起，免得年少时光白白度过。",
    s: "《定风波·自春来》是柳永的名作，以市井女子的口吻，描写了对丈夫的思念和对平凡夫妻生活的向往。“针线闲拈伴伊坐”写出了女子对温馨生活的渴望，相传晏殊曾以此词讥讽柳永。全词语言通俗，情感真挚，是柳永俚词的代表作。"
  },
  "戚氏·晚秋天|柳永": {
    y: "时值深秋，短促的细雨洒落在庭院栏干前。栏边的菊花稀疏，井边的梧桐叶零乱，惹起残烟。凄凉啊，远望江山关隘，飞云暗淡在夕阳之间。当年宋玉悲秋，对着此景临水登山。远道迢迢，行人凄楚，听厌了陇水潺潺。正是蝉在败叶中吟唱，蟋蟀在衰草中鸣叫，相互应和，喧闹不停。\n孤馆中，度日如年。风露渐渐变凉，悄悄到了更深夜阑。长天明净，银河清浅，皓月明媚。思绪绵绵。长夜对景，哪能忍受屈指暗想从前。没有功名没有利禄，在绮陌红楼中，往往一年年拖延。\n京城风光好，当年少的时候，朝朝暮暮宴饮欢乐。何况有狂放怪异的朋友，遇到对酒当歌就竞相留连。别来时光如梭，旧游似梦，烟水路程多么遥远。想名利，憔悴地长久萦绕牵绊。追念往事，空自愁容惨淡。漏箭移动，渐渐觉得微寒。渐渐呜咽，画角几声残响。对着闲窗，灯灭到天亮，抱着影子无眠。",
    s: "《戚氏》是柳永最长的词调，共212字，是柳永慢词的代表作。全词以凄清的秋景衬托游子的思乡之情和对往事的回忆，“念名利，憔悴长萦绊”道尽了为名利奔波的辛酸。全词结构宏大，情感深沉，是宋词中慢词的杰作。"
  },
  "夜半乐·冻云黯淡天气|柳永": {
    y: "寒云暗淡的天气，我乘一叶扁舟，乘兴离开江渚。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，山风忽然吹起，又听到商旅相互呼唤。船帆高高举起，画船轻快地驶过南浦。\n望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰杨掩映，岸边两两三三，是浣纱的游女。躲避行人，含羞笑着相互说话。\n到此因此思念，轻易抛弃了绣阁中的佳人，像浪萍一样难以停留。感叹后约的叮咛究竟有什么凭据。离怀凄惨，空自恨岁晚归期受阻。泪眼凝望，遥远的京城路。孤雁声远，长天暮色。",
    s: "《夜半乐》是柳永的长调名作，全词分三片，描写了舟行所见的江南景色和对佳人的思念。“败荷零落，衰杨掩映，岸边两两三三，浣纱游女”以细腻的笔触写出了江南水乡的生活气息，“断鸿声远长天暮”以景结情，余味无穷。全词意境优美，是柳永慢词的佳作。"
  },
  "玉楼春·春恨|晏殊": {
    y: "在绿杨芳草的长亭路上，年少的人轻易地抛下我离去。楼头的残梦被五更钟惊醒，花底的离愁像三月的雨。\n无情的人不像多情的人那样痛苦，一寸相思还能变成千万缕。天涯地角总有尽头，只有相思没有尽头。",
    s: "《玉楼春·春恨》是晏殊的名作，“无情不似多情苦，一寸还成千万缕”以对比手法写出了多情的痛苦，“天涯地角有穷时，只有相思无尽处”以夸张手法写出了相思的无穷无尽。全词情感真挚，语言清丽，是晏殊婉约词的代表作。"
  },
  "踏莎行·小径红稀|晏殊": {
    y: "小路边的红花日渐稀少，郊野却被萋萋芳草占遍，绿树成荫高楼台榭若隐若现。春风不懂得去管束杨花柳絮，让它们迷迷蒙蒙乱扑人面。\n翠绿的树叶里藏着黄莺，红色窗帘把燕子隔在外面，静静的炉香像游丝般袅袅升腾。醉酒后一场愁梦醒来时，夕阳正斜照着深深的庭院。",
    s: "《踏莎行·小径红稀》是晏殊的名作，“春风不解禁杨花，濛濛乱扑行人面”以拟人手法写春风，生动有趣，“一场愁梦酒醒时，斜阳却照深深院”以景结情，将闲愁写得含蓄深沉。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "清平乐·金风细细|晏殊": {
    y: "微微的秋风细细吹，梧桐叶一片片坠下。初尝绿酒人容易醉，在小窗下枕着浓睡。\n紫薇和朱槿花都残了，斜阳正照着栏杆。双燕将要归去的时节，银屏昨夜微微寒冷。",
    s: "《清平乐·金风细细》是晏殊的名作，以细腻的笔触描写了秋日的闲愁。“金风细细，叶叶梧桐坠”写出了秋日的萧瑟，“双燕欲归时节，银屏昨夜微寒”以双燕归巢反衬人的孤独。全词意境优美，情感细腻，是晏殊婉约词的佳作。"
  },
  "浣溪沙·小阁重帘有燕过|晏殊": {
    y: "小楼的重重帘幕间有燕子飞过，晚花的红瓣落在庭院的莎草上。曲折的栏杆影子映入凉波。\n一阵好风吹动翠幕，几回疏雨滴在圆荷上。酒醒人散，得到的愁更多。",
    s: "《浣溪沙·小阁重帘有燕过》是晏殊的名作，以细腻的笔触描写了暮春的景色和闲愁。“几回疏雨滴圆荷”以疏雨滴荷的细节，写出了环境的清幽，“酒醒人散得愁多”将闲愁写得含蓄深沉。全词意境优美，情感细腻。"
  },
  "诉衷情·眉意|欧阳修": {
    y: "清晨卷起帘幕，看到轻霜，呵着暖手试着画梅妆。都是因为自己有离恨，所以把眉毛画得像远山一样长。\n思念往事，惋惜流逝的芳华，容易成伤。想要唱歌先收敛，想要笑又皱眉，最让人断肠。",
    s: "《诉衷情·眉意》是欧阳修的名作，以女子画眉的细节，描写了离恨之深。“都缘自有离恨，故画作远山长”将离恨融入画眉的动作中，构思巧妙，“拟歌先敛，欲笑还颦，最断人肠”将女子的复杂心理写得生动传神。全词情感细腻，是婉约词的佳作。"
  },
  "南歌子·凤髻金泥带|欧阳修": {
    y: "凤凰发髻上束着金泥带，龙纹玉掌梳插在发间。走到窗下笑着相扶，爱问画眉深浅合不合时宜？\n依偎着人摆弄笔很久，初次试着描花。轻易耽误了绣花功夫，笑着问鸳鸯两个字怎么写？",
    s: "《南歌子·凤髻金泥带》是欧阳修的名作，以细腻的笔触描写了新婚夫妇的甜蜜生活。“爱道画眉深浅入时无”化用朱庆余诗句，“笑问鸳鸯两字怎生书”将少女的娇羞写得生动传神。全词语言明快，充满生活气息，是欧阳修词中少有的轻快之作。"
  },
  "临江仙·夜归临皋|苏轼": {
    y: "夜里在东坡饮酒，醉而复醒，醒了又饮。回来的时候仿佛已经三更。家里的童仆早已睡熟鼾声如雷鸣。反复敲门里面全不回应，只好独自倚着藜杖倾听江水奔流的吼声。\n长恨身在宦途，这身子已不是我自己所有。什么时候能忘却为功名利禄而奔竞钻营！夜深了，风停了，江面上的水波也平静下来。真想乘上小船从此消逝，在江河湖海中了却余生。",
    s: "《临江仙·夜归临皋》是苏轼被贬黄州时所作，“小舟从此逝，江海寄余生”表达了诗人对自由生活的向往，相传苏轼写此词后，“挂冠服江边，拏舟长啸去矣”，太守徐君猷闻之大惊，以为苏轼逃走。全词意境旷达，情感真挚，是苏轼豪放词的代表作。"
  },
  "西江月·平山堂|苏轼": {
    y: "我三次经过平山堂下，半生在弹指声中过去了。十年没见老仙翁欧阳修了，墙壁上他的字迹还龙蛇飞动。\n想要悼念文章太守欧阳修，仍然歌唱他的杨柳春风。不要说万事转头就空，没转头的时候也都是梦。",
    s: "《西江月·平山堂》是苏轼经过扬州平山堂时，为悼念恩师欧阳修而作。“壁上龙蛇飞动”写出了欧阳修书法的雄健，“休言万事转头空，未转头时皆梦”表达了对人生的深刻感悟。全词情感真挚，意境旷达，是苏轼婉约词的佳作。"
  },
  "阮郎归·初夏|苏轼": {
    y: "绿槐高柳上，新蝉的鸣叫声咽住了，和暖的南风刚刚入弦。碧纱窗下，水沉香的烟袅袅升起，下棋声惊醒了午睡。\n微雨过后，小荷叶翻卷，石榴花开得像要燃烧。玉盆中纤手拨弄清泉，水珠碎了又圆。",
    s: "《阮郎归·初夏》是苏轼描写初夏景色的词作，“榴花开欲然”以夸张手法写出了石榴花的鲜艳，“玉盆纤手弄清泉，琼珠碎却圆”以细腻的笔触写出了少女戏水的情景。全词色彩明丽，充满生活气息，是苏轼婉约词的佳作。"
  },
  "贺新郎·乳燕飞华屋|苏轼": {
    y: "小燕子飞落在华丽的房屋上，静悄悄无人，梧桐阴转到正午，傍晚凉爽，刚洗过澡。手拿着生丝白团扇，扇和手一时都像玉一样。渐渐困倦倚着，孤眠清熟。帘外谁来推绣户？枉自让人梦断瑶台曲。又却是，风敲竹子。\n石榴花半开，像红巾皱起，等浮花浪蕊都谢尽，陪伴你幽独。浓艳的一枝仔细看，芳心千重像束起来。又恐怕被秋风惊绿。如果等得你来到这里，花前对酒不忍触碰。和粉泪一起，两厢簌簌落下。",
    s: "《贺新郎·乳燕飞华屋》是苏轼的咏物词代表作，以石榴花比喻美人，“待浮花浪蕊都尽，伴君幽独”写出了石榴花的高洁，“共粉泪，两簌簌”将花与人融为一体，意境凄美。全词托物言志，情感深沉，是苏轼婉约词的杰作。"
  },
  "永遇乐·明月如霜|苏轼": {
    y: "明月如霜，好风如水，清景无限。曲折的港湾里鱼儿跳跃，圆圆的荷叶上露珠滚落，寂寞无人看见。三更鼓声响起，一片叶子铿然落下，黯黯的梦云被惊断。夜色茫茫，重寻无处，醒来后把小园走遍。\n天涯的倦客，山中的归路，望断了故园的视线。燕子楼空，佳人在哪里，空锁住楼中的燕子。古今如梦，何曾从梦中醒来，只有旧欢新怨。他日对着黄楼夜景，会为我长叹。",
    s: "《永遇乐·明月如霜》是苏轼夜宿燕子楼时所作，“燕子楼空，佳人何在，空锁楼中燕”是千古传诵的名句，将对历史的感慨写得含蓄深沉。全词意境凄清，情感深沉，是苏轼婉约词的杰作，晁补之称“燕子楼空，佳人何在，空锁楼中燕”为“三句说尽张建封事”。"
  },
  "洞仙歌·冰肌玉骨|苏轼": {
    y: "冰一样的肌肤，玉一般的身骨，自然是遍身清凉没有汗。宫殿里清风徐来幽香弥漫。绣帘被风吹开，一线月光把佳人窥探。佳人还没有入睡，她斜倚绣枕钗横发乱。\n起来携着她的纤纤素手，走到无声的庭院，时时看到稀疏的星星渡过银河。试问夜有多深？已经是三更时分，月光淡了，玉绳星低低转动。屈指算西风几时吹来，又不道流年在暗中偷偷变换。",
    s: "《洞仙歌·冰肌玉骨》是苏轼根据蜀主孟昶与花蕊夫人的故事改写的词作，“冰肌玉骨，自清凉无汗”写出了花蕊夫人的清丽，“但屈指西风几时来，又不道流年暗中偷换”将时光流逝的感慨写得含蓄深沉。全词意境优美，情感细腻，是苏轼婉约词的佳作。"
  },
  "天净沙·秋思|马致远": {
    y: "枯萎的藤蔓，苍老的古树，黄昏时归巢的乌鸦；小桥下溪水潺潺，旁边有几户人家；古老的道路上，萧瑟的西风里，走着一匹疲惫的瘦马。夕阳向西边落下，漂泊在外的游子，还远在天涯，愁肠寸断。",
    s: "《天净沙·秋思》被称为“秋思之祖”，仅用28个字，便勾勒出一幅苍凉的秋日羁旅图。全曲无一“愁”字，却字字含愁，情景交融，是元曲中最广为人知的作品，也是中国古典诗歌中描写乡愁的巅峰之作。"
  },
  "汉宫秋·第三折（节选）|马致远": {
    y: "呀！我面对着这辽阔荒凉的原野，草已经变黄，野兔早已遇上了秋霜。猎狗褪了毛变得苍灰，战士们扛起了缨枪，马驮着行装，车运着干粮，打猎的围场已经布置好。她伤心地辞别汉主，我携着手送她到河梁。她的随从进入了荒凉的远方，我的车驾返回咸阳。返回咸阳，经过宫墙；经过宫墙，绕着回廊；绕着回廊，靠近椒房；靠近椒房，月色昏黄；月色昏黄，夜里生凉；夜里生凉，寒蝉悲泣；寒蝉悲泣，绿纱窗下；绿纱窗下，怎能不思念！",
    s: "《汉宫秋》是马致远的杂剧代表作，写王昭君出塞的故事。这段曲词以顶真手法，从“返咸阳”到“不思量”，层层递进，将汉元帝回宫后对王昭君的思念写得缠绵悱恻，是元曲中最著名的唱段之一。"
  },
  "山坡羊·潼关怀古|张养浩": {
    y: "群山好像从四面八方聚集而来，黄河的波涛汹涌澎湃，像在发怒；潼关外有黄河，内有华山，地势十分险要。遥望古都长安，思绪起伏，久久不能平静。令人伤心的是，当年秦汉盛世的地方，万间宫殿都早已化作了尘土。国家兴盛的时候，受苦的是百姓；国家灭亡的时候，受苦的还是百姓。",
    s: "《山坡羊·潼关怀古》是元曲中怀古咏史的代表作，作者行经潼关，目睹历代王朝兴衰遗迹，发出了穿透历史的深沉慨叹。结尾“兴，百姓苦；亡，百姓苦”八字，道尽了封建时代百姓的命运，极具思想深度，在抖音等平台被广泛引用。"
  },
  "一枝花·不伏老（节选）|关汉卿": {
    y: "【尾】我是个蒸不烂、煮不熟、捶不扁、炒不爆、响当当的一粒铜豌豆，那些子弟们谁让你们钻进了他锄不断、砍不下、解不开、甩不掉、慢腾腾的千层锦套头？我玩的是梁园的明月，饮的是东京的美酒，赏的是洛阳的名花，攀的是章台的杨柳。我也会围棋、会踢球、会打猎、会插科打诨、会唱歌跳舞、会吹弹乐器、会唱曲、会吟诗、会双陆。你就是打掉了我的牙、打歪了我的嘴、打瘸了我的腿、打断了我的手，上天赐给我的这些毛病，我还是不肯罢休！除非是阎王亲自来召唤，神鬼亲自来勾魂。三魂归了地府，七魄丧了幽冥。天哪！那时候我才不往烟花路上走！",
    s: "《一枝花·不伏老》是关汉卿的自叙之作，以“铜豌豆”自喻，展现了自己坚韧不屈、放荡不羁的性格。“蒸不烂、煮不熟、捶不匾、炒不爆”的排比，气势磅礴，将关汉卿的叛逆精神和顽强生命力写得淋漓尽致，是元曲中最具个性的作品之一。"
  },
  "窦娥冤·第三折（节选）|关汉卿": {
    y: "【正宫·端正好】无缘无故犯了王法，没有提防遭受刑罚，叫一声屈动地惊天。顷刻间游魂先赴了阎王殿，怎么不把天地也深深地埋怨。\n【滚绣球】有日月早晚悬挂，有鬼神掌着生死大权。天地啊，只应该把清浊分辨，可怎么混淆了盗跖和颜渊？行善的受贫穷又命短，作恶的享富贵又寿长。天地啊，做得个怕硬欺软，却原来也这般顺水推船！地啊，你不分好歹算什么地？天啊，你错判贤愚枉做天！哎，只落得两泪涟涟。",
    s: "《窦娥冤》是关汉卿的代表作，也是中国古代悲剧的巅峰之作。这段唱词是窦娥在法场上对天地的控诉，“地也，你不分好歹何为地？天也，你错勘贤愚枉做天！”以震天撼地的呐喊，揭露了封建社会的黑暗与不公，是元曲中最具反抗精神的唱段。"
  },
  "天净沙·春|白朴": {
    y: "桃红柳绿的春山，煦暖的阳光照耀，和柔的东风吹拂，楼阁上卷起帘拢，凭栏远望。院中杨柳依依，秋千轻轻摇动。黄莺在歌唱，春燕在飞舞，小桥下流水潺潺，柳絮飞花飘扬。",
    s: "《天净沙·春》是白朴的名作，与马致远《天净沙·秋思》齐名。全曲以白描手法描绘了春日的美好景象，“春山暖日和风”“啼莺舞燕，小桥流水飞红”，色彩明丽，生机盎然，与《秋思》的苍凉形成鲜明对比。"
  },
  "墙头马上·第一折（节选）|白朴": {
    y: "【后庭花】不要说姻缘难得，这是情意坚定。他用眉眼传递心事，我把心肠写进短笺。我若得见天颜，将他好言相劝，他是宰相家的贵公子，我是总管的女婵娟。\n【柳叶儿】呀，我只怕你情意淡薄，我只怕你日久心变，我只怕你另寻了姻缘。我只怕你等闲间把人轻视，我只怕你话里把人哄骗，我只怕你口是心非把人怠慢。",
    s: "《墙头马上》是白朴的爱情喜剧代表作，与《西厢记》《拜月亭》《倩女离魂》并称元曲四大爱情剧。这段唱词以女子的口吻，表达了对爱情的渴望和对未来的担忧，心理描写细腻生动，是元曲爱情戏的经典片段。"
  },
  "高祖还乡（节选）|睢景臣": {
    y: "【般涉调·哨遍】社长挨家挨户通知，只要有差使都不许推脱。这差使不寻常，一边要交纳草料，一边又要出夫役，都要应付。又说是车驾，都说是銮舆，今天要回故乡。王乡老拿着瓦台盘，赵忙郎抱着酒葫芦。新刷的头巾，刚浆过的绸衫，真是装模作样的大户。\n【耍孩儿】瞎王留领着一伙怪男女，乱踢蹬吹笛擂鼓。看见一队人马到庄门，当头几面旗舒展。一面旗白圈套着个迎霜兔，一面旗红圈打着个毕月乌。一面旗鸡学舞，一面旗狗生双翅，一面旗蛇缠葫芦。",
    s: "《高祖还乡》是睢景臣的代表作，以一个农民的视角，描写了汉高祖刘邦还乡的场面。全曲以幽默讽刺的笔法，将皇帝的仪仗描写得荒诞可笑，撕下了帝王的神圣面纱，表现了对封建皇权的蔑视，是元曲中最具讽刺性的作品之一。"
  },
  "醉太平·堂堂大元|无名氏": {
    y: "堂堂大元朝，奸臣专权。开河变钞是祸乱的根源，惹起了红巾军万千。官法混乱，刑法严苛，百姓怨恨。人吃人，钞买钞，何曾见过。贼做官，官做贼，愚贤不分，真是可悲可怜！",
    s: "《醉太平·堂堂大元》是元代末年的民间散曲，以尖锐泼辣的语言揭露了元末社会的黑暗：奸佞专权、官法泛滥、刑法严苛、人吃人、贼做官，是对元末社会现实的真实写照，也是元曲中最具批判精神的作品之一。"
  },
  "卖花声·怀古|张可久": {
    y: "阿房宫里罗袖翻飞，金谷园中玉楼高耸，隋堤上的古柳系着龙舟。往事不堪回首，东风又吹来了，野花开在暮春时候。",
    s: "《卖花声·怀古》是张可久的代表作，以阿房宫、金谷园、隋堤三个历史典故，抒发了对历史兴亡的感慨。“不堪回首，东风还又，野花开暮春时候”以景结情，将历史的沧桑与自然的永恒对比，含蓄深沉，是元曲中怀古的佳作。"
  },
  "人月圆·山中书事|张可久": {
    y: "千古以来的兴亡繁华，都像一场梦，诗人的眼睛已厌倦了天涯漂泊。孔林的乔木，吴宫的蔓草，楚庙的寒鸦，都在诉说着历史的沧桑。几间茅舍，藏书万卷，终老在乡村人家。山中做什么事？用松花酿酒，用春水煎茶。",
    s: "《人月圆·山中书事》是张可久的代表作，表达了对历史兴亡的感慨和对隐居生活的向往。“松花酿酒，春水煎茶”以极简练的笔墨写出了隐居生活的闲适与美好，全曲意境清雅，语言凝练，是元曲中小令的精品。"
  },
  "清江引·秋怀|张可久": {
    y: "西风送来家书，家在万里之外，问我什么时候回去？大雁在红叶满天的秋天啼叫，人在黄花满地的地方醉倒，芭蕉叶上的雨声，飘进了秋日的梦里。",
    s: "《清江引·秋怀》是张可久的名作，以西风、家书、雁啼、红叶、黄花、芭蕉、雨声等意象，营造出凄清的秋日意境，表达了游子的思乡之情。全曲语言凝练，意境优美，是元曲中写秋的佳作。"
  },
  "寿阳曲·远浦归帆|马致远": {
    y: "夕阳西下，酒旗悠闲地飘着，两三只船还没有靠岸。落花飘在水上，带着香气，茅舍笼罩在暮色中，断桥头上卖鱼的人已经散去。",
    s: "《寿阳曲·远浦归帆》是马致远《潇湘八景》组曲之一，以极简练的笔墨描绘了一幅渔村晚景图。“夕阳下，酒旆闲”“断桥头卖鱼人散”，画面宁静优美，充满生活气息，是元曲中写景的佳作。"
  },
  "四块玉·别情|关汉卿": {
    y: "自从送别之后，心中难舍，这一点相思什么时候才能断绝？凭栏远望，衣袖拂过如雪的杨花。溪水又斜，青山又遮，人已经去了！",
    s: "《四块玉·别情》是关汉卿的小令名作，以女子的口吻写送别后的相思。“凭阑袖拂杨花雪”以动作写思念，“溪又斜，山又遮，人去也”以景结情，将离别的惆怅写得含蓄深沉。全曲语言朴素，情感真挚。"
  },
  "沉醉东风·渔夫|白朴": {
    y: "黄芦岸边白苹渡口，绿柳堤上红蓼滩头。虽然没有刎颈之交，却有忘机之友。秋江上点染着白鹭沙鸥。傲视人间的万户侯，我是个不识字的烟波钓叟。",
    s: "《沉醉东风·渔夫》是白朴的名作，以渔夫的生活表达了对自由的向往和对权贵的蔑视。“傲杀人间万户侯，不识字烟波钓叟”将渔夫的自由与权贵的束缚对比，表达了不慕荣利、追求自由的人生态度，是元曲中隐逸题材的佳作。"
  },
  "鹦鹉曲·渔父|冯子振": {
    y: "我家住在鹦鹉洲边，是个不识字的渔父。浪花中一叶扁舟，在江南烟雨中酣睡。醒来时满眼青山，抖抖绿蓑衣归去。算从前错怨了天公，原来也有安排我的地方。",
    s: "《鹦鹉曲·渔父》是冯子振的代表作，以渔父的生活表达了随遇而安的人生态度。“浪花中一叶扁舟，睡煞江南烟雨”意境优美，“算从前错怨天公，甚也有安排我处”充满哲理，是元曲中隐逸题材的名篇。"
  },
  "小桃红·秋江|倪瓒": {
    y: "一江秋水笼罩着淡淡的寒烟，水面明净如白练。眼底的离愁如几行飞雁。雪后初晴，绿苹红蓼参差可见。唱着吴歌荡桨，一声哀怨，惊起了安眠的白鸥。",
    s: "《小桃红·秋江》是倪瓒的名作，倪瓒是元代著名画家，此曲以画家的笔触描绘了秋江的景色，“一江秋水澹寒烟，水影明如练”画面感极强，“吴歌荡桨，一声哀怨，惊起白鸥眠”以动写静，意境悠远，是元曲中写景的精品。"
  },
  "登徒子好色赋（节选）|宋玉": {
    y: "大夫登徒子在楚王身边侍奉，说宋玉的坏话：“宋玉这个人，相貌娴雅英俊，口才很好，又生性好色。希望大王不要让他出入后宫。”\n楚王把登徒子的话告诉了宋玉。宋玉说：“相貌娴雅英俊，是上天赐予的；口才很好，是从老师那里学来的；至于好色，臣下没有这回事。”\n楚王说：“你不好色，有什么说法吗？有道理就留下，没有道理就退下。”\n宋玉说：“天下的美女，没有比得上楚国的；楚国的美女，没有比得上我家乡的；我家乡的美女，没有比得上我东边邻居家的女儿。东边邻居家的女儿，增加一分就太高，减少一分就太矮；搽粉就太白，抹胭脂就太红；眉毛像翠鸟的羽毛，肌肤像白雪；腰像一束素绢，牙齿像含着贝壳；嫣然一笑，就能迷惑阳城、下蔡的公子。然而这个女子爬墙偷看我三年，我至今没有答应她。登徒子就不是这样：他的妻子头发蓬乱，耳朵卷曲，嘴唇外翻，牙齿稀疏，走路歪歪扭扭，还长着疥疮和痔疮。登徒子却很喜欢她，让她生了五个孩子。大王仔细考察一下，谁是好色的人呢？”",
    s: "《登徒子好色赋》是宋玉的代表作，以登徒子与宋玉的对比，讽刺了以貌取人的偏见。“增之一分则太长，减之一分则太短”成为描写美女的千古名句，“登徒子”也成为好色之徒的代名词。全赋语言优美，比喻生动，是先秦赋的代表作。"
  },
  "风赋（节选）|宋玉": {
    y: "楚襄王在兰台宫游玩，宋玉、景差在旁侍奉。有一阵风飒飒吹来，楚王就敞开衣襟迎着风，说：“这风真痛快啊！这是我和百姓共同享受的吗？”\n宋玉回答说：“这只是大王您的风罢了，百姓怎么能和您共同享受呢！”\n楚王说：“风，是天地间的气，普遍畅通地吹来，不分贵贱高低都吹到。现在你独独认为是我的风，难道有什么说法吗？”\n宋玉回答说：“我从老师那里听说：枳树弯曲的枝桠会招来鸟筑巢，空穴会引来风。它所依托的环境是这样，那么风的气势就不同了。”\n楚王说：“风，最初是从哪里产生的呢？”\n宋玉回答说：“风从大地上产生，从青苹草的末梢兴起。渐渐进入山谷，在山洞口猛烈怒吼。沿着泰山的山坳，在松柏之下飞舞。飘忽澎湃，激荡如烈火怒吼。轰轰如雷声，回旋交错。吹动石头，折断树木，冲击森林。等到它将要衰弱的时候，就四面分散，穿洞动门，光彩灿烂，离散转移。所以那清凉的雄风，就飘举升降，越过高高的城墙，进入深深的宫殿。吹开花叶散发香气，在桂树椒树之间徘徊，在急流之上翱翔。将冲击荷花，掠过蕙草，分开秦衡，掠过新夷，覆盖初生的杨树，回旋冲击，使众芳萧条。然后在庭院中徜徉，向北进入玉堂，穿过罗帐，经过深邃的内室，这才成为大王的风。所以这风吹到人的身上，直让人感到凄凉寒冷，清凉得让人叹息。清清凉凉，能治好病，解除酒醉，使人耳聪目明，身体安宁。这就是所说的大王的雄风。”",
    s: "《风赋》是宋玉的代表作，以“雄风”与“雌风”的对比，讽刺了统治者与百姓生活的天壤之别。“风起于青苹之末”成为千古名句，比喻事物的发展有一个从小到大的过程。全赋想象丰富，描写细腻，是先秦赋的杰作。"
  },
  "子虚赋（节选）|司马相如": {
    y: "楚王派子虚出使齐国，齐王征发全部车马，和使者一起外出打猎。打猎结束后，子虚去拜访乌有先生，亡是公也在座。坐定后，乌有先生问道：“今天打猎快乐吗？”子虚说：“快乐。”“收获多吗？”子虚说：“少。”“那为什么快乐呢？”子虚回答说：“我快乐是因为齐王想向我夸耀他的车骑众多，而我却用云梦泽的事来回答他。”乌有先生说：“可以说给我听听吗？”\n子虚说：“可以。齐王驾着千辆马车，挑选了万名骑兵，在海边打猎。士卒布满沼泽，罗网布满山丘，掩捕野兔，车轮碾死鹿，射杀麋鹿，抓住麟。在盐滩上奔驰，切割鲜肉，血染车轮。射中捕获很多，骄傲地自夸功劳。回头对我说：'楚国也有像这样富饶快乐的平原广泽游猎之地吗？楚王打猎和我比怎么样？'我下车回答说：'我是楚国的鄙陋之人，有幸在宫中宿卫十多年，时常跟随出游，在后宫花园游玩，看了一些景色，但还没有全部看完，又怎么能说宫外的大泽呢！'齐王说：'即使这样，你就大致说说你所听到看到的吧。'",
    s: "《子虚赋》是司马相如的代表作，与《上林赋》并称，是汉大赋的典范。全赋以子虚、乌有先生、亡是公三人的对话展开，极力铺陈楚国云梦泽的富饶和齐王打猎的盛况，规模宏大，辞藻华丽，奠定了汉大赋的体制，对后世影响深远。"
  },
  "上林赋（节选）|司马相如": {
    y: "亡是公笑着说：“楚国错了，齐国也不算对。让诸侯纳贡，不是为了财物，而是让他们陈述职守。划定疆界，不是为了防守，而是为了禁止放纵。现在齐国作为东方的藩国，却对外私通肃慎，离开本国，越过边界，渡海打猎，这在道义上本来就不可以。而且你们两位的议论，不致力于阐明君臣的道义，端正诸侯的礼仪，只是争着谈论游戏的快乐，苑囿的广大，想以奢侈争胜负，以荒淫比高低，这不能用来扬名传誉，反而足以贬低君主、损害自己。”\n“况且齐楚的事，又哪里值得称道呢！你们没有见过那巨大壮丽的景象，难道没听说过天子的上林苑吗？左边是苍梧，右边是西极。丹水经过它的南边，紫渊穿过它的北边。灞水浐水始终流在苑中，泾水渭水出入其中；酆水镐水潦水潏水，曲折蜿蜒，流经苑内。浩浩荡荡八条河流分流，方向不同，形态各异。东西南北，奔驰往来，从椒丘的阙口流出，在沙洲的水边行进，经过桂林之中，越过广阔的原野。水势浩荡，顺着山坡而下，奔赴狭窄的峡口，撞击巨石，冲击沙堆，沸腾暴怒，汹涌澎湃。水势湍急，相迫相击，横流回旋，翻腾飞溅，水势浩大。波浪如云般回旋，水流曲折纠缠。后浪越过前浪奔向低洼，水石相击流下浅滩。冲击岩石，拍打堤岸，奔腾飞扬。流向小洲，注入深谷，水声潺潺，水势深沉，轰鸣作响，水势汹涌，如鼎沸腾。波浪奔驰，泡沫跳跃，水流迅疾。悠远长流，寂静无声，安然长归。然后水势浩大，缓缓回旋，波光粼粼，向东注入太湖，溢满池塘。”",
    s: "《上林赋》是司马相如的代表作，与《子虚赋》连为一体，是汉大赋的巅峰之作。全赋以亡是公之口，极力铺陈天子上林苑的壮丽和天子打猎的盛况，规模宏大，辞藻华丽，气势磅礴，最后归于节俭，体现了“劝百讽一”的赋颂传统，对后世辞赋影响极大。"
  },
  "归田赋|张衡": {
    y: "在京城游历已久，没有高明的谋略辅佐时政。只是临河羡鱼，等待黄河水清却遥遥无期。感慨蔡泽的慷慨，跟随唐举决断疑惑。实在是天道幽微不明，追随渔父一同嬉戏。超脱尘世远去，与世事永远辞别。\n于是在美好的仲春二月，气候温和，天气清明；平原低地草木茂盛，百草繁荣。雎鸠展翅，黄鹂哀鸣；交颈上下翻飞，关关嘤嘤和鸣。在这里逍遥自在，姑且愉悦心情。\n于是在大泽边龙吟，在山丘上虎啸。仰射飞鸟，俯钓长流。鸟中箭而死，鱼贪饵吞钩。射落云间的飞鸟，钓起深渊中的鱼。\n这时太阳西斜，接着月亮升起。极尽游乐的至乐，虽然到了傍晚也忘记了疲劳。有感于老子的遗诫，将驾车回到茅屋。弹奏五弦琴的妙曲，诵读周公孔子的图书。挥笔作文，陈述三皇的法度。只要纵情于物外，哪里知道荣辱的所在。",
    s: "《归田赋》是张衡的代表作，也是中国文学史上第一篇描写田园隐居乐趣的赋作。全赋篇幅短小，语言清丽，一改汉大赋的铺张扬厉，开创了抒情小赋的先河，对后世陶渊明的田园诗产生了深远影响。"
  },
  "登楼赋|王粲": {
    y: "登上这座楼向四面眺望啊，姑且借闲暇的日子消解忧愁。看这座楼所处的位置啊，确实明亮宽敞少有匹敌。旁临清澈漳水的河口啊，倚靠曲折沮水的长洲。背后是高而平的广阔陆地啊，面前是低洼湿地的肥沃水流。北边直到陶牧，西边连接昭丘。花果遮蔽原野，黍稷长满田畴。虽然确实美好却不是我的故乡啊，又怎么值得稍稍停留。\n遭遇乱世而迁徙流亡啊，漫漫超过十二年直到如今。情意眷恋而思归啊，谁能承受这样的忧思？靠着栏杆遥望啊，迎着北风敞开衣襟。平原遥远极目远望啊，被荆山的高峰遮蔽。道路曲折而漫长啊，河水荡漾而渡口深。悲伤故乡被阻隔啊，眼泪纵横落下而不能禁止。从前孔子在陈国啊，有“归欤”的叹息。钟仪被囚禁而奏楚乐啊，庄舄显贵而仍越吟。人的感情都同样怀念故土啊，难道会因穷困显达而改变心意！\n想到时光流逝啊，等待黄河水清却没有尽头。希望王道统一太平啊，凭借大道施展才力。害怕像匏瓜那样白白悬挂啊，担心井已淘清却无人饮用。徘徊漫步啊，太阳忽然将要西沉。风声萧瑟四起啊，天色惨淡无光。野兽惊慌回顾寻找群伴啊，鸟儿相鸣而展翅。原野寂静无人啊，征夫行走不停。心中凄怆感慨啊，情意悲伤哀痛。沿着台阶走下楼啊，怨气交结充满胸中。到了半夜还不能入睡啊，惆怅徘徊翻来覆去。",
    s: "《登楼赋》是王粲的代表作，也是建安文学的名篇。王粲避难荆州，登当阳城楼，写下此赋，抒发了思乡之情和怀才不遇的感慨。“虽信美而非吾土兮，曾何足以少留”“人情同于怀土兮，岂穷达而异心”都是千古传诵的名句。全赋抒情真挚，语言清丽，是魏晋抒情小赋的典范。"
  },
  "洛神赋（节选）|曹植": {
    y: "黄初三年，我到京师朝见，回来时渡过洛水。古人说，这洛水的神，名叫宓妃。有感于宋玉对楚王说的神女之事，于是作了这篇赋。辞说：\n我从京城出发，回到东方的藩国。离开伊阙，越过轘辕，经过通谷，登上景山。太阳已经西斜，车困马乏。于是在长满杜蘅的岸边停车，在种满芝草的田里喂马，在阳林漫步，放眼眺望洛川。这时精神恍惚，忽然思绪飘散。低头没有看清，抬头却看到奇异的景象，看见一位美人，在山崖边。于是拉着车夫告诉他说：“你看见那个人了吗？那是谁啊？这样美丽！”车夫回答说：“我听说河洛的神，名叫宓妃。那么君王所见的，莫非就是她吗？她的样子怎样？我想听听。”\n我告诉他说：“她的形态，轻盈如惊飞的鸿雁，婉曲如游动的蛟龙。容光如秋菊般灿烂，风华如春松般茂盛。隐隐约约如轻云遮住月亮，飘飘摇摇如流风吹起回旋的雪花。远远望去，皎洁如朝阳升起在朝霞中；走近细看，鲜明如荷花出清水。肥瘦适中，高矮合度。肩膀如削成一般，腰肢如一束素绢。脖颈修长，洁白的肌肤显露。不施芳香，不涂脂粉。发髻高耸如云，眉毛修长弯曲。红唇鲜明，皓齿洁白，明亮的眼睛善于顾盼，面颊有美丽的酒窝。姿态瑰丽艳逸，仪态文静娴雅。柔情绰约，言语娇媚。服饰奇特举世无双，骨相应图。披着璀璨的罗衣，戴着华美的瑶碧玉佩。戴着金翠首饰，缀着明珠照耀身躯。穿着远游的花鞋，拖着薄雾般的轻裙。幽兰的芳香微微散发，在山边徘徊漫步。”",
    s: "《洛神赋》是曹植的代表作，以浪漫主义的笔法描写了人神相恋的故事。“翩若惊鸿，婉若游龙”“仿佛兮若轻云之蔽月，飘飖兮若流风之回雪”成为描写美女的千古名句。全赋想象瑰丽，辞藻华美，情感真挚，是中国文学史上最著名的赋作之一，也是后世绘画、戏曲的重要题材。"
  },
  "酒德颂|刘伶": {
    y: "有一位大人先生，把天地当作一天，把万年当作片刻，把日月当作门窗，把八方荒远之地当作庭院道路。行走没有车辙痕迹，居住没有房屋，以天为幕，以地为席，随心所欲。停下来就拿着酒杯，走动就提着酒壶，只致力于饮酒，哪里知道其他的事？\n有尊贵的公子和士大夫，听到我的名声，议论我的作为。于是挥袖挽襟，怒目咬牙，陈说礼法，是非纷起。先生这时正捧着酒坛接着酒槽，含着酒杯漱口酒，抖动胡须，箕踞而坐，枕着酒曲，垫着酒糟，无思无虑，其乐陶陶。昏然醉倒，豁然醒来。静听听不到雷霆的声音，细看看不见泰山的形状，不觉得寒暑侵入肌肤，利欲触动感情。俯视万物，纷纷扰扰，像江汉水中漂浮的浮萍；两位贵人侍立在旁，就像蜾蠃和螟蛉一样。",
    s: "《酒德颂》是刘伶的代表作，也是魏晋名士风度的集中体现。全文以大人先生的形象，表达了蔑视礼法、纵酒放达的人生态度，“幕天席地，纵意所如”成为千古名句。文章短小精悍，气势磅礴，是魏晋文学的名篇。"
  },
  "闲情赋（节选）|陶渊明": {
    y: "那是何等瑰丽超逸的美好姿容，举世无双，秀出群伦。展现出倾城的艳丽姿色，期望有美德流传。佩戴鸣玉来比洁白，与幽兰比芬芳。在世俗中保持淡泊柔情，怀抱高雅之志上凌云天。悲叹晨曦容易西斜，感慨人生长久辛劳。同样都在百年后穷尽，为何欢乐少而忧愁多。撩起红色帷幕端坐，弹奏清瑟自娱。纤细的手指传送余韵，洁白的衣袖挥动缤纷。美丽的眼睛转动流盼，含着言笑难以分辨。\n曲调将到一半，日影落到西窗。悲风叩击树林，白云依傍山峦。仰望天路，俯身催促琴弦。神态妩媚，举止安详妍丽。清音激越感动了我，希望促膝交谈。想亲自前往结下誓言，又怕冒犯礼法成为过错。等待凤鸟传话，又怕别人抢在我前面。心意惶惑不安，魂魄片刻之间九次变迁。\n愿做衣服的领子，承受美发的余香；悲叹罗衣夜里脱下，怨恨秋夜漫长。愿做裙子的腰带，束住窈窕的纤腰；嗟叹温凉变化，有时脱旧换新。愿做头发的油脂，涂抹在垂肩的黑发上；悲叹佳人多次洗发，随白水煎熬干枯。愿做眉毛的黛色，随着顾盼而舒展；悲叹脂粉求鲜，有时在华妆中被毁。愿做蒲草席，在三秋安托柔弱的身体；悲叹花纹褥子取代，要等一年才被用。愿做丝线做鞋，附着白足周旋；悲叹行止有节，白白被抛弃在床前。愿做白天的影子，常依身形或西或东；悲叹高树多荫，有时不能相随。愿做夜晚的蜡烛，在两楹之间照亮玉容；悲叹太阳升起，忽然灭影藏光。愿做竹子做扇，在柔握中含着清风；悲叹白露晨降，看着襟袖而遥远。愿做树木做桐，做膝上的鸣琴；悲叹乐极哀来，最终推开我而停止弹奏。",
    s: "《闲情赋》是陶渊明唯一的爱情赋作，“十愿”（愿在衣而为领、愿在裳而为带……）以奇特的想象，表达了对美人的深情爱慕，是中国文学史上最著名的爱情描写之一。全赋辞藻华美，情感真挚，与陶渊明平时平淡自然的风格形成鲜明对比，萧统评价为“白璧微瑕”，实则是陶渊明才情的另一种展现。"
  },
  "芜城赋|鲍照": {
    y: "广陵平原连绵起伏，向南可达苍梧、涨海，向北可到紫塞、雁门。以漕渠为舵，以昆岗为轴。是重关复江的险要之地，四方通达的要道。当它全盛的时候，车轴相碰，人肩相摩，房屋遍地，歌声震天。盐田滋生财富，铜山开采利益，财力雄厚，兵马精良。所以能超越秦法，超过周令，修筑高墙，挖掘深沟，图谋永世的好运。因此板筑城墙的盛状，建造望楼的辛勤，高度超过五岳，广度超过三坟，险峻如断岸，高耸如长云。用磁石制作防御，用红泥涂抹飞文。看这城防的坚固，将万年一君。经历三代，五百多年，竟然瓜剖豆分。\n井边长满青苔，道路缠绕野葛。庭院中遍布毒蛇，台阶上獐鼠相斗。木魅山鬼，野鼠城狐，在风雨中嚎叫，黄昏出现，清晨奔走。饥鹰磨嘴，寒鸥吓雏。潜伏猛虎，吸血食肉。崩倒的榛树堵塞道路，古老的大道险峻。白杨早落，寒草先衰。霜气凛冽，风威肃杀。孤蓬自飞，惊沙乱卷。灌木茫茫无际，草丛纷杂相依。城壕已经填平，城楼已经坍塌。直视千里之外，只见黄尘飞扬。凝神静听，心伤已碎。\n至于雕花的门、绣花的帐，歌堂舞阁的基址；玉池碧树，射猎垂钓的馆舍；吴蔡齐秦的音乐，鱼龙爵马的玩物；都香消烟灭，光沉响绝。东都的美女，南国的丽人，蕙心纨质，玉貌红唇，无不埋魂于幽石，委骨于穷尘。哪里还会记得同辇的欢乐，离宫的苦辛呢？\n天道如何，抱恨的人多。拿琴奏曲，作芜城之歌。歌道：边风急啊城上寒，井径灭啊丘垄残。千年啊万代，同归于尽啊又何言。",
    s: "《芜城赋》是鲍照的代表作，描写了广陵城（今扬州）从繁华到荒芜的巨变。“千龄兮万代，共尽兮何言”以苍凉的笔调抒发了对历史兴亡的感慨。全赋对比强烈，辞藻瑰丽，情感深沉，是南朝抒情小赋的巅峰之作。"
  },
  "别赋（节选）|江淹": {
    y: "最让人黯然销魂的，只有离别而已！何况秦吴是相隔绝远的国家，燕宋又相隔千里。有时春苔才开始生长，忽然秋风又暂时吹起。因此游子肠断，百感凄恻。风声萧萧而异响，云色漫漫而奇色。船在水边停滞，车在山侧徘徊。船桨迟缓怎能前进，马寒鸣不停。掩住金杯谁能饮，横放琴柱泪沾轼。在家的人愁卧，恍然若失。日影下墙而光彩沉，月亮上楼而飞光。见红兰承受露水，望青楸遭受寒霜。沿着高柱空掩门，抚摸锦幕空凄凉。知道离梦徘徊，料想别魂飞扬。\n所以离别虽是一种情绪，事情却有万种。至于龙马银鞍，朱车绣轴，在东都设帐饯饮，在金谷送客。琴羽奏响啊箫鼓陈列，燕赵悲歌啊美人伤心，珠玉啊艳于暮秋，罗绮啊娇于初春。惊得驷马仰头嚼食，耸动深渊鱼的红鳞。到分手时含泪，感到寂寞而伤神。\n又有剑客感恩，少年报士，像聂政刺韩相，豫让伏赵厕，专诸刺吴王，荆轲在燕市。割舍慈爱，离开邦国乡里，洒泪诀别，擦血相视。驱征马不回头，只见行尘时时扬起。正是因一剑感恩，不是为了买名于黄泉。金石震动而色变，骨肉悲痛而心死。",
    s: "《别赋》是江淹的代表作，与《恨赋》并称。“黯然销魂者，唯别而已矣”开篇便点明主旨，成为千古传诵的名句。全赋铺写了各种类型的离别，辞藻华丽，情感真挚，是南朝骈赋的典范之作，对后世影响深远。"
  },
  "滕王阁序（节选）|王勃": {
    y: "时当九月，正值深秋。雨后的积水已经消尽，寒冷的潭水十分清澈；烟雾凝聚，傍晚的山峦呈现出一片紫色。我们在高高的山路上驾车前行，到崇山峻岭中寻访风景。来到滕王营建的长洲上，看见了这座仙人般的楼阁。层叠的山峦耸起一片苍翠，向上直插云霄；凌空的楼阁丹漆流动，往下看，深不见底。白鹤、野鸭栖息的沙洲，极尽岛屿曲折回环的景致；桂木、兰木修建的宫殿，依着山峦的起伏排列。\n推开雕花的阁门，俯视华美的屋脊，辽阔的山川平原尽收眼底，迂回的江河湖泽令人惊叹。房屋遍地，都是钟鸣鼎食的富贵人家；船只停满渡口，都是青雀、黄龙造型的大船。乌云消散，雨过天晴，阳光普照，天空明朗。落日的晚霞与孤单的野鸭一同飞翔，秋天的江水和辽阔的天空浑然一色。傍晚渔舟中传来歌声，响彻彭蠡湖畔；雁群被寒气惊扰，叫声消失在衡阳的水边。\n胸怀顿时舒畅，超逸的兴致迅速飞扬。排箫声起，清风徐来，柔歌缭绕，白云停飞。睢园的绿竹，豪气胜过陶渊明的酒樽；邺水的朱华，光彩照过谢灵运的诗笔。四种美好都具备，两种难得也齐全。极目远望长空，在假日尽情游乐。天高地远，感到宇宙无穷；兴尽悲来，知道盛衰有定。远望长安在日下，遥看吴会在云间。地势尽而南海深，天柱高而北极远。关山难越，谁为迷路的人悲伤？萍水相逢，都是他乡之客。思念宫门却不得见，等待宣室召见又在哪一年？\n唉！时运不齐，命运多舛。冯唐容易衰老，李广难得封侯。贾谊被贬到长沙，不是没有圣明的君主；梁鸿逃到海边，难道不是政治清明的时代？所依赖的是君子看到征兆，达人知道命运。老当益壮，怎能改变白发之心？穷且益坚，不堕青云之志。喝贪泉的水更觉清爽，处干涸的车辙依然欢乐。北海虽远，乘风可到；早晨虽过，傍晚不晚。孟尝高洁，空有报国之情；阮籍猖狂，岂能学他穷途之哭！",
    s: "《滕王阁序》是骈文的巅峰之作，也是王勃的千古绝唱。全文辞藻华丽，对仗工整，意境开阔，“落霞与孤鹜齐飞，秋水共长天一色”更是千古名句。“老当益壮，宁移白首之心？穷且益坚，不坠青云之志”激励了无数身处逆境的人。全文是中国古代赋体文学最具代表性的作品。"
  },
  "前赤壁赋|苏轼": {
    y: "壬戌年的秋天，七月十六日，我和客人乘船在赤壁之下游玩。清风缓缓吹来，水面波澜不惊。我举起酒杯劝客人同饮，吟诵《诗经》中关于明月的诗篇。不一会儿，月亮从东山上升起，在斗宿和牛宿之间徘徊。白茫茫的水汽笼罩江面，水光与天空连成一片。我们任凭小船像一片苇叶般飘荡，越过茫茫万顷的江面。浩浩荡荡的，好像凌空驾风而行，不知道要停在哪里；飘飘然的，好像脱离了尘世，无牵无挂，变成了神仙飞上了天。\n这时候喝酒喝得高兴起来，用手叩击船舷应声而歌。歌词说：“桂木做的棹啊兰木做的桨，拍击着清澈的江水啊，在月光浮动的江面逆流而上。我的心怀悠远啊，遥望美人啊在天的一方。”客人中有吹洞箫的，按着歌声伴奏。那箫声呜呜咽咽，像怨恨又像思慕，像哭泣又像倾诉，尾声婉转悠长，像不断的细丝。能使深谷中的蛟龙起舞，能使孤舟上的寡妇哭泣。\n我的神色变得忧愁，整理好衣襟端坐，问客人说：“箫声为什么这样悲凉呢？”客人说：“'月明星稀，乌鹊南飞'，这不是曹孟德的诗吗？向西望是夏口，向东望是武昌，山水环绕，一片苍翠，这不是曹孟德被周瑜围困的地方吗？当他攻破荆州，攻下江陵，顺流东下的时候，战船相连千里，旌旗遮蔽天空，在江边斟酒，横执长矛吟诗，本是一代枭雄，如今又在哪里呢？何况我和你在江中小洲打鱼砍柴，以鱼虾为伴，以麋鹿为友，驾着一叶小船，举起酒杯互相劝酒。像蜉蝣一样寄生在天地之间，渺小得像大海中的一粒粟。哀叹我们生命的短暂，羡慕长江的无穷无尽。想和飞仙一起遨游，和明月相拥而永存。知道这些不可能轻易得到，只能把箫声的余音寄托给悲凉的秋风。”\n我说：“你也知道那江水和月亮吗？江水像这样不断流逝，却并没有真正流走；月亮像那样时圆时缺，却终究没有增减。如果从变化的一面去看，天地间的万事万物，连一眨眼的工夫都不曾保持原样；从不变的一面去看，万物和我们都是永恒的，又有什么可羡慕的呢？况且天地之间，万物各有其主，如果不是我所有的，即使一丝一毫也不能索取。只有江上的清风，和山间的明月，耳朵听到就成为声音，眼睛看到就成为颜色，取之不尽，用之不竭，这是大自然无穷无尽的宝藏，是我和你可以共同享受的。”\n客人高兴地笑了，洗了酒杯重新斟酒。菜肴和果品都吃完了，杯子盘子杂乱地放着。大家互相枕着靠着睡在船中，不知不觉东方已经发白。",
    s: "《前赤壁赋》是宋代文赋的典范，苏轼借赤壁夜游，探讨了变与不变、短暂与永恒的哲学命题。全文写景、抒情、议论浑然一体，既有泛舟江上的诗意，又有通透豁达的人生智慧。“惟江上之清风，与山间之明月，耳得之而为声，目遇之而成色，取之无禁，用之不竭”成为千古名句，是中国古代散文中的不朽名篇。"
  },
  "秋声赋|欧阳修": {
    y: "欧阳先生夜里正在读书，听到有声音从西南方向传来，惊恐地侧耳倾听，说：“奇怪啊！”起初是淅淅沥沥的雨声夹杂着萧飒的风声，忽然奔腾澎湃起来，像波涛在夜间惊起，风雨突然到来。它碰到物体上，鏦鏦铮铮，像金属兵器相击；又像奔赴敌阵的士兵，衔枚快跑，听不到号令，只听到人马的行进声。我对童子说：“这是什么声音？你出去看看。”童子说：“星月皎洁，银河在天，四周没有人声，声音在树间。”\n我说：“唉，可悲啊！这是秋声，为什么而来呢？秋天的样子是：它的颜色惨淡，烟飞云收；它的容貌清明，天高气爽，阳光灿烂；它的气候寒冷，刺人肌骨；它的意境萧条，山川寂静。所以它发出的声音，凄凄切切，呼号奋发。茂盛的草碧绿繁茂，美好的树木葱茏可爱；可是草被秋风一吹就变色，树被秋风一刮就落叶。它之所以能摧败零落，是因为这一股肃杀之气的余威。秋天，是刑官，在时令上属阴；又是兵象，在五行中属金。这叫做天地的义气，常以肃杀为心。天对于万物，春生秋实，所以在音乐上，商声是西方的音，夷则是七月的律。商，就是伤，万物老了就悲伤；夷，就是戮，万物过盛就当杀。\n唉！草木无情，有时还要飘零。人是动物，是万物之灵；百忧触动他的心，万事劳累他的身体；心中有所触动，必然动摇他的精神。何况要思考他力量所不及的事，忧虑他智慧所不能的事；当然会使红润的容颜变成枯木，乌黑的头发变成花白。为什么要用不是金石的体质，想和草木争荣呢？想想是谁伤害了自己，又何必怨恨这秋声呢！”\n童子没有回答，低头睡着了。只听到四壁虫声唧唧，像在附和我的叹息。",
    s: "《秋声赋》是欧阳修的代表作，以秋声为线索，抒发了对人生的感慨。“草木无情，有时飘零。人为动物，惟物之灵”将草木与人对比，表达了对人生劳碌的感慨。全赋以无形的秋声为描写对象，想象丰富，描写生动，是宋代文赋的典范。"
  },
  "杂曲歌辞·行路难三首·二|李白": {
    y: "大道虽宽广如青天，唯独我没有出路。\n耻于追随长安城中的纨绔子弟，以赤鸡白雉赌梨栗为乐。\n像冯谖那样弹剑作歌，发出苦声，在王侯门下做食客，不合心意。\n淮阴市井之人嘲笑韩信，汉朝公卿嫉妒贾谊。\n你不见从前燕昭王重用郭隗，拿着扫帚扫地，屈身相待，毫无猜忌。\n剧辛、乐毅感恩图报，输肝剖胆效忠英才。\n如今昭王的白骨已缠绕蔓草，还有谁来打扫黄金台呢？\n行路难啊，归去来！",
    s: "《行路难·其二》是李白的名作，“大道如青天，我独不得出”以极强烈的对比，写出了怀才不遇的悲愤。全诗借古讽今，以燕昭王筑黄金台招贤的历史，讽刺了当朝统治者不重人才的现实，情感深沉，气势磅礴。"
  },
  "清平调词三首·三|李白": {
    y: "名花和倾国美人两相映衬，相得益彰，常使君王面带笑容观赏。\n春风中无限的怅恨都被消解，君王和贵妃在沉香亭北倚靠着栏杆。",
    s: "《清平调·其三》将名花与美人合写，“名花倾国两相欢”写出了花美与人美的交融，“解释春风无限恨”写出了君王与贵妃的恩爱。全诗辞藻华丽，意境优美，是李白七绝中的佳作。"
  },
  "渔父·一|张志和": {
    y: "西塞山前白鹭在自由地翱翔，江岸桃花盛开，江水中肥美的鳜鱼欢快地游来游去。\n渔翁头戴青色斗笠，身披绿色蓑衣，冒着斜风细雨，悠然自得地垂钓，连下了雨都不回家。",
    s: "《渔歌子》是张志和的代表作，描绘了一幅江南水乡的渔乐图。“青箬笠，绿蓑衣，斜风细雨不须归”写出了渔翁的悠闲自在，表达了诗人对隐居生活的向往。全词色彩明丽，意境优美，是小学课本中的经典篇目。"
  },
  "杂曲歌辞·忆江南·一|白居易": {
    y: "江南的风景多么美好，如画的风景久已熟悉。\n清晨日出的时候，江边盛开花朵颜色鲜红胜过火焰，碧绿的江水绿得胜过蓝草。\n怎能叫人不怀念江南？",
    s: "《忆江南》是白居易晚年回忆江南生活所作，“日出江花红胜火，春来江水绿如蓝”以鲜明的色彩对比，将江南春日的美景写得如诗如画，令人向往。全词语言明快，色彩绚丽，是描写江南的千古名篇。"
  }
};
